('BEBE PARA EL CUIDADO DE LA 3RA EDAD', 'LM-069', 1, 'MODELO PARA AYUDAR A LOS PACIENTES DE EDAD AVANZADA O CON DEMENCIA. PERMITE LOGRAR QUE LOS PACIENTES SE SIENTAN MAS EN CONFIANZA Y TENER UNA COMUNICACIÓN. EL BEBE ESTA FABRICADO DE MATERIAL SUAVE Y TIENE UN PESO MUY REALISTA. LAS MANOS Y LOS PIES SON FLEXIBLES PARA PERMITIR EL CAMBIO DE ROPA. LA CARA DEL BEBE ESTA DISEÑADA PARA PARECER FAMILIAR Y RECORDAR AL PACIENTE TIEMPOS FELICES PARA SU MAYOR ESTABLIDAD EMOCIONAL', NULL, 3, 1, 'A', 32, '2013-04-16 18:03:44', NULL, NULL, 114, NULL),
('MODELO PEDIATRICO DE 4 MESES DE EDAD', 'LM-075', 1, 'MODELO DE PACIENTE DE 4 MESES DE EDAD DE 6 KG APROXIMADAMENTE QUE PERMITE PRACTICAS COMO ALIMENTACION, ASISTIRLO, CARGARLO Y SENTARLO EN UNA SILLA DE BEBE', NULL, 3, 1, 'A', 32, '2013-04-16 18:04:44', NULL, NULL, 115, NULL),
('SIMULADOR DE CUIDADOS MULTIPROPOSITO DE PACIENTE', 'LM-079', 1, 'SIMULADOR DE CUERPO COMPLETO FEMENINOI MULTIFUNCIONAL DE CUIDADOS DE PACIENTE DISEÑADO DE MATERIAL SUAVE Y REALISTA. LOS DEDOS PUEDEN SER VENDADOS. EL CRANEO PRESENTA LOS HUESOS FRONTAL, CIGOMATICO Y DE LA MANDIBULA. PERMITE LA PRACTICA DE ENEMA, LAVADO DE ESTOMAGO E INTESTINAL, DUCHA VAGINAL, PUNCION INTRAMUSCULAR, CUIDADOS ORALES, LAVADO DE CABELLO, ASEO, POSICIONAMIENTO', NULL, 3, 1, 'A', 32, '2013-04-16 18:05:18', NULL, NULL, 116, NULL),
('MODELO TRANSPARENTE DE CAVIDAD NASAL', 'LM-005', 2, 'MODELO TRANSPARENTE DE LA ESTRUCTURA DE LA CAVIDAD NASAL. EL MODELO PUEDE DIVIDIRSE A LA MITAD DEL SEPTUM PARA VER LAS ESTRUCTURAS TANTO DERECHA COMO IZQUIERDA.', NULL, 3, 1, 'A', 32, '2013-04-16 18:06:48', NULL, NULL, 117, NULL),
('MODELO DE ENTRENAMIENTO PARA PALPACION E INSPECCION DE CANCER DE MAMA II', 'LM-017', 2, 'MODELO DE AUTOPALPACION Y AUTOEXPLORACION DE MAMAS PARA DETECCION DE SINTOMAS DE CANCER CON 5 BULTOS ANORMALES Y 1 DEPRESION. FABRICADO DE SILICON LO QUE DA UNA SENSACION REALISTA.', NULL, 3, 1, 'A', 32, '2013-04-16 18:07:22', NULL, NULL, 118, NULL),
('MODELO DE ENTRENAMIENTO PARA PALPACION E INSPECCION DE CANCER DE MAMA', 'LM-018', 2, 'MODELO CON VARIOS SINTOMAS PARA IDENTIFICACION Y PALPACION DE MAMAS COMO CANCER, INFLAMACION DE LOS LINFOMAS AUXILIARES, BULTOS ANORMALES, DEPRESION DEL PEZON Y CAMBIOS EN LA PIEL', NULL, 3, 1, 'A', 32, '2013-04-16 18:08:09', NULL, NULL, 119, NULL);
