('MODELO DE MASAJE Y EXPLORACION DE MAMA', 'LM-024', 2, 'MODELO FABRICADO EN MATERIAL SUAVE Y REALISTA QUE REPRESENTA LOS PECHOS DE UNA MUJER. PERMITE LA PRACTICA DE DISTINTAS TECNICAS COMO MASAJE DEL PECHO, DE LAS AUREOLAS Y LACTANCIA.', NULL, 3, 1, 'A', 32, '2013-04-16 18:08:54', NULL, NULL, 120, NULL),
('MODELO DE CATETERIZACION FEMENINA E INYECCION RECTAL', 'LM-025', 2, 'MODELO AUXILIAR PARA PRACTICA DE CATETERIZACION FEMENINA E INYECCION RECTAL EL CUAL PUEDE USAR UNA PERSONA O COLOCARLO A UN MANIQUI. LA FORMA ES MUY SIMILAR A LA DE UNA PERSONA REAL.', NULL, 3, 1, 'A', 32, '2013-04-16 18:09:33', NULL, NULL, 121, NULL),
('MODELO DE INYECCION INTRAMUSCULAR EN EL GLUTEO', 'LM-027', 2, '<p>MODELO REALISTA PARA PRACTICA DE INYECCION INTRAMUSCULAR. CUANDO LA PUNCION ES REALIZADA EN UN SITIO INADECUADA SE ACTIVA UNA ALARMA. LA SENSACION DE LA INSERCION DE LA AGUJA ES MUY REALISTA. LOS SITIOS DE INYECCION Y LA PIEL SON REEMPLAZABLES</p>', NULL, 3, 1, 'A', 32, '2013-04-16 18:10:18', 32, '2013-09-07 13:03:42', 122, '20130907_eb4fd2.pdf'),
('MODELO PARA PRACTICA DE PUNCION Y RECOLECCION DE MUESTRAS DE SANGRE', 'LM-028', 2, 'BRAZO FABRICADO DE SILICON ESPECIAL PARA PROPORCIONAR REALISMO. PERMITE LA PRACTICA DE PUNCION INTRAMUSCULAR, HIPODERMICA E INTRAVENOSA. ASI MISMO PERMITE LA TOMA DE MUESTRAS SANGUINEAS DEBIDO A QUE LA SANGRE CIRCULA POR EL BRAZO.', NULL, 3, 1, 'A', 32, '2013-04-16 18:10:55', NULL, NULL, 123, NULL),
('MODELO DE CATETERIZACION MASCULINA I', 'LM-029', 2, 'MODULO PARA LA PRACTICA DE LA CATETERIZACION MASCULINA FABRICADO DE SILICON ESPECIAL QUE PROPORCIONA UNA TEXTURA REALISTA. CUENTA CON UNA PORCION TRANSPARENTE DONDE SE PUEDEN OBSERVAR LA URETRA Y LA VEJIGA PARA UNA MEJOR ENSEÑANZA.', NULL, 3, 1, 'A', 32, '2013-04-16 18:11:31', NULL, NULL, 124, NULL),
('MODELO DE MASAJE Y EXPLORACION DE MAMA II', 'LM-045', 2, 'MODELO FABRICADO EN MATERIAL SUAVE Y REALISTA QUE REPRESENTA LOS PECHOS DE UNA MUJER. PERMITE LA PRACTICA DE DISTINTAS TECNICAS COMO MASAJE DEL PECHO, DE LAS AUREOLAS Y LACTANCIA. CUENTA CON CINTILLAS QUE PERMITEN A LA USUARIO COLOCARSELO Y PRACTICAR LA AUTOEXPLORACION', NULL, 3, 1, 'A', 32, '2013-04-16 18:12:07', NULL, NULL, 125, NULL),
('MODELO DE ENTRENAMIENTO PARA PALPACION PUERPERAL', 'LM-055', 2, 'MODELO DE TORSO FEMENINO QUE PERMITE LA PRACTICA DE PALPACION DEL FONDO UTERINO. LOS UTEROS REPRESENTAN 4 CONDICIONES DIFERENTES LAS CUALES PUEDEN IDENTIFICARSE A TRAVES DE LA PALAPACION. PUEDE PRACTICARSE EL CUIDADO Y EL LAVADO DE LA VULVA', NULL, 3, 1, 'A', 32, '2013-04-16 18:12:46', NULL, NULL, 126, NULL),
('MODELO DE INYECCION INTRAMUSCULAR EN EL GLUTEO II', 'LM-057', 2, '<p>MODELO REALISTA PARA PRACTICA DE INYECCION INTRAMUSCULAR. LOS SITIOS DE INYECCION CORRESPONDEN AL METODO DE MEDICION DE PUNTOS DE HOCHSTETTER Y CLARK. CUANDO LA PUNCION ES REALIZADA EN UN SITIO INADECUADA SE ACTIVA UNA ALARMA.</p>', NULL, 3, 1, 'A', 32, '2013-04-16 18:13:37', 32, '2013-09-07 13:06:15', 127, '20130907_5c5f32.pdf'),
('SET DE SIMULACION DE EDAD AVANZADA', 'LM-060', 2, '', NULL, 3, 1, 'A', 32, '2013-04-16 18:14:10', 32, '2013-09-07 13:06:46', 128, '20130907_83e30e.pdf'),
('MODELO DE CATETERIZACION URETRAL FEMENINA', 'LM-061', 2, 'MODELO DE TORSO INFERIOR FEMENINO ANATOMICAMENTE CORRECTO PARA LA PRACTICA DE LA CATETERIZACION FEMENINA. LA TURGENCIA DE LA VEJIGA PUEDE IDENTIFICARSE POR PALPACION. CUANDO EL CATETER ES INSERTADO POR LA URETRA Y ENTRA A LA VEJIGA, ORINA ARTIFICIAL FLUIRA DESDE EL CATETER COMO SI FUESE UNA PERSONA REAL', NULL, 3, 1, 'A', 32, '2013-04-16 18:14:57', NULL, NULL, 129, NULL),
('MODELO DE ENTRANAMIENTO PARA REALIZACION DE EDEMA', 'LM-068', 2, 'MODELO QUE SIMULA PACIENTES POSTRADOS EN CAMA O DE EDAD AVANZADA QUE TIENEN PROBLEMAS PARA ELIMINAR RESIDUOS POR SI MISMOS Y PERMITE LA REMOCION DE HECES SIMULADAS POR INSERCION DIGITAL. EL PROCEDIMIENTO DE ENEMA TAMBIEN PUEDE SER SIMULADO. LIQUIDO DE GLICERINA PUEDE SER SIMULADO. ABRIENDO LA CUBIERTA ABDOMINAL ES POSIBLE CORROBORAR LA CORRECTA REALIZACION DEL PROCEDIMIENTO.', NULL, 3, 1, 'A', 32, '2013-04-16 18:15:28', NULL, NULL, 130, NULL),
('BRAZO PARA ENTRENAMIENTO DE INYECCION', 'LM-074', 2, 'BRAZO PARA PRACTICA DE DISTINTOS TIPOS DE PUNCION COMO HIPODERMICA, INTRAMUSCULAR E INTRAVENOSA. LA SANGRE PRESURIZADA PUEDE PALPARSE EN LAS VENAS COMO SI SE TRATASE DE UN BRAZO HUMANO REAL.', NULL, 3, 1, 'A', 32, '2013-04-16 18:15:59', NULL, NULL, 131, NULL),
('MODELO DE LOS ORGANOS REPRODUCTIVOS FEMENINOS', 'LM-030', 3, 'MODELO DE LOS ORGANOS REPRODUCTIVOS FEMENINOS QUE PERMITE LA PRACTICA DE LA INSERCION DE DISPOSITIVOS ANTICONCEPTIVOS. FABRICADO DE SILICON QUE LE DA UNA SENSACION MAS REALISTA. EL MODELO PUEDE SEPARARSE POR LA MITAD PARA APRECIAR LAS ESTRUCTURAS DE LOS ORGANOS POR DENTRO.', NULL, 3, 1, 'A', 32, '2013-04-16 18:17:02', NULL, NULL, 132, NULL),
('MODELO DE MATERNIDAD TIPO-I', 'LM-043', 3, '<p>MODELO DE TORSO FEMENINO A TAMA&Ntilde;O REAL USADO PARA PRACTICAR LAS MANIOBRAS DE LEOPOLD, MONITORIZANDO LA FRECUENCIA CARDIACA FETAL Y REALIZANDO MEDICIONES ABDOMINALES. PERMITE REPROUCIR UNA SENSACION REALISTA A TRAVES DE AIRE EN LUGAR DEL LIQUIDO AMNIOTICO. EL VOLUMEN Y LA FRECUENCIA CARDIACA FETAL SON AJUSTABLES.</p>', NULL, 3, 1, 'A', 32, '2013-04-16 18:17:36', 32, '2013-09-07 13:12:34', 133, '20130907_20aab2.pdf'),
('MODELO DE ENTRENAMIENTO DE DIAGNOSTICO GINECOLOGICO', 'LM-050', 3, 'MODELO QUE PUEDE SER UTILIZADO PARA EL ENTRENAMIENTO Y LA INSTRUCCIÓN EN EL DIAGNOSTICO DE VARIOS ESTADOS Y ENFERMEDADES GINECOLOGICASASI COMO EN LA TOMA Y RECOLECCION DE MUESTRAS. LA EPIDERMIS, LA VAGINA Y EL ANO SON FABRICADOS DE UN MATERIAL QUE PERMITE OBTENER UNA IMPRESION MUY REALISTA. INCLUYE ORGANOS REPRODUCTIVOS INTERNOS ANORMALES Y NORMALES LOS CUALES SON FACILMENTE INTERCAMBIABLES. EL TAMAÑO DE LOS QUISTES PUEDE VARIAR AJUSTANDO LA CANTIDAD DE AIRE QUE CONTIENEN A TRAVES DE UNA BOMBA. LAS EXAMINACIONES Y PROCEDIMIENTOS QUE SE PUEDEN REALIZAR SON VAGINOSCOPIA, EXPLORACION BIMANUAL, EXAMINACION RECTAL, USO DE ESPECULO.', NULL, 3, 1, 'A', 32, '2013-04-16 18:18:12', NULL, NULL, 134, NULL),
('CHALECO DE SIMULACION DE MATERNIDAD', 'LM-054', 3, 'ESTE CHALECO DE SIMULACION ES IDEAL PARA EXPERIMENTAR LA VIDA Y ACTIVIDADES DE UNA MUJER EMBARAZADA, Y PERMITE EL APRENDIZAJE DE COMO ASISTIRLA.', NULL, 3, 1, 'A', 32, '2013-04-16 18:18:44', NULL, NULL, 135, NULL),
('SET DE MODELOS PARA PRACTICAS GINECOLOGICAS', 'LM-063A', 3, 'JUEGO PARA ENTRENAMIENTO Y ENSEÑANZA DE DISTINTAS TECNICAS GINECOLOGICAS, COMO EL DIAGNOSTICO EN LAS DISTINTAS ETAPAS DEL EMBARAZO, ASISTENCIA OBSTETRICA, REALIZACION DE EPISIOTOMIA. PERMITE LA PRACTICA DE LOS CONCEPTOS DEL EMBARAZO COMO LABOR, ALUMBRAMIENTO Y RECUPERACION.', NULL, 3, 1, 'A', 32, '2013-04-16 18:19:23', NULL, NULL, 136, NULL),
('SIMULADOR DE EMBARAZO DE CUERPO COMPLETO', 'LM-064', 3, '<p>SIMULADOR DE EMBARAZO DE CUERPO COMPLETO CON GENERACION DE SONIDOS CARDIACOS, MODELO PARA PALPACION ABDOMINAL, MODULO DE EXAMINACION VAGINAL CON 3 TIPOS DE DILATACION UTERINA. EL JUEGO DE ALUMBRAMIENTO CONSISTE EN EL FETO, LA PLACENTA, VULVA Y LUBRICANTE. MODELO DE REPARACION DE EPISIOTOMIA, ASI COMO UN MODULO DE PALPACION PUERPERAL. TAMBIEN PERMITE EL CUIDADO DE MAMA. FABRICADO DE MATERIAL REALISTA CON LIBERTAD DE MOVIMIENTO EN LAS ARTICULACIONES PARA COLOCACION EN DIFERENTES POSICIONES COMO SUPINO O LATERAL</p>', NULL, 3, 1, 'A', 32, '2013-04-16 18:19:58', 32, '2013-09-07 13:14:27', 137, '20130907_e7da3a.pdf'),
('CHALECO DE SIMULACION DE MATERNIDAD II', 'LM-065', 3, 'ESTE CHALECO DE SIMULACION ES IDEAL PARA EXPERIMENTAR LA VIDA Y ACTIVIDADES DE UNA MUJER EMBARAZADA, Y PERMITE EL APRENDIZAJE DE COMO ASISTIRLA. INCLUYE ESTUCHE Y ROPA DE MATERNIDAD', NULL, 3, 1, 'A', 32, '2013-04-16 18:20:30', NULL, NULL, 138, NULL),
('MODELO DE EXTRACCION DE CABEZA FETAL', 'LM-066', 3, 'MODELO AUXILIAR PARA LA EXTRACCION DE LA CABEZA FETAL EL CUAL PUEDE SER USADO CON EL MODELO LM-063. LA VELOCIDAD DE EXTRACCION ES AJUSTABLE Y LA CABEZA PUEDE EXTRAERSE SIN APLICAR FUERZA EXCESIVA', NULL, 3, 1, 'A', 32, '2013-04-16 18:21:12', NULL, NULL, 139, NULL),
('MODELO DE MATERNIDAD DE VERSION CEFALICA EXTERNA', 'LM-080', 3, '<p>MODELO DE TORSO FEMENINO A ESCALA REAL FABRICADO DE SILICON ESPECIAL PARA TENER UNA SENSACION REALISTA, UTILIZADO PARA PRACTICAR LA TECNICA DE VERSION CEFALICA EXTERNA (ROTACION DEL FETO), MEDICION PELVICA EXTERNA. EL VOLUMEN DEL LIQUIDO AMNIOTICO ES AJUSTABLE</p>', NULL, 3, 1, 'A', 32, '2013-04-16 18:21:47', 32, '2013-09-07 13:15:03', 140, '20130907_e5d70d.pdf'),
('MODELO DE ENTRENAMIENTO DE COLANGIOPANCREATOGRAFÍA RETRÓGRADA ENDOSCÓPICA TIPO E', 'LM-014', 4, 'ESTE MODELO OFRECE LA OPORTUNIDAD DE ENTRENAR Y ADQUIRIR LAS HABILIDADES EN EL USO DE DIFERENTES MODELOS DE FIBROSCOPIO DENTRO DEL ESOFAGO, ESTOMAGO, DUODENO Y EN LA PAPILA DE VATER. LA ORIENTACION DE LAS ESTRUCTURAS ANATOMICAS ES MUY REALISTA Y EXACTA.', NULL, 3, 1, 'A', 32, '2013-04-16 18:23:18', NULL, NULL, 141, NULL),
('PIEL PARA ENTRENAMIENTO QUIRURGICO', 'LM-021A', 4, 'REPRODUCCION DE UNA ESTRUCTURA DE PIEL PARA PRACTICA DE INCISION Y SUTURA. SENSACION REALISTA CUANDO EL ESCAPELO ES INSERTADO. LA CAPA DE SUTURA INTRADERMICA ES FACILMENTE DISTINGUIBLE POR SU COLOR BLANCO', NULL, 3, 1, 'A', 32, '2013-04-16 18:23:51', NULL, NULL, 142, NULL),
('MODELO DE ENTRENAMIENTO COLANGIOPANCREATOGRAFÍA RETRÓGRADA ENDOSCÓPICA TIPO E CON INDICADOR DE FUNCION', 'LM-022', 4, 'ESTE MODELO OFRECE LA OPORTUNIDAD DE ENTRENAR Y ADQUIRIR LAS HABILIDADES EN EL USO DE DIFERENTES MODELOS DE FIBROSCOPIO DENTRO DEL ESOFAGO, ESTOMAGO, DUODENO Y EN LA PAPILA DE VATER. LA ORIENTACION DE LAS ESTRUCTURAS ANATOMICAS ES MUY REALISTA Y EXACTA. CUENTA CON UNA FUNCION DE INDICACION DONDE MUESTRA SI CADA UNA DE LAS PORCIONES ES OBSERVADA EFECTIVAMENTE O NO, LO QUE PERMITE UNA ORIENTACION MAS EFECTIVA. SI EL PROCEDIMIENTO SE REAIIZA CORRECTAMENTE SE ENCENDERA UNA LAMPARA Y SE EMITIRA UN SONIDO', NULL, 3, 1, 'A', 32, '2013-04-16 18:24:24', NULL, NULL, 143, NULL),
('MODELO DE ENTRENAMIENTO DE COLONOSCOPIA', 'LM-044B', 4, 'MODELO PARA LA PRACTICA DE LA COLONOSCOPIA Y RECONOCIEMIENTO DE LA LOCALIZACION. FABRICADO EN MATERIAL SILICONIZADO, LO QUE PERMITE CONTAR CON UNA TEXTURA REALISTA AL COLON HUMANO. EN CASO DE QUE SE REQUIERA PRACTICAR LA PRESURIZACION EXTERNA SE PUEDE USAR LA CUBIERTA ESPECIAL. CUENTA CON LAS REGIONES DEL RECTO, COLON SIGMOIDEO, COLON DESCENDENTE, COLON TRANSVERSO E INTESTINO CIEGO', NULL, 3, 1, 'A', 32, '2013-04-16 18:25:03', NULL, NULL, 144, NULL),
('MODELO DE TRATAMIENTO DE ULCERAS DE DECUBITO', 'LM-078', 4, 'SET DE MODELOS QUE REPRODUCE ULCERAS DE DECUBITO FORMADAS EN LA REGION SACRA. EL SET CONSISTE DE 6 DIFERENTES PORCIONES DE PIEL QUE REPRESENTAN DIFERENTES ETAPAS DE DESARROLLO DE LA ULCERA. EL MODELO PUEDE SER USADO POR UNA PERSONA O MONTARSE EN UN MANIQUI', NULL, 3, 1, 'A', 32, '2013-04-16 18:25:35', NULL, NULL, 145, NULL),
('MODELO DE ENTRENAMIENTO DE DISECCION SUBMUCOSA ENDOSCOPICA', 'LM-083', 4, 'MODELO QUE REPRESENTA UN ESTOMAGO HUMANO PARA EL ENTRENAMIENTO DE DISECCION SUBMUCOSA ENDOSCOPICA. CONSIDERANDO LA OPERABILIDAD DEL ENDOSCOPIO, LA PARTE DE TRANSICION QUE VA DEL ESOFAGO AL ESTOMAGO ESTA FABRICADA DE RESINA SUAVE. ENTRENAMIENTO PRINCIPALMENTE EN LAS SIGUIENTES AREAS: PARED VESTIBULAR ANTERIOR, PARED VESTIBULAR POSTERIOR, GRAN CURVATURA EN EL ANGULO GASTRICO, CURVATURA DE LESSER Y GRAN CURVATURA EN EL CUERPO GASTRICO.', NULL, 3, 1, 'A', 32, '2013-04-16 18:26:13', NULL, NULL, 146, NULL),
('MODELO DE RECIEN NACIDO PARA PRACTICA DE CUIDADOS MULTIPROPOSITO', 'LM-026', 5, 'MANIQUÍ TAMAÑO REAL DE RECIÉN NACIDO MASCULINO PARA LA PRÁCTICA DE CUIDADOS MULTIPROPÓSITOS, FABRICADO DE SILICÓN ESPECIAL CON PROPORCIONA UNA APARIENCIA Y TEXTURA DE PIEL REALISTA, LA PIEL ES A PRUEBA DE AGUA', NULL, 3, 1, 'A', 32, '2013-04-16 18:27:45', NULL, NULL, 147, NULL),
('MODELO DE PREMATURO', 'LM-062', 5, 'MANIQUÍ TAMAÑO REAL DE PACIENTE MASCULINO PREMATURO DE 30 SEMANAS PARA PRÁCTICA DE CUIDADOS MULTIPROPÓSITOS, OBSERVACIÓN, MEDICIÓN Y EXPLORACIÓN FÍSICA, PALPACIÓN DE LA FONTANELA ANTERIOR, LIMPIEZA Y BAÑO DENTRO DE LA INCUBADORA, ASPIRACIÓN Y NUTRICIÓN POR SONDA', NULL, 3, 1, 'A', 32, '2013-04-16 18:28:15', NULL, NULL, 148, NULL),
('MODELO DE RECIEN NACIDO PREMATURA', 'LM-062', 5, 'MODELO TAMAÑO REAL DE RECIEN NACIDO PREMATURA FABRICADO DE SILICON ESPECIAL PARA PROPORCIONAR UNA SENSACION MAS REALISTA. PERMITE LA PRACTICA DE CUIDADOS MULTIPROPOSITOS COMO OBSERVACION Y MEDICION, PALPACION DE LA FONTANELA SUPERIOR, BAÑO Y ASPIRACION', NULL, 3, 1, 'A', 32, '2013-04-16 18:29:16', NULL, NULL, 149, NULL),
('MODELO DE RECIÉN NACIDO PARA PRÁCTICA DE CUIDADOS MULTIPROPÓSITOS', 'LM-082', 5, 'MANIQUÍ TAMAÑO REAL DE RECIÉN NACIDO MASCULINO PARA LA PRÁCTICA DE CUIDADOS MULTIPROPÓSITOS, FABRICADO DE SILICÓN ESPECIAL CON PROPORCIONA UNA APARIENCIA Y TEXTURA DE PIEL REALISTA, LA PIEL ES A PRUEBA DE AGUA', NULL, 3, 1, 'A', 32, '2013-04-16 18:29:56', NULL, NULL, 150, NULL),
('SIMULADOR DE SOPORTE DE VIDA AVANZADO TIPO II', 'LM-073', 8, 'SIMULADOR DE TAMAÑO COMPLETO PARA EL ENTRENAMIENTO DE TECNICAS DE SOPORTE DE VIDA AVANZADO. PERMITE EL MANEJO DE VIAS AEREAS DESDE OCLUSION DE LA LENGUA, INSERCION DE CANULAS ENDOTRAQUEALES, VENTILACION HASTA LA IDENTIFICACION DE LOS SONIDOS PULMONARES A TRAVES DE UN ESTETOSCOPIO. LA DESFIBRILACION Y EL MONITOREO DE ECG PUEDEN LLEVARSE A CABO CAMBIANDO LOS RITMOS Y LA FORMA DE ONDA. INFUSION Y PUNSION INTRAVENOSA PUEDE PRACTICARSE. CUENTA CON UN CONTROL PARA LA MODIFICACION DE LOS PARAMETROS DEL SIMULADOR COMO FRECUENCIA CARDIACA, LA FORMA DE ONDA DEL ECG Y EL PULSO DE LA ARTERIA CAROTIDEA', NULL, 3, 1, 'A', 32, '2013-04-16 18:30:40', NULL, NULL, 151, NULL),
('SIMULADOR DE SOPORTE DE VIDA AVANZADO TIPO III', 'LM-085', 8, 'MODELO DE ENTRENAMIENTO PARA SOPORTE DE VIDA CARDIOVASCULAR AVANZADO. LA SUPERFICIE DE LA CABEZA, LA CAVIDAD ORAL Y EL TORSO ESTAN FABRICADOS DE HULE DE SILICON LO QUE LE DA UNA SENSACION REALISTA. PERMITE EL MANEJO DE VIAS AEREAS COMO INTUBACION, VENTILACION Y VERIFICACION DE LOS SONIDOS RESPIRATORIOS CON EL USO DE UN ESTETOSCOPIO. PERMITE INFUNDIR FLUIDO A TRAVES DE UNAS MANGUERAS ESPECIALES UBICADAS EN LOS ANTEBRAZOS. DESFIBRILACION Y MONITOREO DE ECG SE PUEDEN LLEVAR A CABO. CUENTA CON UN CONTROL PARA LA MODIFICACION DE LOS PARAMETROS DEL SIMULADOR COMO FRECUENCIA CARDIACA, LA FORMA DE ONDA DEL ECG Y EL PULSO DE LA ARTERIA CAROTIDEA', NULL, 3, 1, 'A', 32, '2013-04-16 18:31:20', NULL, NULL, 152, NULL),
('MODELO DE MANEJO DE VÍAS AÉREAS', 'LM-059', 9, '<p>MODELO DE MANEJO DE VIAS AEREAS A TRAVES DE DIFERENTES TECNICAS COMO INTUBACION ENDOTRAQUEAL Y USO DE LARINGOSCOPIO. PRACTICA DE REMOCION DE OBJETOS EXTRA&Ntilde;OS DE LA VIA AREA CON LA AYDA DE FORSEPS ASI COMO CONFIMRACION DE SONIDOS RESPIRATORIOS. SENSACION REALISTA DE LA PIEL, LA CAVIDAD ORAL Y LA LENGUA. DILATACION DEL ESTOMAGO CUANDO EL AIRE ENTRA POR EL ESOFAGO. SE ACTIVA UNA ALARMA CUANDO EL LARINGOSCOPIO GENERA UNA PRESION EXCESIVA EN LOS DIENTES. LOS SONIDOS PULMONARES IZQUIERDO Y DERECHO PUEDEN ESCUCHARSE CON UN ESTETOSCOPIO ORDINARIO.</p>', NULL, 3, 1, 'A', 32, '2013-04-16 18:32:01', 32, '2013-09-07 13:17:21', 153, '20130907_bf0a25.pdf'),
('MODELO DE ENTRENAMIENTO DE ASPIRACION DE VIAS AEREAS', 'LM-070', 9, 'CABEZA PARA PRACTICA DE LA INSERCION DEL TUBO DE SUCCION POR LA CAVIDAD NASAL Y ORAL. PRMITE REMOVER UNA PORCION DE LA CARA PARA VISUALIZAR SI LA INSERCION DEL TUBO SE LLEVO A CABO DE MANERA CORRECTA Y APRENDER TODAS LAS ESTRUCTURAS ANATOMICAS COMO CAVIDAD NASAL, ORAL Y EL AREA CERVICAL.', NULL, 3, 1, 'A', 32, '2013-04-16 18:32:37', NULL, NULL, 154, NULL),
('MODELO DE ENTRENAMIENTO DE INTUBACION ENDOTRAQUEAL CON LARINGE INTERCAMBIABLE', 'LM-072', 10, 'MODELO PARA INTUBACION ENDOTRAQUEAL. CUANDO SE APLICA UNA PRESION EXCESIVA CON LA CANULA ENDOTRAQUEAL SOBRE LA LARINGE, LA MEMBRANA MUCOSA PUEDE DESPRENDERSE O DAÑARSE. DEPENDIENDO DEL DAÑO A LA LARINGE EL INSTRUCTR PUEDE DETERMINAR SI LA TECINICA DE INTUBACION HA SIDO REALIZADA CORRECTAMENTE', NULL, 3, 1, 'A', 32, '2013-04-16 18:33:37', NULL, NULL, 155, NULL),
('MODELO DE ENTRENAMIENTO DE INTUBACION ENDOTRAQUEAL CON EDEMA DE LENGUA', 'LM-076', 10, 'MODELO PARA INTUBACION ENDOTRAQUEAL CON RECREACION DE VARIOS TIPOS DE EDEMA PARA LA COMPLIACION DE LA MISMA. PERMITE LA RECREACION DE EDEMA DE LENGUA E INFLAMACION DE LA PARED POSTERIOR DE LA LARINGE.', NULL, 3, 1, 'A', 32, '2013-04-16 18:34:15', 32, '2013-04-16 18:34:53', 156, NULL),
('MODELO DE RESUCITACION NEONATAL', 'LM-089', 10, 'MANIQUI TAMAÑO REAL PARA PRACTICA DE RESICITACION CARDIOPULMONAR EN UN NEONATO. MOVIMIENTO TORACICO PUEDE OBSERVARSE CUANDO EL MANIQUI ES VENTILADO. ASPIRACION ORAL Y NASAL. COMPRESION DE PECHO Y CATETERIZACION UMBILICAL. MEDICION DEL LATIDO CARDIACO EN LA BASE DEL CORDON UMBILICAL PARA DETERMINACION DE LA FRECUENCIA. LOS PULSOS SON SIMULADOS A TRAVES DE UN MANGO', NULL, 3, 1, 'A', 32, '2013-04-16 18:35:22', NULL, NULL, 157, NULL),
('SIMULADOR DE PACIENTE DE CARDIOLOGÍA', 'M84-S', 16, '<p>SIMULADOR DE PACIENTE CARDIOL&Oacute;GICO PARA ENTRENAMIENTO CL&Iacute;NICO QUE FACILITA EL ENTRENAMIENTO EN LA AUSCULTACI&Oacute;N DE SONIDOS CARDIACOS Y MURMULLOS. CONTIENE SONIDOS PREGRABADOS DE PACIENTE REALES Y REPRODUCIDOS USANDO UN SISTEMA DE SONIDO DE ALTA CALIDAD, PERMITE EL USO DE UN ESTETOSCOPIO REAL. SITIOS DE AUSCULTACI&Oacute;N CORRESPONDIENTES A LA LOCALIZACI&Oacute;N PRECISA DE LAS V&Aacute;LVULAS DEL CORAZ&Oacute;N Y LOCALIZADOS EN UN TORSO DE TAMA&Ntilde;O REAL ADULTO. CONTIENE 88 CASOS DIVIDIDOS EN: 12 SONIDOS NORMALES, 14 ENFERMEDADES CARDIACAS, 10 ARRITMIAS Y 52 ARRITMIAS DE ECG. OBSERVACI&Oacute;N DE LAS VENAS YUGULARES BILATERALMENTE, PALPACI&Oacute;N DE LOS IMPULSOS CARDIACOS, PALPACI&Oacute;N DE LAS ARTERIAS BILATERALMENTE, SONIDOS CARDIACOS ESCUCHADOS EN LOS 4 SITIOS DE AUSCULTACI&Oacute;N PRIMARIOS</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:37:19', 32, '2013-09-07 13:50:46', 158, '20130907_143641.pdf'),
('MODELO DE ENTRENAMIENTO DE COLONOSCOPÍA', 'M40', 2, '<p>SISTEMA DE ENTRENAMIENTO DE COLONOSCOPIA QUE PERMITE LA EXAMINACI&Oacute;N DE UNA GRAN VARIEDAD DE CASOS QUE VAN DESDE LOS MAS SENCILLOS A LOS MAS COMPLEJOS. EL TUBO DEL COLON PERMITE LA INSUFLACI&Oacute;N Y LA SUCCI&Oacute;N, EL ESF&Iacute;NTER ANAL PERMITE SU MANIPULACI&Oacute;N, EL SIMULADOR PUEDE SER ORIENTADO EN POSICI&Oacute;N LATERAL IZQUIERDA, LATERAL DERECHA O SUPINA. PERMITE LA PRACTICA DE COMPRESI&Oacute;N ABDOMINAL.</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:37:55', 32, '2013-09-07 13:44:13', 159, '20130907_b694c8.pdf'),
('SIMULADOR DE PUNCIÓN LUMBAR', 'M43B', 2, '<p>SIMULADOR PARA LA REALIZACI&Oacute;N DE LA PUNCI&Oacute;N LUMBAR, CON REFERENCIAS ANAT&Oacute;MICAS REALISTAS, SENSACI&Oacute;N REAL DE LA RESISTENCIA A LA PUNCI&Oacute;N DE LA PIEL Y DEL TEJIDO, PERMITE RECOLECCI&Oacute;N DE FLUIDO Y MEDICI&Oacute;N DE LA PRESI&Oacute;N DEL FLUIDO BAJO CONDICIONES CL&Iacute;NICAS REALISTAS</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:38:27', 32, '2013-09-07 13:44:24', 160, '20130907_98e043.pdf'),
('SIMULADOR PARA PUNCIÓN INTRAVENOSA', 'M50B', 2, '<p>BRAZO Y MANOS DE ENTRENAMIENTO DE INYECCI&Oacute;N QUE PERMITE LA PR&Aacute;CTICA EN TRES VENAS: BAS&Iacute;LICA, ANTE BRAQUIAL MEDIA Y CEF&Aacute;LICA. SENSACI&Oacute;N NATURAL AL TACTO Y RESISTENCIA EN LOS SITIOS DE INYECCI&Oacute;N QUE PERMITEN PALPAR LAS VENAS COMO LAS DE UN PACIENTE REAL</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:39:10', 32, '2013-09-07 13:44:36', 161, '20130907_18de46.pdf'),
('SIMULADOR PARA EXAMEN DE PRÓSTATA', 'M53B', 2, '<p>SIMULADOR DE EXAMINACI&Oacute;N DE PR&Oacute;STATA, QUE CONSISTE EN UN TORSO INFERIOR MASCULINO DONDE EL ANO Y EL RECTO EST&Aacute;N CONSTRUIDOS CON MATERIALES REALISTAS, INCLUYE 10 TIPOS DE PR&Oacute;STATAS QUE PUEDEN SER INTERCAMBIADAS F&Aacute;CILMENTE UTILIZANDO UN SISTEMA ROTATORIO. INCLUYE 2 CASOS DE PR&Oacute;STATAS NORMALES, 2 CASOS DE ALARGAMIENTO DE LA GL&Aacute;NDULA PROST&Aacute;TICA, UN CASO DE INFLAMACI&Oacute;N DE LA PR&Oacute;STATA Y 5 CASOS CON CARCINOMA. PERMITE LA EXAMINACI&Oacute;N DESDE 3 POSICIONES, SUPINA, PRONA Y LATERAL</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:40:01', 32, '2013-09-07 13:44:47', 162, '20130907_502ca4.pdf'),
('SIMULADOR DE PACIENTE DE AUSCULTACIÓN PULMONAR', 'M81-S', 2, '<p>SIMULADOR PARA AUSCULTACI&Oacute;N DE SONIDOS PULMONARES CON CASOS GRABADOS DE PACIENTES REALES. CUENTA CON LA LOCALIZACI&Oacute;N EXACTA DE LOS SONIDOS PULMONARES, CON 7 BOCINAS EN LA PARTE ANTERIOR Y 8 EN LA PARTE POSTERIOR. EL TORSO ROTA DE LA BASE, PERMITIENDO UNA EXAMINACI&Oacute;N TANTO DE LA PARTE ANTERIOR COMO LA POSTERIOR. LOS SONIDOS PUEDEN SER MONITORIZADOS GR&Aacute;FICAMENTE Y EN TIEMPO REAL, EL VOLUMEN DEL SONIDO, EL RITMO DE LA RESPIRACI&Oacute;N Y EL TIEMPO DE OPERACI&Oacute;N SON AJUSTABLES. PERMITE EL USO DE UN ESTETOSCOPIO REAL. SISTEMA DE AUDIO CON ALTAVOCES. INCLUYE 36 CASOS DE SONIDOS DIVIDIDOS EN: NORMALES, ANORMALES, SONIDOS CREPITANTES, SIBILANCIAS, RONQUIDOS, MISCEL&Aacute;NEOS CONTINUOS Y MISCEL&Aacute;NEOS</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:40:38', 32, '2013-09-07 13:44:59', 163, '20130907_fb5c14.pdf'),
('SIMULADOR DE EXAMINACIÓN DE FONDO DE OJO.', 'M82', 2, '<p>SIMULADOR DE TORSO CON CABEZA DE TAMA&Ntilde;O ADULTO DISE&Ntilde;ADO PARA LA EXAMINACI&Oacute;N DE FONDO DE OJO CON AYUDA DEL OFTALMOSCOPIO, DISE&Ntilde;ADO CON MATERIAL SUAVE Y REALISTA PARA EL USO CON CUALQUIER TIPO DE OFTALMOSCOPIO, DI&Aacute;METRO DE LA PUPILA INTERCAMBIABLE. LA PROFUNDIDAD DE LAS DIAPOSITIVAS DEL FONDO DE OJO SE PUEDEN AJUSTAR EN TRES PASOS QUE MUESTRA LAS DIFERENCIAS ENTRE LAS VISTAS HIPERM&Eacute;TROPES, NORMALES Y MIOPES</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:41:32', 32, '2013-09-07 13:45:12', 164, '20130907_8de849.pdf'),
('SIMULADOR DE PACIENTE PARA AUSCULTACIÓN CARDIACA Y PULMONAR', 'M8481-S', 2, '<p>SISTEMA SIMULADOR QUE CONSISTE EN DOS MANIQU&Iacute;S EL M84-S Y EL MS81-1, UNO PARA AUSCULTACI&Oacute;N, PALPACI&Oacute;N Y OBSERVACI&Oacute;N DE SONIDOS CARDIACOS Y OTRO PARA AUSCULTACI&Oacute;N DE SONIDOS RESPIRATORIOS</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:42:09', 32, '2013-09-07 13:46:45', 165, '20130907_9cef57.pdf'),
('ENTRENADOR DE ASPIRACIÓN DE VÍAS AÉREAS', 'M85', 2, '<p>SISTEMA ENTRENADOR CON SENSACI&Oacute;N REALISTA PARA LA PR&Aacute;CTICA DE PROCEDIMIENTOS DE ASPIRACI&Oacute;N DE LAS V&Iacute;AS A&Eacute;REAS. CUENTA CON 3 RUTAS DE CAT&Eacute;TER: ORAL, FARINGE Y APERTURA DE TRAQUEOTOM&Iacute;A, LAS V&Iacute;AS A&Eacute;REAS Y EL MOVIMIENTO DEL CAT&Eacute;TER PUEDEN SER VISTOS A TRAV&Eacute;S DEL LADO TRANSPARENTE DEL SIMULADOR</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:42:53', 32, '2013-09-07 13:46:57', 166, '20130907_190dee.pdf'),
('PAD ENTRENADOR DE VENOPUNCIÓN', 'M87', 2, '<p>SISTEMA DE ENTRENAMIENTO DE VENOPUNCI&Oacute;N CON TRES L&Iacute;NEAS, DOS NORMALES Y UNA DELGADA. TEJIDO REALISTA Y RESISTENCIA DE LA PARED DE LA VENA REALISTA</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:43:27', 32, '2013-09-07 13:47:06', 167, '20130907_e9fc93.pdf'),
('SIMULADOR DE EXAMINACIÓN DE OÍDO', 'M88', 2, '<p>SIMULADOR DISE&Ntilde;ADO PARA EL ENTRENAMIENTO DE LA EXAMINACI&Oacute;N DEL CANAL AUDITIVO EXTERNO Y LA MEMBRANA TIMP&Aacute;NICA, DISE&Ntilde;ADO CON MATERIAL SUAVE Y REALISTA, PUEDE SER USADO CON CUALQUIER TIPO DE OTOSCOPIO. INCLUYE SET CON 10 CASOS CL&Iacute;NICOS Y UN CASO PARA REMOCI&Oacute;N DE CUERPOS EXTRA&Ntilde;OS</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:43:59', 32, '2013-09-07 13:47:14', 168, '20130907_559014.pdf'),
('SIMULADOR PARA EXAMEN RECTAL', 'M92', 2, '<p>SIMULADOR DE EXAMINACI&Oacute;N DE RECTO DISE&Ntilde;ADO PARA AYUDAR AL ENTRENAMIENTO EN LA DIFERENCIACI&Oacute;N DE DIFERENTES ENFERMEDADES RECTALES A TRAV&Eacute;S DE LA PALPACI&Oacute;N, CON 4 UNIDADES INTERCAMBIABLES DE RECTO CON DIFERENTES CASOS, 1 NORMAL, 2 CANCERES RECTALES, 1 RECTO CON P&Oacute;LIPOS</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:44:34', 32, '2013-09-07 13:47:26', 169, '20130907_e6ddb3.pdf'),
('SIMULADOR DE INSERCIÓN DE CATÉTER VENOSO CENTRAL', 'M93UB', 2, '<p>SIMULADOR CON UNA ESTRUCTURA ANAT&Oacute;MICA CORRECTA QUE INCLUYE HUESOS, VENAS, ARTERIAS Y LA PARTE SUPERIOR DEL PULM&Oacute;N PARA LA INSERCI&Oacute;N DE CAT&Eacute;TER VENOSO CENTRAL A TRAV&Eacute;S DEL ESPACIO SUBCLAVIO O EL ESPACIO YUGULAR INTERNO</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:45:08', 32, '2013-09-07 13:49:34', 170, '20130907_cfb01c.pdf'),
('SIMULADOR PARA INYECCIÓN INTRADÉRMICA', 'M94', 2, '<p>EL SIMULADOR PROVEE ENTRENAMIENTO DE LA INYECCI&Oacute;N INTRAD&Eacute;RMICA DE LA PARTE INFERIOR DEL ANTEBRAZO. RESISTENCIA Y SENSACI&Oacute;N REALISTA, TAMA&Ntilde;O REAL QUE AYUDA EN EL ENTRENAMIENTO PARA ENCONTRAR EL &Aacute;NGULO DE INYECCI&Oacute;N ADECUADO</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:45:42', 32, '2013-09-07 13:49:42', 171, '20130907_6edbcf.pdf'),
('SIMULADOR PARA PUNCIÓN ARTERIAL EN LA MUÑECA', 'M99', 2, '<p>SISTEMA SIMULADOR CONSISTENTE EN UN BRAZO PARA LA PR&Aacute;CTICA DE LA PUNCI&Oacute;N ARTERIAL. EL PULSO ARTERIAL ES PALPABLE, EL TEJIDO PRESENTA UNA RESISTENCIA REAL A LA PUNCI&Oacute;N, RETROALIMENTACI&Oacute;N NATURAL A TRAV&Eacute;S DE SANGRE ARTIFICIAL, NO QUEDAN MARCAS DEL SITIO DONDE SE REALIZO LA PUNCI&Oacute;N.</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:46:18', 32, '2013-09-07 13:49:50', 172, '20130907_1cc410.pdf'),
('SIMULADOR DE PUNCIÓN LUMBAR PEDIÁTRICO', 'M43C', 5, 'SIMULADOR PEDIÁTRICO PARA LA REALIZACIÓN DE LA PUNCIÓN LUMBAR, CON REFERENCIAS ANATÓMICAS REALISTAS, SENSACIÓN REAL DE LA RESISTENCIA A LA PUNCIÓN DE LA PIEL Y DEL TEJIDO, PERMITE RECOLECCIÓN DE FLUIDO Y MEDICIÓN DE LA PRESIÓN DEL FLUIDO BAJO CONDICIONES CLÍNICAS REALISTAS', NULL, 4, 1, 'A', 32, '2013-04-16 18:47:39', NULL, NULL, 173, NULL),
('SIMULADOR DE EXAMINACIÓN DE SIGNOS VITALES EN RECIÉN NACIDO', 'M58', 5, '<p>MANIQU&Iacute; TAMA&Ntilde;O REAL DE RECI&Eacute;N NACIDO PARA LA PR&Aacute;CTICA DE LA EXAMINACI&Oacute;N DE LOS SIGNOS VITALES, PERMITE LA AUSCULTACI&Oacute;N DE SONIDOS CARDIACOS, PULSOS ARTERIALES EN LAS MU&Ntilde;ECAS, CUELLO Y FONTANELAS, PULSO TEMPORAL SUPERFICIAL, CAROTIDEO Y RADIAL BILATERALMENTE, MEDICI&Oacute;N DE TEMPERATURA RECTAL</p>', NULL, 4, 1, 'A', 32, '2013-04-16 18:48:15', 32, '2013-09-07 13:50:29', 174, '20130907_931ebb.pdf'),
('SISTEMA ENTRENADOR DE AUSCULTACIÓN', 'LF01142U', 16, 'SIMULADOR ESENCIAL PARA LA PRÁCTICA Y EL ENTRENAMIENTO DE HABILIDADES EN LA AUSCULTACIÓN DE SONIDOS DEL CORAZÓN Y DEL PULMÓN, CON ÁREAS DE AUSCULTACIÓN INVISIBLES, SIN ALTAVOCES INTERNOS, TOTALMENTE INALÁMBRICOS, SEÑALES PALPABLES, CONTROL REMOTO, SONIDOS DE CORAZÓN Y PULMÓN VARÍAN DE ACUERDO AL SITIO DE AUSCULTACIÓN', NULL, 5, 1, 'E', 32, '2013-04-18 14:28:04', 1, '2018-02-08 00:18:34', 175, NULL),
('ESTACIÓN DE ENTRENAMIENTO EN AUSCULTACIÓN DE LUJO', 'LF01200U', 16, 'ESENCIAL PARA LA PRÁCTICA Y EL ENTRENAMIENTO DE HABILIDADES EN LA AUSCULTACIÓN DE SONIDOS DEL CORAZÓN Y DEL PULMÓN. INCLUYE ENTRENADOR DE AUSCULTACIÓN Y SMARTSCOPE, SISTEMA AMPLIFICADOS CON ALTAVOZ, TABLERO DE PRÁCTICAS DE AUSCULTACIÓN POSTERIOR Y ANTERIOR', NULL, 5, 1, 'E', 32, '2013-04-18 14:28:45', 1, '2018-02-08 00:18:19', 176, NULL),
('ESTACIÓN COMPLETA DE ENTRENAMIENTO EN AUSCULTACIÓN', 'LF01191U', 15, 'ESTACIÓN PARA ENTRENAMIENTO DE AUSCULTACIÓN QUE INCLUYE UN TABLERO DE PRACTICAS PARA AUSCULTACIÓN ANTERIOR Y UN TORSO DE AUSCULTACIÓN. LOS SONIDOS SON GENERADOS A TRAVÉS DEL DISPOSITIVO SMARTSCOPE QUE CONSISTE EN UN ESTETOSCOPIO CON UN AMPLIFICADOR. INCLUYE CONTROL REMOTO PARA MANEJO INALÁMBRICO', NULL, 5, 1, 'E', 32, '2013-04-18 14:29:24', 1, '2018-02-08 00:29:45', 177, NULL),
('TABLERO INDIVIDUAL DE PRACTICAS DE AUSCULTACIÓN POSTERIOR', 'LF01199U', 15, 'TABLERO DE AUSCULTACIÓN QUE PRESENTA 12 PUNTOS POSTERIORES DEL PULMÓN: 6 SUPERIORES, 4 INFERIORES Y 2 AXILARES MEDIOS. INCLUYE TABLERO DE 41 X 51 CM, PARCHES ADHESIVOS, FUNDA DE VINIL, CABALLETE E INSTRUCCIONES. NO INCLUYE SISTEMA SMARTSCOPE NI CONTROL REMOTO', NULL, 5, 1, 'E', 32, '2013-04-18 14:29:56', 1, '2018-02-08 00:22:29', 178, NULL),
('MANIQUÍ PARA AUSCULTACIÓN GERI', 'LF04003U', 15, 'MANIQUÍ PARA CUIDADOS DE PACIENTE Y AUSCULTACIÓN GERIÁTRICO BÁSICO QUE PERMITE EL POSICIONAMIENTO DEL PACIENTE, CON FLEXIBILIDAD Y RANGO SUPERIOR DE MOVIMIENTO. VISUALMENTE REALISTAS, PERMITEN CUIDADOS COMO VENDAJES, ADMINISTRACIÓN DE EDEMAS, IRRIGACIÓN OCULAR, CUIDADO GASTROSTÓMICO, CUIDADO DE CABELLO, FROTIS CERVICAL Y DUCHAS VAGINALES, EXAMEN PROSTÁTICO. NO CUENTA CON LOS DEPÓSITOS INTERNOS DE FLUIDOS. CUENTA CON LA ADICIÓN DE SITIOS DE AUSCULTACIÓN CON SONIDOS CARDIACOS Y PULMONARES. CON MENÚ DE 12 PATOLOGÍAS CARDIACAS Y PULMONARES MEDIANTE CONTROL REMOTO. FUNCIONA A TRAVÉS DEL SISTEMA DE ESTETOSCOPIO SMARTSCOPE', NULL, 5, 1, 'E', 32, '2013-04-18 14:30:30', 1, '2018-02-08 00:22:50', 179, NULL),
('MANIQUÍ DE AUSCULTACIÓN KERI', 'LF04023U', 15, 'MANIQUÍ PARA CUIDADOS DE PACIENTE Y AUSCULTACIÓN ADULTO BÁSICO QUE PERMITE EL POSICIONAMIENTO DEL PACIENTE, CON FLEXIBILIDAD Y RANGO SUPERIOR DE MOVIMIENTO. VISUALMENTE REALISTAS, PERMITEN CUIDADOS COMO VENDAJES, ADMINISTRACIÓN DE EDEMAS, IRRIGACIÓN OCULAR, CUIDADO GASTROSTÓMICO, CUIDADO DE CABELLO, FROTIS CERVICAL Y DUCHAS VAGINALES, EXAMEN PROSTÁTICO. NO CUENTA CON LOS DEPÓSITOS INTERNOS DE FLUIDOS. CUENTA CON LA ADICIÓN DE SITIOS DE AUSCULTACIÓN CON SONIDOS CARDIACOS Y PULMONARES. CON MENÚ DE 12 PATOLOGÍAS CARDIACAS Y PULMONARES MEDIANTE CONTROL REMOTO. FUNCIONA A TRAVÉS DEL SISTEMA DE ESTETOSCOPIO SMARTSCOPE', NULL, 5, 1, 'E', 32, '2013-04-18 14:31:15', 1, '2018-02-08 00:22:37', 180, NULL),
('SIMULADOR DE VENDAJE QUIRÚRGICOS', 'LF00929U', 1, 'TORSO CON 14 HERIDAS QUIRÚRGICAS QUE INCLUYEN UNA HENDIDURA ESTERNAL MEDIA CON DOS DRENAJES SIMULADOS, UNA ULCERA DE DECÚBITO DE SACRO Y UN MUÑÓN DE AMPUTACIÓN DE PIERNA. LOS CIERRES DE HERIDA PRESENTAN GRAPAS QUIRÚRGICAS PARA LA HENDIDURA ESTERNAL MEDIA, TORACOTOMÍA, NEFRECTOMÍA, TORACOTOMÍA, LAPAROTOMÍA, HISTERECTOMÍA ABDOMINAL. LAS GRAPAS Y SUTURAS NO SE PUEDEN QUITAR', NULL, 5, 1, 'E', 32, '2013-04-18 14:32:08', 1, '2018-02-08 00:17:33', 181, NULL),
('PIE DE ANCIANO CON ULCERAS POR PRESIÓN', 'LF00933', 1, 'PIE DE ANCIANO CON ULCERAS POR PRESIÓN PARA LA INSTRUCCIÓN SOBRE EL CUIDADO Y LIMPIEZA DE LAS ULCERAS POR PRESIÓN EN SUS VARIAS ETAPAS. CONTIENE 4 ZONAS DE GRAVEDAD, LOCALIZADA BAJO EL DEDO GORDO, BAJO LA ARTICULACIÓN DONDE NACE EL DEDO GORDO, EN EL LADO EXTERNO DEL PIE Y EN EL TALÓN', NULL, 5, 1, 'E', 32, '2013-04-18 14:32:44', 1, '2018-02-08 00:18:17', 182, NULL),
('JUEGO DE ENTRENAMIENTO PARA PRACTICA DE SUTURA Y ENGRAPADO', 'LF01031U', 1, 'SISTEMA DE ENTRENAMIENTO CONSISTENTE EN UN BRAZO Y PIERNA HUMANA DE TAMAÑO ADULTO PARA LA PRÁCTICA DE LA TÉCNICA DE LA SUTURA Y ENGRAPADO PARA TRATAMIENTO DE HERIDAS, FABRICADO CON PIEL SUAVE DE VINIL SOBRE UN NÚCLEO DE ESPUMA QUE PROPORCIONAN UNA EXPERIENCIA DE SUTURA COMO EN LA VIDA REAL, TEXTURA REALISTA DE LA PIEL CON ARRUGAS, POROS, Y LAS HUELLAS DACTILARES VISIBLES', NULL, 5, 1, 'E', 32, '2013-04-18 14:33:18', 1, '2018-02-08 00:18:30', 183, NULL),
('SIMULADOR DE VENDAJE DE MUÑÓN', 'LF01065U', 1, 'TORSO INFERIOR Y SUPERIOR PARA PRÁCTICA DE VENDAJE DE MUÑONES, PRÁCTICA Y DEMOSTRACIÓN DE PROCEDIMIENTOS DE VENDAJE, EL TORSO INFERIOR ES LO SUFICIENTEMENTE LARGO PARA PERMITIR LLEVAR EL VENDAJE ALREDEDOR DEL CUERPO SOBRE LA CADERA AL NIVEL DE LA CRESTA ILÍACA, AMBOS TORSOS, INFERIOR Y SUPERIOR, PUEDEN SER USADOS PARA DEMOSTRAR LA COLOCACIÓN DE DISPOSITIVOS PROSTÉTICOS, EL TORSO SUPERIOR INCLUYE DOS BRAZOS, UNO CON AMPUTACIÓN ARRIBA DEL CODO Y OTRO UNA AMPUTACIÓN ARRIBA DE LA MUÑECA, LA COMPRESIBILIDAD DEL MATERIAL ES MUY SIMILAR A LA QUE PRESENTARÍA UN PACIENTE REAL', NULL, 5, 1, 'E', 32, '2013-04-18 14:33:51', 1, '2018-02-08 00:18:59', 184, NULL),
