('MANIQUÍ BÁSICO KERI ADULTO', 'LF04021U', 1, 'MANIQUÍ PARA CUIDADOS DE PACIENTE ADULTO BÁSICO QUE PERMITE EL POSICIONAMIENTO DEL PACIENTE, CON FLEXIBILIDAD Y RANGO SUPERIOR DE MOVIMIENTO. VISUALMENTE REALISTAS, PERMITEN CUIDADOS COMO VENDAJES, ADMINISTRACIÓN DE EDEMAS, IRRIGACIÓN OCULAR, CUIDADO GASTROSTÓMICO, CUIDADO DE CABELLO, FROTIS CERVICAL Y DUCHAS VAGINALES, EXAMEN PROSTÁTICO. NO CUENTA CON LOS DEPÓSITOS INTERNOS DE FLUIDOS.', NULL, 5, 1, 'E', 32, '2013-04-18 14:37:30', 1, '2018-02-08 00:19:12', 189, NULL),
('MANIQUÍ AVANZADO KERI', 'LF04022U', 1, 'MANIQUÍ DE PACIENTE SIN EDAD EN ESPECÍFICO QUE PUEDE CONVERTIRSE TANTO EN PACIENTE MASCULINO COMO EN FEMENINO PARA PRÁCTICA DE DIFERENTES PROCEDIMIENTOS', NULL, 5, 1, 'E', 32, '2013-04-18 14:38:03', 1, '2018-02-08 00:21:39', 190, NULL),
('MANIQUÍ AVANZADO GERI', 'LF04030U', 1, 'MANIQUÍ DE PACIENTE GERIÁTRICO CON RANGO COMPLETO DE MOVIMIENTOS, COMPLETAMENTE FUNCIONAL Y VISUALMENTE MUY REALISTA PARA PRACTICA DE DIFERENTES TÉCNICAS DE CUIDADOS DE PACIENTE. CON BRAZO PARA PUNCIÓN IV, PARA TOMA DE PRESIÓN, ENTRENAMIENTO DE INYECCIONES INTRAMUSCULARES', NULL, 5, 1, 'E', 32, '2013-04-18 14:38:32', 1, '2018-02-08 00:22:02', 191, NULL),
('MANIQUÍ BÁSICO GERI', 'LF04040U', 1, 'MANIQUÍ PARA CUIDADOS DE PACIENTE GERIÁTRICO BÁSICO QUE PERMITE EL POSICIONAMIENTO DEL PACIENTE, CON FLEXIBILIDAD Y RANGO SUPERIOR DE MOVIMIENTO. VISUALMENTE REALISTAS, PERMITEN CUIDADOS COMO VENDAJES, ADMINISTRACIÓN DE EDEMAS, IRRIGACIÓN OCULAR, CUIDADO GASTROSTÓMICO, CUIDADO DE CABELLO, FROTIS CERVICAL Y DUCHAS VAGINALES, EXAMEN PROSTÁTICO. NO CUENTA CON LOS DEPÓSITOS INTERNOS DE FLUIDOS.', NULL, 5, 1, 'E', 32, '2013-04-18 14:39:04', 1, '2018-02-08 00:21:19', 192, NULL),
('BRAZO DE ENTRENAMIENTO PARA INYECCIÓN Y VENOPUNCIÓN EN ADULTOS EN TONALIDAD BLANCA', 'LF00698U', 2, 'SIMULADOR IDEAL PARA ENSEÑANZA DE TÉCNICAS DE PUNCIÓN DE VENAS E INTRODUCCIÓN DE CATÉTERES, CON ANATOMÍA REALISTA QUE INCLUYE HUELLAS DACTILARES. LA PIEL SE PLIEGA AL PALPAR LA VENA Y SE PERCIBE EL CARACTERÍSTICO CHASQUIDO CONFORME LA AGUJA PENETRA LA VENA. ES POSIBLE ACCEDER A LAS VENAS DESDE EL PLIEGUE ANTERIOR DEL CODO, A LO LARGO DEL ANTEBRAZO Y EN EL DORSO DE LA MANO. PERMITE TAMBIÉN LA PRACTICA DE INYECCIÓN INTRAMUSCULAR', NULL, 5, 1, 'E', 32, '2013-04-18 14:40:16', 1, '2018-02-08 00:18:42', 193, NULL),
('ENTRENADOR DE MANO PORTÁTIL PARA PUNCIÓN IV DE TONALIDAD BLANCA', 'LF00700U', 2, 'SISTEMA SIMULADOR QUE INCLUYE LO NECESARIO PARA EL ENTRENAMIENTO DE IV, FABRICADO DE MATERIAL SUAVE CON VENAS REALISTAS VISIBLES Y PALPABLES. ACCESO A LA VENA EN EL DORSO DE LA MANO Y LAS VENAS DEL PULGAR. SE SIENTE EL CHASQUIDO DE LA AGUJA AL PENETRAR LA AGUJA', NULL, 5, 1, 'E', 32, '2013-04-18 14:40:50', 1, '2018-02-08 00:21:49', 194, NULL),
('ENTRENADOR DE BRAZO PORTÁTIL PARA PUNCIÓN IV DE TONALIDAD BLANCA', 'LF00701U', 2, 'SISTEMA SIMULADOR QUE INCLUYE LO NECESARIO PARA EL ENTRENAMIENTO DE IV, FABRICADO DE MATERIAL SUAVE CON VENAS REALISTAS VISIBLES Y PALPABLES. ACCESO A LA VENA EN EL PLIEGUE DEL CODO, EN EL ANTEBRAZO. SE SIENTE EL CHASQUIDO DE LA AGUJA AL PENETRAR LA AGUJA', NULL, 5, 1, 'E', 32, '2013-04-18 14:41:23', 1, '2018-02-08 00:19:22', 195, NULL),
('ENTRENADOR DE BRAZO Y MANO PORTÁTIL PARA PUNCIÓN IV DE TONALIDAD BLANCA', 'LF00702U', 2, 'SISTEMA SIMULADOR QUE INCLUYE LO NECESARIO PARA EL ENTRENAMIENTO DE IV, FABRICADO DE MATERIAL SUAVE CON VENAS REALISTAS VISIBLES Y PALPABLES. ACCESO A LA VENA EN EL PLIEGUE DEL CODO, EN EL ANTEBRAZO, EL DORSO DE LA MANO Y LAS VENAS DEL PULGAR. SE SIENTE EL CHASQUIDO DE LA AGUJA AL PENETRAR LA AGUJA', NULL, 5, 1, 'E', 32, '2013-04-18 14:42:10', 1, '2018-02-08 00:25:42', 196, NULL),
('ENTRENADOR DE MANO PORTÁTIL PARA PUNCIÓN IV DE TONALIDAD OSCURA', 'LF00703U', 2, 'SISTEMA SIMULADOR QUE INCLUYE LO NECESARIO PARA EL ENTRENAMIENTO DE IV, FABRICADO DE MATERIAL SUAVE CON VENAS REALISTAS VISIBLES Y PALPABLES. ACCESO A LA VENA EN EL DORSO DE LA MANO Y LAS VENAS DEL PULGAR. SE SIENTE EL CHASQUIDO DE LA AGUJA AL PENETRAR LA AGUJA', NULL, 5, 1, 'E', 32, '2013-04-18 14:42:56', 1, '2018-02-08 00:23:32', 197, NULL),
('ENTRENADOR DE BRAZO PORTÁTIL PARA PUNCIÓN IV DE TONALIDAD OSCURA', 'LF00704U', 2, 'SISTEMA SIMULADOR QUE INCLUYE LO NECESARIO PARA EL ENTRENAMIENTO DE IV, FABRICADO DE MATERIAL SUAVE CON VENAS REALISTAS VISIBLES Y PALPABLES. ACCESO A LA VENA EN EL PLIEGUE DEL CODO, EN EL ANTEBRAZO. SE SIENTE EL CHASQUIDO DE LA AGUJA AL PENETRAR LA AGUJA', NULL, 5, 1, 'E', 32, '2013-04-18 14:43:26', 1, '2018-02-08 00:20:56', 198, NULL),
('ENTRENADOR DE BRAZO Y MANO PORTÁTIL PARA PUNCIÓN IV DE TONALIDAD OSCURA', 'LF00705U', 2, 'SISTEMA SIMULADOR QUE INCLUYE LO NECESARIO PARA EL ENTRENAMIENTO DE IV, FABRICADO DE MATERIAL SUAVE CON VENAS REALISTAS VISIBLES Y PALPABLES. ACCESO A LA VENA EN EL PLIEGUE DEL CODO, EN EL ANTEBRAZO, EL DORSO DE LA MANO Y LAS VENAS DEL PULGAR. SE SIENTE EL CHASQUIDO DE LA AGUJA AL PENETRAR LA AGUJA', NULL, 5, 1, 'E', 32, '2013-04-18 14:44:01', 1, '2018-02-08 00:20:47', 199, NULL),
('SIMULADOR DE CATETERIZACIÓN MASCULINO', 'LF00855U', 2, 'EL SIMULADOR PERMITE LA INSERCIÓN DE UNA SONDA LUBRICADA EN EL ORIFICIO URETRAL Y PASARLO HASTA LA VEJIGA. CUANDO LA VEJIGA RECIBE LA SONDA, LA ORINA ARTIFICIAL COMIENZA A FLUIR POR EL CATÉTER. SE SENTIRÁN LAS RESTRICCIONES NORMALES CAUSADAS POR LOS PLIEGUES MUCOSOS, LA URETRA BULBOSA Y EL ESFÍNTER URETRAL INTERNO, JUSTO ANTES DE LA ENTRADA DE LA VEJIGA', NULL, 5, 1, 'E', 32, '2013-04-18 14:44:36', 1, '2018-02-08 00:21:08', 200, NULL),
('SIMULADOR DE CATETERIZACIÓN PARA MUJERES', 'LF00856U', 2, 'EL SIMULADOR SE HA DISEÑADO CON UN ESPACIO PARA LA VEJIGA, LA URETRA, Y UNA VÁLVULA QUE SIMULA EL ESFÍNTER URETRAL INTERNO. LA SENSACIÓN NORMAL DE RESISTENCIA Y PRESIÓN SERÁ LA MISMA CUANDO PASE EL CATÉTER A TRAVÉS DE LA URETRA Y POR EL ESFÍNTER HASTA LA VEJIGA. CUANDO LA SONDA PENETRE LA VEJIGA, LA ORINA ARTIFICIAL BAJARA POR LA SONDA COMO OCURRIRÍA CON UN PACIENTE REAL. LOS GENITALES EXTERNOS Y EL PERINEO SE HAN MOLDEADO CON MODELOS REALES. LOS LABIOS MENORES PUEDEN APARTARSE DE MANERA NATURAL PARA MOSTRAR EL CLÍTORIS, EL INTROITO URETRAL Y EL VAGINAL', NULL, 5, 1, 'E', 32, '2013-04-18 14:45:09', 1, '2018-02-08 00:26:09', 201, NULL),
('SET DE SIMULACIÓN DE CATETERISMO MASCULINO/FEMENINO', 'LF00857U', 2, 'JUEGO DE SIMULADORES MASCULINO (LF00855U) Y FEMENINO (LF00856U) QUE PERMITEN LA DEMOSTRACIÓN Y PRACTICA DEL PROCEDIMIENTO DE CATETERISMO URINARIO. TAMBIÉN ES ÚTIL PARA LA IDENTIFICACIÓN ANATÓMICA Y DEMOSTRACIÓN DEL CUIDADO DEL PERINEO', NULL, 5, 1, 'E', 32, '2013-04-18 14:45:56', 1, '2018-02-08 00:27:18', 202, NULL),
('SIMULADOR DE EXAMINADOR DE PRÓSTATA', 'LF00901U', 2, 'TORSO CUATRO GLÁNDULAS PROSTÁTICAS SEPARADAS QUE REPRESENTAN UNA GLÁNDULA BENIGNA Y TRES DE CARCINOMA PROSTÁTICO EN DIFERENTES ETAPAS, CADA GLÁNDULA PUEDE INSERTARSE EN EL TORSO PARA PERMITIR UNA PRÁCTICA DEL DIAGNÓSTICO MEDIANTE LA PALPACIÓN RECTAL.', NULL, 5, 1, 'E', 32, '2013-04-18 14:46:34', 1, '2018-02-08 00:27:26', 203, NULL),
('ENTRENADOR DE OSTOMÍA INFANTIL', 'LF00905U', 2, 'ENTRENADOR DISEÑADO PARA ENSEÑANZA DE LOS CUIDADOS DE OSTOMÍA EN UN PACIENTE PEDIÁTRICO. LA ANATOMÍA DE LOS COLOSTOMÍAS FUE REPRODUCIDA PARA DAR MAYOR REALISMO A SU ASPECTO Y FUNCIONES. SE EMPLEA MATERIAL SUAVE Y FLEXIBLE PARA DAR REALISMO A LOS ESTOMAS. LAS JERINGAS QUE SE INCLUYEN SE USAN PARA INYECTAR HECES SIMULADAS A TRAVÉS DE LAS ABERTURAS DE LA COLOSTOMÍA. LAS ÁREAS DE LAS COLOSTOMÍAS PUEDEN IRRIGARSE', NULL, 5, 1, 'E', 32, '2013-04-18 14:47:10', 1, '2018-02-08 00:20:18', 204, NULL),
('SIMULADOR DE OSTOMÍA', 'LF00906U', 2, 'SIMULADOR DISEÑADO PARA INTRODUCIR LOS ASPECTOS ESENCIALES DEL CUIDADO OSMÓTICO. LA ANATOMÍA DE UNA COLOSTOMÍA Y DE UNA ILEOSTOMÍA SE REPRODUCE CON CUIDADO. PUEDE PRACTICARSE LA DILATACIÓN DE LOS ESTOMAS, JUNTO CON LA APLICACIÓN DE BOLSAS OSMÓTICAS POSTOPERATORIAS Y PERMANENTES. LA COLOSTOMÍA PUEDE IRRIGARSE. SE INCLUYEN JERINGAS PARA INYECTAR MATERIALES A TRAVÉS DE LA UNIDAD PARA DRENAR Y EXCRETAR EN CASOS DE ILEOSTOMÍA Y COLOSTOMÍA', NULL, 5, 1, 'E', 32, '2013-04-18 14:47:58', 1, '2018-02-08 00:20:28', 205, NULL),
('MODELO DE PIEL CON ULCERAS DE PRESIÓN', 'LF00934U', 2, 'MODELO QUE ILUSTRA 4 ETAPAS DE HERIDA POR ULCERA Y SE UTILIZAN PARA DAR INSTRUCCIONES DE CUIDADO Y LIMPIEZA DE LAS MISMAS, LAS HERIDAS PUEDEN IR DESDE SUPERFICIALES Y LIGERAMENTE ROJAS HASTA UNA INFECCIÓN EXTREMA, PROFUNDA Y CON HERIDA ABIERTA HASTA EL HUESO JUNTO CON TEJIDO NECROSADO', NULL, 5, 1, 'E', 32, '2013-04-18 14:48:30', 1, '2018-02-08 00:28:56', 206, NULL),
('SIMULADOR DE APLICACIÓN DE ENEMAS', 'LF00957U', 2, 'SIMULADOR PARA LA ENSEÑANZA DE LOS PROCEDIMIENTOS DE ADMINISTRACIÓN DE ENEMAS, LOS CUALES PUEDEN SEGUIRSE UN APARATO TRADICIONAL, PUES NO SE REQUIERE EQUIPO ESPECIAL. LA PARTE SUPERIOR DEL GLÚTEO ES FLEXIBLE DE MODO QUE EL ESTUDIANTE DEBE SUBIRLE PARA LOCALIZAR EL ANO Y HACER LA INSERCIÓN', NULL, 5, 1, 'E', 32, '2013-04-18 14:49:02', 1, '2018-02-08 00:20:36', 207, NULL),
('BRAZO PEDIÁTRICO', 'LF00958U', 2, 'SIMULADOR REALISTA QUE PERMITE PRACTICAR Y APRENDER LAS TÉCNICAS RELATIVA A LA TERAPIA IV EN NIÑOS. PROVEE SENSACIÓN Y RESPUESTA REALISTA. PIEL DE VINIL QUE AL PALPARLA FACILITA LA UBICACIÓN DE LA VENA. UNA ESPUMA SUAVE SIMULA EL MUSCULO DELTOIDES Y PERMITE AL ESTUDIANTE LA PRACTICA DE INYECCIONES INTRAMUSCULARES', NULL, 5, 1, 'E', 32, '2013-04-18 14:49:34', 1, '2018-02-08 00:29:05', 208, NULL),
('SIMULADOR DE INYECCIÓN INTRAMUSCULAR', 'LF00961U', 2, 'SIMULADOR QUE OFRECE APRENDIZAJE TANTO VISUAL COMO TÁCTIL. DENTRO DEL TORSO HAY UNA ESTRUCTURA ÓSEA SIMULADA Y REPRESENTA EL EXTREMO SUPERIOR DEL FÉMUR O TROCÁNTER MAYOR, LAS ESPINAS ILIACAS ANTERO-POSTERIOR Y EL SACRO. LA ESTRUCTURA ÓSEA OFRECE MARCAS ANATÓMICAS PALPABLES PARA QUE LOS ESTUDIANTES PUEDAN IDENTIFICAR LOS SITIOS DE INYECCIÓN. UNA SECCIÓN DEL CUADRANTE SUPERIOR EXTERNO DEL ÁREA DEL GLÚTEO IZQUIERDO SE QUITA PARA EXPONER LAS ESTRUCTURAS. LOS MÚSCULOS GLÚTEOS MEDIO Y MÁXIMO , EL NERVIO CIÁTICO Y LAS ESTRUCTURAS VASCULARES SE VEN CON CLARIDAD. SE PUEDEN ENSEÑAR Y PRACTICAR 3 TIPOS DE PUNCIONES INTRAMUSCULARES: DORSOGLUTEAL, VENTROGLUTEAL Y VASTUS LATERALIS', NULL, 5, 1, 'E', 32, '2013-04-18 14:50:10', 1, '2018-02-08 00:22:27', 209, NULL),
('BRAZO PARA PUNCIÓN ARTERIAL', 'LF00995U', 2, 'SIMULADOR DE BRAZO DE TAMAÑO ADULTO PARA LA PRÁCTICA DEL PROCEDIMIENTO DE PUNCIÓN ARTERIAL, IDEAL PARA LA PRÁCTICA Y DEMOSTRACIÓN EN LA TOMA DE MUESTRAS DE SANGRE ARTERIAL PARA EL CONTROL DE GASES, PERMITE LA IDENTIFICACIÓN DE LOS LUGARES DE PUNCIÓN A TRAVÉS DE LA PALPACIÓN DEL PULSO EN CUALQUIERA DE LOS SITIOS RADIAL O BRAQUIAL, LA PRESIÓN ARTERIAL REALISTA PRODUCE UN REFLUJO REALISTA DE SANGRE EN LA JERINGA, LO QUE CONFIRMA UBICACIÓN CORRECTA DE LA AGUJA EN LA ARTERIA', NULL, 5, 1, 'E', 32, '2013-04-18 14:51:01', 1, '2018-02-08 00:23:54', 210, NULL),
('BRAZO DE ENTRENAMIENTO PARA INYECCIÓN Y VENOPUNCIÓN EN ADULTOS EN TONALIDAD OSCURA', 'LF00997U', 2, 'SIMULADOR IDEAL PARA ENSEÑANZA DE TÉCNICAS DE PUNCIÓN DE VENAS E INTRODUCCIÓN DE CATÉTERES, CON ANATOMÍA REALISTA QUE INCLUYE HUELLAS DACTILARES. LA PIEL SE PLIEGA AL PALPAR LA VENA Y SE PERCIBE EL CARACTERÍSTICO CHASQUIDO CONFORME LA AGUJA PENETRA LA VENA. ES POSIBLE ACCEDER A LAS VENAS DESDE EL PLIEGUE ANTERIOR DEL CODO, A LO LARGO DEL ANTEBRAZO Y EN EL DORSO DE LA MANO. PERMITE TAMBIÉN LA PRACTICA DE INYECCIÓN INTRAMUSCULAR', NULL, 5, 1, 'E', 32, '2013-04-18 14:51:36', 1, '2018-02-08 00:22:18', 211, NULL),
('BRAZO DE PRIMEROS AUXILIOS', 'LF01005U', 2, 'BRAZO DE PRIMEROS AUXILIOS CON ASPECTO REAL Y FUNCIONAL PARA PRACTICAS VEROSÍMILES. CON SENSACIÓN REALISTA, PUEDE FLUIR SANGRE DE UNA CORTADA EN ANTEBRAZO, UNA CORTADA GRAVE HASTA AMPUTACIÓN DEL PULGAR. LA AMPUTACIÓN DEL PULGAR PERMITE LA PRACTICA EN EL CUIDADO POR SEPARADO DE LOS DEMÁS DEDOS DE LA MANO. PUEDE REGULAR EL FLUJO DE LA HEMORRAGIA SEA VENOSA O ARTERIAL. LOS PUNTOS DE PRESIÓN ARTERIAL FUNCIONAN DE MANERA REAL EN LA MUÑECA Y EL BRAZO', NULL, 5, 1, 'E', 32, '2013-04-18 14:52:12', 1, '2018-02-08 00:22:11', 212, NULL),
('SIMULADOR DE INYECCIÓN INTRADÉRMICA', 'LF01008U', 2, 'CONSTA DE UNA PIEZA MOLDEADA A PARTIR DE UN ANTEBRAZO REAL, DE LA MUÑECA A DEBAJO DEL CODO. LA PIEL OFRECE ASPECTOS Y SENSACIONES REALES. EL BRAZO PRESENTA 8 PUNTOS PARA PRACTICAR INYECCIONES INTERCUTÁNEAS. SI EL FLUIDO ES INYECTADO ADECUADAMENTE SE FORMA UN VERDUGÓN EL CUAL SE QUITA EXTRAYENDO EL LIQUIDO TRAS LA PRÁCTICA', NULL, 5, 1, 'E', 32, '2013-04-18 14:52:47', 1, '2018-02-08 00:22:38', 213, NULL),
('SIMULADOR DE CATETERISMO CARDIACO PARA NUTRICIÓN PARENTERAL TOTAL Y CATETERISMO VENOSO CENTRAL', 'LF01012U', 2, 'SIMULADOR QUE CUENTA CON MARCAS PALPABLES PARA IDENTIFICAR LOS PUNTOS DE INSERCIÓN PARA EL CATÉTER VENOSO CENTRAL. PERMITE LA PRACTICA DEL CUIDADO DEL PUNTO DE PUNCIÓN Y LA ADMINISTRACIÓN PARENTERAL DE FLUIDOS, COMO MEDIR LA PRESIÓN VENOSA CENTRAL, LA ENTREGA DE GRANDES VOLÚMENES DE FLUIDOS EN TRAUMA Y LA INYECCIÓN DE ACCIÓN RÁPIDA', NULL, 5, 1, 'E', 32, '2013-04-18 14:53:21', 1, '2018-02-08 00:23:13', 214, NULL),
('SIMULADOR PARA EXAMEN ÓTICO', 'LF01019U', 2, 'SIMULADOR QUE PERMITE EL EXAMEN DE OÍDO. MOLDEADO PARA REPLICAR CON EXACTITUD EL ASPECTO FÍSICO Y LAS DIMENSIONES INTERNAS Y EXTERNAS, LAS OREJAS REMOVIBLES SE CAMBIAN FÁCILMENTE. CUENTA CON DIAPOSITIVAS A TODO COLOR DE LA MEMBRANA TIMPÁNICA A TAMAÑO NATURAL DAN LAS VISTAS REALISTAS QUE SE TIENEN CON UN PACIENTE REAL. CON PIEL DE TEXTURA FLEXIBLE, EJERCICIOS DE IRRIGACIÓN Y DE LIMPIEZA.', NULL, 5, 1, 'E', 32, '2013-04-18 14:53:56', 1, '2018-02-08 00:24:19', 215, NULL),
('SIMULADOR CATH-ED 1, MASCULINO', 'LF01025U', 2, 'SIMULADOR MASCULINO QUE COMBINA EL APRENDIZAJE VISUAL Y TÁCTIL DE LA CATETERIZACIÓN E UNA UNIDAD COMPACTA. LA DISECCIÓN MEDIA SAGITAL PERMITE EL ESTUDIO DE LA ANATOMÍA INTERNA Y OFRECE LA OPORTUNIDAD DE VER QUE SUCEDE CUANDO SE CATETERIZA A UN PACIENTE. PUEDEN DETECTARSE E IDENTIFICARSE LAS RESTRICCIONES NORMALES EN LA URETRA BULBOSA Y EN EL ESFÍNTER DE LA VEJIGA', NULL, 5, 1, 'E', 32, '2013-04-18 14:54:29', 1, '2018-02-08 00:23:03', 216, NULL),
('SIMULADOR CATH-ED 2, FEMENINO', 'LF01026U', 2, 'SIMULADOR FEMENINO QUE COMBINA EL APRENDIZAJE VISUAL Y TÁCTIL DE LA CATETERIZACIÓN E UNA UNIDAD COMPACTA. LA DISECCIÓN MEDIA SAGITAL PERMITE EL ESTUDIO DE LA ANATOMÍA INTERNA Y OFRECE LA OPORTUNIDAD DE VER QUE SUCEDE CUANDO SE CATETERIZA A UN PACIENTE. LA VULVA HA SIDO MOLDEADA COMPLETA PARA FACILITAR LA IDENTIFICACIÓN DE LA URETRA Y LA APERTURA CORRECTA DE LOS LABIOS. SE HA INCORPORADO UNA VEJIGA FUNCIONAL PARA PERMITIR QUE BAJE LA ORINA CUANDO SE INSERTA CORRECTAMENTE LA SONDA', NULL, 5, 1, 'E', 32, '2013-04-18 14:55:06', 1, '2018-02-08 00:22:46', 217, NULL),
('SIMULADOR DE DIÁLISIS PERITONEAL CONTINUA', 'LF01027U', 2, 'DISEÑADO PARA INTRODUCIR A PACIENTES, ESTUDIANTES Y PERSONAL MEDICO EN LOS FUNDAMENTOS DE LOS PROCEDIMIENTOS Y ASISTENCIA PARA LA DIÁLISIS PERITONEAL AMBULATORIA CONTINUA', NULL, 5, 1, 'E', 32, '2013-04-18 14:55:42', 1, '2018-02-08 00:24:03', 218, NULL),
('BRAZO PARA PRACTICA DE SUTURA', 'LF01028U', 2, 'BRAZO FABRICADO DE SUAVE VINIL QUE SIMULA UNA TEXTURA DE PIEL REALISTA, CON ARRUGAS, POROS Y HUELLAS DIGITALES. CON TRES HERIDAS QUE PUEDEN SUTURARSE REPETIDAMENTE. PUEDEN REALIZARSE MAS DE 1000 CORTES', NULL, 5, 1, 'E', 32, '2013-04-18 14:57:01', 1, '2018-02-08 00:22:54', 219, NULL),
('PIERNA PARA PRACTICA DE SUTURA', 'LF01034U', 2, 'PIERNA FABRICADA DE SUAVE VINIL QUE SIMULA UNA TEXTURA DE PIEL REALISTA, CON ARRUGAS, POROS Y HUELLAS DIGITALES. CON TRES HERIDAS QUE PUEDEN SUTURARSE REPETIDAMENTE. PUEDEN REALIZARSE MAS DE 1000 CORTES', NULL, 5, 1, 'E', 32, '2013-04-18 14:57:38', 1, '2018-02-08 00:23:24', 220, NULL),
('SIMULADOR DE INYECCIÓN ESPINAL', 'LF01036U', 2, 'SIMULADOR QUE PERMITE LA PRACTICA REALISTA DE TODAS LAS INYECCIONES EN LA COLUMNA VERTEBRAL, QUE INCLUYEN LA ANESTESIA, PUNCIONES, ANALGESIA EPIDURAL, ANALGESIA CAUDAL Y BLOQUEO DEL NERVIO SACRO Y LUMBAR. EXCELENTES CARACTERÍSTICAS REALISTAS. PUEDE CARGARSE CON FLUIDOS Y ACOMODARSE EN POSICIÓN DE SENTADO O LATERAL', NULL, 5, 1, 'E', 32, '2013-04-18 14:58:11', 1, '2018-02-08 00:23:46', 221, NULL);
