('BRAZO PARA PRACTICA DE HEMODIÁLISIS', 'LF01037U', 2, 'SIMULADOR PARA PRACTICA DE PREPARACIÓN DEL BRAZO PARA HEMODIÁLISIS QUE OFRECE UN ASPECTO REAL CON ACCESO A UNA FISTULA IMPLANTADA Y EL SISTEMA PUEDE PRESURIZARSE CON SANGRE ARTIFICIAL DE MODO QUE OCURRA UN RETORNO CUANDO SE INTRODUCE UNA AGUJA', NULL, 5, 1, 'E', 32, '2013-04-18 14:58:50', 1, '2018-02-08 00:27:08', 222, NULL),
('KIT DE SUTURA', 'LF01042U', 2, 'KIT QUE OFRECE LA PRACTICA DE SUTURAS Y OTRAS HABILIDADES NECESARIAS PARA CERRAR HERIDAS, COMO INCISIONES, DETERMINACIÓN DE LA PROFUNDIDAD DE UNA HERIDA. PERMITE LA PRACTICA DE COMO HACER NUDOS, COSER Y SUJETAR PROFUNDO Y SUBCUTÁNEO. MUESTRA LAS CAPAS DE LA EPIDERMIS, DERMIS, TEJIDO, GRASA Y MUSCULO. LA PIEL PERMITE REALIZAR SUTURAS SUPERFICIALES', NULL, 5, 1, 'E', 32, '2013-04-18 14:59:26', 1, '2018-02-08 00:24:34', 223, NULL),
('EQUIPO DE ENTRENAMIENTO DE EPISIOTOMÍA Y LACERACIÓN PERINEAL', 'LF01044U', 2, 'SIMULADOR OBSTÉTRICO QUE PERMITE REALIZAR INCISIONES PARA CREAR UNA EPISIOTOMÍA TRADICIONAL O CASI CUALQUIER TIPO DE LACERACIONES DE 1ER A 4TO GRADO. INCRUSTADAS EN EL TEJIDO HAY UNAS DISCRETAS ESTRUCTURAS QUE REPRESENTAN EL MUSCULO BULBO CAVERNOSO, EL MUSCULO PERINEAL TRANSVERSAL Y EL ESFÍNTER DEL ANO, LOS CUALES PUEDEN CORTARSE Y REPARARSE. INCLUYE INSTRUMENTAL DE DISECCIÓN EN ESTUCHE DE CARTERA, HILO DE SUTURA CON AGUJA CURVA Y ESTUCHE SUAVE PARA TRASLADO', NULL, 5, 1, 'E', 32, '2013-04-18 15:00:03', 1, '2018-02-08 00:22:58', 224, NULL),
