INSERT INTO `productos` (`titulo`, `sku`, `categoria`, `descripcion`, `precio`, `marca`, `uso`, `estado`, `created_by`, `created_at`, `updated_by`, `updated_at`, `id`, `ficha`) VALUES
('TORSO ENTRENADOR DE MANEJO DE VÍA AÉREA DE NIÑO', 'LF03674U', 10, 'TORSO QUE SIMULA UN NIÑO DE 8 AÑOS PARA PRACTICA DE PROCEDIMIENTOS DE RCP E INTUBACIÓN. LAS REFERENCIAS Y LA ANATOMÍA REALISTAS INCLUYEN DIENTES, BOCA, LENGUA, FARINGE, LARINGE, EPIGLOTIS, ARITENOIDEOS, CUERDAS VOCALES, TRÁQUEA, PULMONES, ESÓFAGO Y ESTOMAGO. PRACTICA DE INTUBACIÓN, VENTILACIÓN, SUCCIÓN Y RCP', NULL, 5, 1, 'E', 32, '2013-04-18 16:16:58', 1, '2018-02-08 00:21:13', 331, NULL),
('MANIQUÍ BÁSICO NIÑO CRISIS', 'LF03765U', 10, 'MANIQUÍ DE NIÑO DE 8 AÑOS ANATÓMICAMENTE CORRECTO PARA ENTRENAMIENTO Y PRACTICA DE MANEJO DE VÍA AÉREA Y RCP. INCLUYE LENGUA, FARINGE, LARINGE, EPIGLOTIS, CUERDAS VOCALES, TRÁQUEA Y ESÓFAGO. CABEZA, CUELLO Y MANDÍBULA ARTICULADOS. PULMONES IZQUIERDO Y DERECHO SEPARADOS PARA AUSCULTACIÓN. CAPACIDAD DE INTUBACIÓN ORAL, NASAL Y DIGITAL. INCLUYE UNA VEJIGA INFLABLE EN EL ESTOMAGO PARA INDICAR INSUFLACIÓN ESOFÁGICA', NULL, 5, 1, 'E', 32, '2013-04-18 16:17:34', 1, '2018-02-08 00:21:23', 332, NULL),
('SIMULADOR DE PERICARDIOCENTESIS', 'LF03769U', 10, 'SIMULADOR DISEÑADO PARA ENSEÑAR EL PROCEDIMIENTO DE PERICARDIOCENTESIS, EL MANTENIMIENTO DEL TUBO TORÁCICO Y EL MANEJO DEL TRAUMATISMO TORÁCICO PRE HOSPITALARIO. CUENTA CON UN PUNTO DE NEUMOTÓRAX A TENSIÓN PRESURIZADO Y PUNTO PARA LA COLOCACIÓN QUIRÚRGICA DE UN TUBO TORÁCICO FUNCIONAL. LA PERICARDIOCENTESIS PUEDE REALIZARSE EN EL ESPACIO SUBXIFOIDEO IZQUIERDO Y EN EL QUINTO ESPACIO INTERCOSTAL IZQUIERDO', NULL, 5, 1, 'E', 32, '2013-04-18 16:18:19', 1, '2018-02-08 00:30:59', 333, NULL),
('MANIQUÍ CON TUBO TORÁCICO', 'LF03770U', 10, 'SIMULADOR DISEÑADO PARA ENSEÑAR TEORÍA, ANATOMÍA Y HABILIDADES PARA MANEJAR TRAUMATISMO TORÁCICO PRE HOSPITALARIO Y EL MANTENIMIENTO DEL TUBO TORÁCICO EN CURSO. EL LADO DERECHO TIENE DOS ZONAS QUE PERMITEN VER LAS RELACIONES ANATÓMICAS DE PIEL, MUSCULATURA, COSTILLAS Y PULMONES. EL LADO IZQUIERDO TIENE UN PUNTO DE NEUMOTÓRAX PRESURIZADO PARA LIBERAR EL AIRE ACUMULADO EN EL ESPACIO PLEURAL Y QUE RESTRINGE EL INFLADO DEL PULMÓN. TIENE UN PUNTO EN QUE LOS TUBOS TORÁCICOS PUEDEN COLOCARSE QUIRÚRGICAMENTE PARA TRATAR EL DERRAME PLEURAL DRENANDO LOS FLUIDOS. SE CONTROLA COLOR, VOLUMEN Y VISCOSIDAD DEL FLUIDO', NULL, 5, 1, 'E', 32, '2013-04-18 16:18:51', 1, '2018-02-08 00:21:29', 334, NULL),
('MANIQUÍ DE TORSO CRISIS', 'LF03957U', 10, 'TORSO PARA PRACTICAS DE MANEJO DE VÍAS AÉREAS, PIEL DE TÓRAX PARA ENSAYO DE DESFIBRILACIÓN, COMPRESIONES DE RCP', NULL, 5, 1, 'E', 32, '2013-04-18 16:19:26', 1, '2018-02-08 00:30:00', 335, NULL),
('TORSO AVANZADO PARA DESFIBRILACIÓN', 'LF03960U', 10, 'TORSO DE TAMAÑO ADULTO QUE PERMITE PRACTICAR DESFIBRILACIÓN UTILIZANDO DESFIBRILADOR DE MONITOR EXTERNO MANUAL, SEMIAUTOMÁTICO O AUTOMÁTICO. UNA CAJA INTERNA ABSORBE LA ENERGÍA DE CADA DESCARGA PARA PROTEGER A LOS USUARIOS. PERMITE MONITOREAR AL MANIQUÍ COMO SI FUERA UN PACIENTE REAL. PRESENTA 4 PUNTOS PARA ECG Y 2 PARA DESFIBRILACIÓN. PERMITE PRACTICAR TAMBIÉN DISTINTAS TÉCNICAS DE MANEJO DE VÍAS AÉREAS COMO INTUBACIÓN, ASPIRACIÓN Y VENTILACIÓN.', NULL, 5, 1, 'E', 32, '2013-04-18 16:20:04', 1, '2018-02-08 00:29:20', 336, NULL),
('SIMULADOR DE LUJO INFANTIL CRISIS CON SIMULADOR DE ECG', 'LF03617U', 11, 'MANIQUÍ SIMULADOR DE PACIENTE DE 8 AÑOS DE EDAD PARA PRÁCTICAS DE TÉCNICAS DE SOPORTE DE VIDA AVANZADO PEDIÁTRICO, ENTRENAMIENTO DE MANEJO DE VÍAS AÉREAS, BRAZO DE PUNCIÓN INTRAVENOSA, BRAZO PARA TOMA DE PRESIÓN, PRÁCTICA DE DESFIBRILACIÓN, INFUSIÓN INTRAÓSEA/ACCESO FEMORAL, PRÁCTICA DE RCP, SIMULADOR DE ARRITMIAS DE ECG, INTUBACIÓN ORAL, DIGITAL Y NASAL', NULL, 5, 1, 'E', 32, '2013-04-18 16:21:16', 1, '2018-02-08 00:21:49', 337, NULL),
('SIMULADOR COMPLETO DE RECIÉN NACIDO CRISIS', 'LF03709U', 11, 'MANIQUÍ SIMULADOR DE PACIENTE RECIÉN NACIDO QUE PERMITE LA PRÁCTICA DE ALS, MONITOREO DE ECG DE 4 DERIVACIONES, TERAPIA IV, CATETERISMO UMBILICAL, MANEJO DE VÍAS AÉREAS, INFUSIÓN INTRAÓSEA Y RCP', NULL, 5, 1, 'E', 32, '2013-04-18 16:21:50', 1, '2018-02-08 00:29:27', 338, NULL),
('TORSO AVANZADO INFANTIL DE MANEJO DE VÍAS AÉREAS CON DESFIBRILACIÓN, ECG Y AED', 'LF03764U', 11, 'MODELO DE TORSO DE PACIENTE DE 8 AÑOS DE EDAD DE LA PARTE SUPERIOR DEL CUERPO PARA EL MANEJO DE LAS VÍAS AÉREAS, RCP Y PROCEDIMIENTOS DE SOPORTE DE VIDA, PERMITE LA PRÁCTICA DE INTUBACIÓN, VENTILACIÓN, ASPIRACIÓN, RCP Y TÉCNICAS DE EMPUJE DE LA MANDÍBULA, REFERENCIAS ANATÓMICAS REALISTAS QUE INCLUYE DIENTES, LENGUA, FARINGE, LARINGE, EPIGLOTIS, CUERDAS VOCALES, TRÁQUEA, PULMONES, ESÓFAGO Y ESTÓMAGO, PERMITE LA PRÁCTICA DE INTUBACIÓN ORAL, DIGITAL Y NASAL', NULL, 5, 1, 'E', 32, '2013-04-18 16:22:23', 1, '2018-02-08 00:21:55', 339, NULL),
('SIMULADOR DE LUJO ADULTO CRISIS CON SIMULADOR DE ECG', 'LF03955U', 11, 'MANIQUÍ SIMULADOR DE PACIENTE ADULTO PARA PRÁCTICAS DE TÉCNICAS DE SOPORTE DE VIDA AVANZADO, PRÁCTICA DE DIFERENTES ESCENARIOS QUE INCLUYE UN MANIQUÍ A CUERPO COMPLETO, CABEZA DE MANEJO DE VÍAS AÉREAS, BRAZO DE PUNCIÓN INTRAVENOSA, BRAZO PARA TOMA DE PRESIÓN Y PECHO PARA DESFIBRILACIÓN, IDEAL PARA PROCEDIMIENTOS DE ACLS', NULL, 5, 1, 'E', 32, '2013-04-18 16:22:55', 1, '2018-02-08 00:22:03', 340, NULL),
('SIMULADOR DEL CUIDADO TRAQUEOSTOMICO', 'LF01083U', 12, 'SIMULADOR REPLICA DE VARÓN ADULTO QUE MUESTRA LOS PASAJES ORAL Y NASAL Y LA ANATOMÍA CORRESPONDIENTE. LA ZONA DEL PECHO CONTIENE LOS BRONQUIOS COMO EL ÁRBOL BRONQUIAL, EL ESÓFAGO TERMINA DOS PULGADAS DEBAJO DE LA ABERTURA TRAQUEAL. PUEDE PRACTICARSE LA SUCCIÓN ORAL, NASOFARÍNGEA, NASOTRAQUEAL Y TRAQUEAL. LA LIMPIEZA DE LA ABERTURA QUIRÚRGICA PUEDE HACERSE COMO EN UN PACIENTE', NULL, 5, 1, 'E', 32, '2013-04-18 16:23:30', 1, '2018-02-08 00:31:57', 341, NULL),
('PAQUETE DE 5 MANIQUÍES PARA RCP PEDIÁTRICO', 'LF06050U', 12, 'CONJUNTO DE 4 MANIQUÍES TAMAÑO PEDIÁTRICO PARA EL ENTRENAMIENTO DE REANIMACIÓN CARDIOPULMONAR (RCP)', NULL, 5, 1, 'E', 32, '2013-04-18 16:24:01', 1, '2018-02-08 00:22:15', 342, NULL),
('PAQUETE DE 4 MANIQUÍES PARA RCP ADULTO (PAQUETE DE 4)', 'LF06100U', 12, 'CONJUNTO DE 4 MANIQUÍES TAMAÑO ADULTO PARA EL ENTRENAMIENTO DE REANIMACIÓN CARDIOPULMONAR (RCP)', NULL, 5, 1, 'E', 32, '2013-04-18 16:24:32', 1, '2018-02-08 00:29:36', 343, NULL),
('SIMULADOR DE CRICOROTOMIA', 'LF01082U', 13, 'SIMULADOR PARA PRACTICA DE CRICOROTOMIA CON REFERENCIAS ANATÓMICAS PALPABLES QUE INCLUYEN LOS CARTÍLAGOS CRICOIDES Y TIROIDES. LA PROMINENCIA LARÍNGEA DESTACA EN EL CUELLO EN HIPEREXTENSIÓN. LA TRÁQUEA ES REEMPLAZABLE EN CUANTO LA VÍA AÉREA PASA DE ARRIBA A ABAJO, LO QUE PERMITE VERIFICAR LA COLOCACIÓN DEL ESTILETE Y OBTURADOR UNA VEZ QUE EL CORTE ESTA HECHO', NULL, 5, 1, 'E', 32, '2013-04-18 16:25:11', 1, '2018-02-08 00:22:22', 344, NULL),
('ENTRENADOR DE SONIDOS DE CORAZON Y PULMONES', 'PP00030U', 15, 'TORSO DE NIÑO DE 4 AÑOS QUE ENVIA LOS SONIDOS DE CORAZON Y PULMONES EMITIDOS DESDE 10 ALTAVOCES EN PULMONES Y UNO EN CORAZON, LOCALIZADOS EN PUNTOS DE AUSCULTACION NORMALES. EL USO DE ALTAVOCES PERMITE EMPLEAR CUALQUIER ESTETOSCOPIO. LA UNIDAD PUEDE ENCENDERSE DESDE UNA COMPUTADORA PERSONAL, O ATRAVES DEL CONTROL REMOTO ESPECIALCUENTA CON ENCHUFE PARA ALTAVOZ EXTERNO.', NULL, 6, 1, 'E', 32, '2013-04-18 16:31:55', 1, '2018-02-08 00:30:37', 345, NULL),
('MANIQUI PESADO PARA EL CUIDADO DEL PACIENTE', 'PP01370U', 1, 'MANIQUI DE VINIL DE 57 KG DE PESO VACIADO EN ARMAZON DE CABLE DE ACERO Y DE TAMAÑO Y PESO NATURAL, CON EXTREMIDADES ARTICULADAS Y TORSO FLEXIBLE. PERMITE EL ENTRENAMIENTO EN MANEJO Y TRANSFERENCIA DE PACIENTES, Y POSICIONAMIENTO CORRECTO EN CAMA, EN SILLA DE RUEDAS U OTRO EQUIPO. PRACTICA DE TECNICAS DE BAÑO E HIGIENE. CUENTA CON GENITALES INTERCAMBIABLES DE HOMBRE Y MUJER. PIEL SE ACOMODA A LAS HERIDAS PARA ENSEÑAR EL CUIDADO DE ULCERAS DE DECUBITO Y AL CAMBIAR LA ROPA QUIRURGICA O PRACTICAR VENDAJES', NULL, 6, 1, 'E', 32, '2013-04-18 16:32:39', 1, '2018-02-08 00:35:57', 346, NULL),
('MANIQUI PARA EL CUIDADO DEL PACIENTE', 'PP01372U', 1, 'MANIQUI DE VINIL VACIADO EN ARMAZON DE CABLE DE ACERO Y DE TAMAÑO NATURAL, CON EXTREMIDADES ARTICULADAS Y TORSO FLEXIBLE. PERMITE EL ENTRENAMIENTO EN MANEJO Y TRANSFERENCIA DE PACIENTES, Y POSICIONAMIENTO CORRECTO EN CAMA, EN SILLA DE RUEDAS U OTRO EQUIPO. PRACTICA DE TECNICAS DE BAÑO E HIGIENE. CUENTA CON GENITALES INTERCAMBIABLES DE HOMBRE Y MUJER. PIEL SE ACOMODA A LAS HERIDAS PARA ENSEÑAR EL CUIDADO DE ULCERAS DE DECUBITO Y AL CAMBIAR LA ROPA QUIRURGICA O PRACTICAR VENDAJES', NULL, 6, 1, 'E', 32, '2013-04-18 16:33:09', 1, '2018-02-08 00:36:08', 347, NULL),
('BRAZO DE ENTRENAMIENTO IV DE LUJO', 'PP00120U', 2, 'BRAZO DE ENTRENAMIENTO PARA PUNCION IV QUE DA ACCESO A LAS VENAS DEL BRAZO, LA MANO Y EL PUNTO DE INYECCION INTRAMUSUCLAR DELTOIDES. LOS SITIOS EN QUE LAS VENAS CEFALICA, BASILICA Y ANTECUBITAL SE ACOPLAN CON LAS VENAS METACARPIANAS PERMITE PRACTICAR VARIAS HABILIDADES', NULL, 6, 1, 'E', 32, '2013-04-18 16:33:59', 1, '2018-02-08 00:33:17', 348, NULL),
('SET DE MANO Y BRAZO DE ENTRENAMIENTO IV', 'PP00140U', 2, 'ACCESORIO DE ENTRENAMIENTO DISEÑADO PARA LA PRACTICA DE ADMINISTRACION DE PUNCIONS IV. PERMITE PRACTICAR EJERCICIOS DETALLADOS DE VENOPUNCION, DE MODO QUE LA TECNICA PUEDE DOMINARSE EN UN MODELO REALISTA ANTES DE APLICARLA EN PACIENTES. PUEDE PALPARSE LA PIEL Y LOCALIZAR LA VENA.', NULL, 6, 1, 'E', 32, '2013-04-18 16:34:30', 1, '2018-02-08 00:36:18', 349, NULL),
('BRAZO DE ENTRENAMIENTO IV', 'PP00146U', 2, 'ACCESORIO DE ENTRENAMIENTO DISEÑADO PARA LA PRACTICA DE ADMINISTRACION DE PUNCIONS IV. PERMITE PRACTICAR EJERCICIOS DETALLADOS DE VENOPUNCION, DE MODO QUE LA TECNICA PUEDE DOMINARSE EN UN MODELO REALISTA ANTES DE APLICARLA EN PACIENTES. PUEDE PALPARSE LA PIEL Y LOCALIZAR LA VENA.', NULL, 6, 1, 'E', 32, '2013-04-18 16:35:05', 1, '2018-02-08 00:36:25', 350, NULL),
('MANO DE ENTRENAMIENTO IV', 'PP00147U', 2, 'ACCESORIO DE ENTRENAMIENTO DISEÑADO PARA LA PRACTICA DE ADMINISTRACION DE PUNCIONS IV. PERMITE PRACTICAR EJERCICIOS DETALLADOS DE VENOPUNCION, DE MODO QUE LA TECNICA PUEDE DOMINARSE EN UN MODELO REALISTA ANTES DE APLICARLA EN PACIENTES. PUEDE PALPARSE LA PIEL Y LOCALIZAR LA VENA.', NULL, 6, 1, 'E', 32, '2013-04-18 16:35:38', 1, '2018-02-08 00:36:12', 351, NULL),
('BRAZO DE ENTRENAMIENTO IV GERIATRICO', 'PP00610U', 2, 'BRAZO CREADO A PARTIR DE UN MODELO VIVO. SUS PROPIEDADES INCLUYEN VENAS QUE SE APARTAN O DESAPARECEN CUANDO SE INTENTA CATETERIZAR EL VASO Y UNA PIEL ESPECIALMENTE DESARROLLADA', NULL, 6, 1, 'E', 32, '2013-04-18 16:36:16', 1, '2018-02-08 00:36:10', 352, NULL),
('ENTRENADOR DE AUTOEXPLORACION DE MAMA', 'PP01040U', 2, 'ENTRENADOR DE AUTO EXAMEN DE MAMA FABRICADO CON MATERIAL NO TOXICO, RESISTENTE A LAS MANCHAS. EN LA MAMA HAY 5 PROTUBERANCIAS QUE REPRESENTAN DIFERENTES ESTADIOS DE ENFERMEDAD: QUISTES, FIBROADENOMAS, ADENOSIS ESCLEROSANTE O NECROSIS GRASA. EL RELLENO ES UN GEL QUE IMITA LA CONSISTENCIA DE UNA MAMA', NULL, 6, 1, 'E', 32, '2013-04-18 16:36:59', 1, '2018-02-08 00:30:46', 353, NULL),
('BRAZO Y MANO PARA PUNCION IV', 'PP01374U', 2, 'ESTE ANTEBRAZO CON MANO REALISTA Y VENAS DE MANGUERA FLEXIBLE, PERMITE PRACTICAR LA COLOCACION DE IV, LAINFUSION DE FLUIDOS Y LA EXTRACCION DE SANGRE. INCLUYE BOLSA DE DEPOSITO, BANDEJA TRANSPORTADORAY SANGRE SIMUADA EN POLVO', NULL, 6, 1, 'E', 32, '2013-04-18 16:37:32', 1, '2018-02-08 00:36:08', 354, NULL),
('ENTRENADOR DIU', 'PP01912U', 2, 'ENTRENADOR PARA DEMOSTRAR LAS TECNICAS APROPIADAS DE INSERCION DE DIU', NULL, 6, 1, 'E', 32, '2013-04-18 16:38:08', 1, '2018-02-08 00:30:56', 355, NULL),
('MANIQUI OBSTETRICO', 'PP00180U', 3, 'MODELO PELVICO ANATOMICAMENTE CORRECTO CON RECIEN NACIDO A TERMINO Y PLACENTA PARA PRACTICAS REALISTAS EN TECNICAS MULTIPLES, Y A PRENDER EL PARTO SUBITO. INCLUYE CORDONES UMBILICALES DESECHABLES CON ABRAZADERAS, VULVA ADICIONAL REEMPLAZABLE, SANGRE EN POLVO, RECUBRIMIENTO DE VIENTRE DE EMBARAZADA MODULAR CON FETO PERMANENTE PARA ENTRENAR LA PRACTICA DE LA MANIOBRA DE LEOPOLD. LA CAVIDAD PELVICA TIENE ACUSADAS MARCAS PELVICAS, ESPINA DORSAL LOCALIZADA, CANAL DEL PARTO ANGULADO, ILION, ISQUION, LIGAMENTO SACROESPINOSO Y ESCOTADURA SACROCAITICA MAYOR. DISPONIBLE EN TONO DE PIEL BLANCO Y NEGRO', NULL, 6, 1, 'E', 32, '2013-04-18 16:38:52', 1, '2018-02-08 00:32:13', 356, NULL),
('HUESO PELVICO CON CABEZAS FETALES EN SOPORTE', 'PP00195U', 3, 'UNA PELVIS FEMENINA Y DOS CABEZAS DE FETO DISEÑADAS PARA DEMOSTRAR EL PROCESO DE PARTO. LAS DOS CABEZAS INTERCAMBIABLES, UNA A TERMINO Y LA OTRA PREMATURA, ESTAN SUJETADAS A UN EJE FLEXIBLE PARA PERMITIRLES PASAR, EN DIFERENTES POSICIONES, A TRAVES DEL ESTRECHO INFERIOR DE LA PELVIS. LAS DOS CABEZAS TIENEN CRANEOS EN LAS QUE SON PALPABLES LAS SUTURAS CRANEALES Y LAS FONTANELAS. LOS MODELOS PUEDEN USARSE PARA MOSTRAR PARTOS CON FORCEPS Y POR EXTRACCION AL VACIO.', NULL, 6, 1, 'E', 32, '2013-04-18 16:39:25', 1, '2018-02-08 00:35:54', 357, NULL),
('MANIQUI OBSTETRICO PARA PARTO CON FORCEPS/A VACIO', 'PP01377U', 3, 'MODELO PELVICO ANATOMICAMENTE CORRECTO CON FETOS TANTO PREMATURO COMO A TERMINO PARA UNA PRATICA REALISTA EN TECNICAS MULTIPLES, Y PARA APRENDER EL PROCEDIMIENTO DE PARTO REPENTINO. LA PELVIS DE VINIL SUAVE RECREA LA RESISTENCIA QUE SE ENCUENTRA EN UN PARTO QUE REQUIERE LA INTERVENCION DE FORCEPS O DE VACIO. DISPONIBLE EN TONO DE PIEL BLANCO Y NEGRO', NULL, 6, 1, 'E', 32, '2013-04-18 16:39:56', 1, '2018-02-08 00:31:08', 358, NULL),
('EVA. MANIQUI DE ENTRENAMIENTO GINECOLOGICO', 'PP01900U', 3, 'PELVIS FEMENINA PARECIDA A LA REAL PARA DESARROLLAR HABILIDADES EN PROCEDIMIENTOS GINECOLOGICOS, INSTRUCCIÓN ANATOMICA, PALPACION ABDOMINAL E INSTRUCCIÓN CON EL ESPECULO. INCLUYE LOS SIGUIENTES INSERTOS INTERCAMBIABLES: CERVIX NORMAL PARA INSERCION Y EXTRACCION DE DIU, CERVIX PARIDO NORMAL, CERVIX CON POLIPO ENDOCERVICAL, CERVIX CON CARACTERISTICAS DE ECTROPION, CERVIX CON NEOPLASIA (CARCINOMA), UTERO NORMAL PARA INCERSION Y EXTRACCION DE DIU, UTERO DE 10 SEMANAS DE EMBARAZO. NO INCLUYE OVARIOS.', NULL, 6, 1, 'E', 32, '2013-04-18 16:40:35', 1, '2018-02-08 00:35:51', 359, NULL),
('KIT FORENSE PARA SIMULACION DE HERIDAS', 'PP00700U', 6, 'UNIDAD BASICA DE RECOLECCION DE PRUEBAS DE TRAUMA QUE CONTIENE UNA SERIE DE HERIDAS CREADAS PARA ENSEÑAR EL ANALISIS DE LA ESCENA DEL CRIMEN Y LA RECONSTRUCCION DE LA ESCENA FORENSE. LOS DETALLES EN LAS HERIDAS ESTAN DISEÑADOS PARA DETERMINAR TIPO DE ARMA, DIRECCION DE FUERZA Y OTROS DETALLES QUE ESTEN PRESENTES EN LA REPRODUCCION DEL TRAUMA. CONTIENE MORDEDURA COMPLETA Y PARCIAL, GOLPE CONTUSO, OREJAS DE CONEJO, FRACTURA DE HUMERO, ROCE DE DISPARO, HERIDA DE CONTACTO, NAVAJA DE DOS FILOS, SALIDA DE DISPARO, INDEFINIBLES, PICAHIELO, LACERACION GRANDE Y MEDIA, PATRON DE LIGADURA, PETEQUIAS, DESTORNILLADOR, DISPARO Y CORTES, DISPARO DE CERCA Y QUEMADURA DE SEGUNDO GRADO', NULL, 6, 1, 'E', 32, '2013-04-18 16:41:18', 1, '2018-02-08 00:31:17', 360, NULL),
('PAQUETE FORENSE DE HERIDAS', 'PP00710U', 6, 'HERIDAS ADHESIVAS ESPECIALES QUE INCLUYE DOS DE CADA UNO DE LOS SIGUIENTES: MORDEDURA COMPLETA Y PARCIAL, GOLPE CONTUSO, ROCE DE DISPARO, NAVAJA DE DOS FILOS, EQUIMOSIS, SALIDA DE DISPARO, HERIDA GRANDE Y CHICA DE SALIDA, PICAHIELO, ROCE A DISTANCIA MEDIA, PATRON DE LIGADURA, PETEQUIAS, CUCHILLO DE UN SOLO FILO.', NULL, 6, 1, 'E', 32, '2013-04-18 16:41:51', 1, '2018-02-08 00:32:33', 361, NULL),
('EQUIPO BASICO PARA SIMULACION DE LESIONES', 'PP00815U', 6, 'EQUIPO PARA SIMULACION DE LESIONES. INCLUYE FRACTURA COMPUESTA DE TIBIA COMPLETA CON MONTAJE DE BOMBEO, BOTELLA DE SANGRE SIMULADA, POLVO PARA PREPARACION DE 1 GALON DE SANGRE SIMULADA, LACERACIONES ADHESIVAS VARIAS, CERA PARA SIMULACION DE HERIDAS, PAQUETE DE PLEXIGLAS ROTO PARA SIMULACION DE HERIDA POR CRISTAL INCRUSTADO, MAQUILLAJE, ESPATULAS Y ABATELENGUAS', NULL, 6, 1, 'E', 32, '2013-04-18 16:42:36', 1, '2018-02-08 00:31:31', 362, NULL),
('KIT MULTIPLE DE SIMULACION DE LESIONES', 'PP00816U', 6, 'PROPORCIONA HERIDAS COMPLEJAS PARA EVALUAR NIVELES MAS ALTOS DE HABILIDAD EN VENDAJE Y EN CUIDADO DE PACIENTE. CONTIENE HERIDAS SANGRANTES CON CORREAS, COMPLETAS CON BOLSAS DE DEPOSITO Y MONTAJE DE BOMBEO, AMPUTACION ABIERTA, FRACTURA COMPUESTA DE TIBIA IZQUIERDA, FRACTURA COMPUESTA DE HUMERO, HERIDA ASPIRATIVA DEL TORAX Y HERIDA DE BALA EN LA PALMA DE LA MANO.', NULL, 6, 1, 'E', 32, '2013-04-18 16:43:12', 1, '2018-02-08 00:32:26', 363, NULL),
('KIT DE SIMULACION DE VICTIMAS PARA PARAMEDICOS', 'PP00818U', 6, 'CONTIENE HERIDAS SANGRANTES CON CORREAS, HERIDA EN MANDIBULA, HERIDA ABDOMINAL CON PROT. DE INTESTINOS, HERIDA ASPIRATIVA DEL TORAX, FRACTURAS COMPUESTAS DE HUMERO, FRACTURAS COMPUESTAS DE FEMUR, LACERACION EN LA FRENTE, AMPUTACION DE PIERNA, FRACTURAS COMPUESTAS DE TIBIA, HERIDAS POR DISPARO EN LA PALMA. HERIDAS NO SANGRANTES SIMULADAS COMO QUEMADURA POR FOSFORO, DE 1ER, 2DO Y 3ER GRADO EN CARA, TORAX, ESPALDA, MANO Y ANTEBRAZO. EN TOTAL SON 95 PIEZAS, CON 36 LACERACIONES Y FRACTURAS ABIERTAS Y 6 QUEMADURAS', NULL, 6, 1, 'E', 32, '2013-04-18 16:43:56', 1, '2018-02-08 00:32:20', 364, NULL),
