('KIT DE LUJO PARA SIMULACION DE LESIONES', 'PP00890U', 6, 'ESTE EQUIPO CONTIENE 7 HERIDAS SANGRANTES CON CORREAS Y 15 HERIDAS ADHERIBLES MOLDEADAS JAMAS VISTAS. LA LINEA COMPLETA DE ACCESORIOS LE PERMITE CREAR 70 HERIDAS INDIVIDUALES. CONTIENE HERIDAS ADHERIBLES, GLOBO OCULAR, PROTRUSION DE CUERPO EXTRAÑO, INTESTINOS EVISCERADOS, LACERACIONES, FRACTURAS, AVULSION, QUEMADURAS, HERIDA EN LA MANDIBULA, CLAVICULA FRACTURADA, LACERACION EN ANTEBRAZO.', NULL, 6, 1, 'E', 32, '2013-04-18 16:47:48', 1, '2018-02-08 00:31:47', 367, NULL),
('MANIQUI STAT', 'PP00300U', 7, 'MANIQUI CON ALTO NIVEL DE ENTRENAMIENTO Y VALORACION DE HABILIDADES. CUENTA COM COMPONENTES DE RECONOCIMIENTO DE RITMO DE ECG Y DESFIBRILACION, MANTENIMIENTO DE VÍA AEREA, BRAZO IV, CARACTERISTICAS DE RCP, CARDIOVERSION AUTOMATICO DURANTE LA DESFIBRILACION, PUNTOS BILATERALES PARA DESCOMPRESION DE TORAX, PUNTOS BILATERALES PARA INSERCION DE TUBO TORACICO, CRICOTIROTOMIA, MARCAPASO, EDEMA LINGUAL Y LARINGOSPASMO, 12 PUNTOS PULSO, ROTURA DE DIENTES SUPERIORES POR PRESION DEL LARINGOSCOPIO, ACCESO VENOSO DEL DORSO DE LA MANO A LA PARTE SUPERIOR DEL BRAZO.', NULL, 6, 1, 'E', 32, '2013-04-18 16:48:32', 1, '2018-02-08 00:31:56', 368, NULL),
('BEBE STAT', 'PP00350U', 7, 'SIMULADOR PARA EL CUIDADO DEL LACTANTE QUE UTILIZA MATERIALES NUEVOS PARA LA PERCEPCION TACTIL DURANTE LA VALORACION DEL PACIENTE. MIDE LO QUE UN PACIENTE DE 9 MESES. SUS CARACTERISTICAS SON LAS SIGUIENTES: - PUNTOS BILATERALES PARA INSERCION DE TUBO TORACICO - DESFIBRILACION CON NIVEL DE DESCARGA DE 2.4 JOULES POR KG - INSERCION DE TUBO ENDOTRAQUEAL - CUIDADO CATETER DE ALIMENTACION - INSERCION DE SONDA FOLEY (FEMENINO) - PUNTOS DE INYECCION IM Y SC - PIERNA INTRAOSEA - COLOCACION DE SONDA NASOGASTRICA - PUNTOS PERIFERICOS IV EN MANO Y PIE - NEUMOTORAX - MEDICACION RECTAL - 6 PUNTOS DE PULSO (DOS BRAQUIALES, DOS FEMORALES Y DOS CAROTIDEOS - EDEMA LINGUAL Y LARINGOSPASMO - CUIDADO DE LA TRAQUEA', NULL, 6, 1, 'E', 32, '2013-04-18 16:49:07', 1, '2018-02-08 00:32:57', 369, NULL),
('PDA STAT MANIQUI', 'PP00400U', 7, 'SIMULADOR DE PACIENTE TAMAÑO REAL PARA ENTRENAMIENTO DE ALS. INCLUYE UN MANIQUI PDA STAT, PDA, CABLE USB, MANGUITO PARA PRESION ARTERIAL, PROGRAMAS, ESTUCHE RIGIDO Y PIEZAS DE REEMPLAZO. FUNCIONA EN EL LABORATORIO PARA ENSEÑANZA Y EN CAMPO PARA HABILIDAD EN DIAGNOSTICO. LOS REGISTROS DE DESEMPEÑO DEL ESTUDIANTE PUEDEN TRANSFERIRSE A LA PC. PERMITE LLEVAR A CABO PRACTICAS DE MANEJO AVANZADO DE VIAS AEREAS, TRAUMA COMO DESCOMPRESION DE NEUMOTORAX. GENERACION DE PULSOS INDEPENDIENTES. ECG Y BRAZO PARA PUNCION IV.', NULL, 6, 1, 'E', 32, '2013-04-18 16:49:38', 1, '2018-02-08 00:32:04', 370, NULL),
