('SMARTSTAT', 'PP00411U', 7, 'SIMULADOR DE PACIENTE INALÁMBRICO QUE OFRECE SIMPLICIDAD EN LA OPERACIÓN EN UN MANIQUÍ ALTAMENTE AVANZADO PARA EL ENTRENAMIENTO DE HABILIDADES MÉDICAS EN DIFERENTES NIVELES, INCLUYENDO SEM, HABILIDADES DE ENFERMERÍA Y ENTRENAMIENTO AVANZADO EN TRAUMA, CARDIOLOGÍA Y DIFERENTES ENFERMEDADES. PUEDEN PRACTICARSE PROCEDIMIENTOS COMO MANEJO AVANZADO DE VIAS AEREAS, DESFIBRILACION, PRACTICAS DE TRAUMA. INCLUYE UN MONITOR DE SIGNOS VITALES, PIERN TRAUMATIZADA CON HERIDA SANGRANTE Y SIMULADOR DE ARRITMIA. SE CONTROLA A TRAVES DE UNA POCKET PC (PALM). LAS CARACTERISTICAS PRINCIPALES SON LAS SIGUIENTES: - PUPILAS DILATABLES QUE PUEDEN CAMBIARSE EN TRES TAMAÑOS DIFERENTES \r\n- MUCOSA NASAL \r\n- BOCA ESPUMOSA \r\n- SONIDOS VOCALES PREGRABADOS (INCLUYENDO VÓMITO) \r\n- LABIOS Y UÑAS DE LOS DEDOS CON CIANOSIS \r\n- 12 PUNTOS DE PULSO \r\n- RCP, PULSOS CAROTIDEOS ACTIVADOS DURANTE UNA COMPRESIÓN ADECUADA \r\n- PERICARDIOCENTESIS \r\n- BRAZOS BILATERALES BP E IV \r\n- CATETERIZACIÓN YUGULAR EXTERNA - 5 DERIVACIONES PARA ECG \r\n- CATETERIZACIÓN URINARIA CON GENITALES INTERCAMBIABLES \r\n- SONIDOS ABDOMINALES EN CUATRO CUADRANTES \r\n- TODOS LOS FLUIDOS ALMACENADOS INCLUYENDO, SANGRE INTRAVENOSA Y LA SALIDA URINARIA \r\n- CADA PUNTO DE PULSO PUEDE SER DESACTIVADO PARA SIMULAR DIFICULTADES VASCULARES O ESTADOS DE ENFERMEDAD. \r\n- LA BATERÍA SE ENCUENTRA EN LA PIERNA IZQUIERDA, CON UNA DURACIÓN DE 3 ½ HRS EN OPERACIÓN \r\n- ACTUALIZACIÓN DE DATOS DEL EDITOR DEL MANIQUÍ', NULL, 6, 1, 'E', 32, '2013-04-18 16:50:51', 1, '2018-02-08 00:32:49', 372, NULL),
('ENTRENADOR SVA DE ADULTO', 'PP00080U', 8, 'SIMULADOR DE CUERPO COMPLETO QUE INCLUYE ESTERNON, CAJA TORACICA Y ESCOTADURA SUBESTERNAL. CONTIENE DIENTES, UVULA, CUERDAS VOCALES, GLOTIS, EPIGLOTIS, LARINGE, CARTILAGO ARITENOIDES, TRAQUEA, ESOFAGO Y PULMONES. LAS CARACTERISTICAS INCLUYEN VIAS AEREAS ORAL Y NASAL PARA INTUBACION, VENTILACION DE BOLSA-VALVULA-MASCARA, ENTREGA DE OXIGENO SUPLEMENTARIO, PULSO CAROTIDEO, EVALUACION ABC, PULMONES SEPARADOS, SONIDOS RESPIRATORIOS, COMPRESIONES DE TORAX E HIPIDO CORDIAL, TRACCION MANDIBULAR, PUNTO DE ACCESO INTRAVENOSO EN MANO Y BRAZO, PUNTO PARA PUNCIONINTRAMUSCULAR Y COLOCACION DE MANGO DE PRESION ARTERIAL. CON SIMULADOR DE ARRITMIAS/MARCAPASOS QUE RECREA 17 RITMOS CARDIACOS DE ADULTO Y 17 PEDIATRICOS. SE PUEDE SIMULAR CAPTURA ELECTRONICA, CARDIOVERSION CON DESFIBRILACION MANUAL, SEMIAUTOMATICA O AUTOMATICA.', NULL, 6, 1, 'E', 32, '2013-04-18 16:51:47', 1, '2018-02-08 00:32:20', 373, NULL),
