('MANIQUI RCP DE ENTRENAMIENTO MULTICULTURAL', 'PP02827U', 9, 'MANIQUI CON CARACTERISTICAS MULTICULTURALES Y COLOR DE PIEL. PERMITE LA TECNICA DE LEVANTAR EL MENTON E INCLINAR LA CABEZA PARA ABRIR LA VIA AEREA Y LAS MARCAS ANATOMICAS QUE AYUDAN A LA COLOCACION ADECUADA DE LA MANO. EL ESFUERZO DE LAS COMPRESIONES TORACICAS DE ADULTO PUEDEN ELIMINARSE RETIRANDO LA PLACA TORACICA DE DEBAJO DE LA PIEL Y SE PUEDEN EXPERIMENTAR COMPRESIONES DE ADULTO PEQUEÑO O ADOLESCENTE.', NULL, 6, 1, 'E', 32, '2013-04-18 17:19:03', 1, '2018-02-08 00:34:43', 413, NULL),
('KIM MANIQUI DE LACTANTE PARA RCP', 'PP02901U', 9, 'MANIQUI ECONOMICO PARA ENSEÑANZA DE RCP EN RECIEN NACIDOS. LIGERO Y REALISTA RELLENO CON ESPUMA SIN PARTES INTERNAS QUE SE ROMPAN. INCLUYE BOQUILLAS/PIEZAS NASALES INDIVIDUALES, UNA INCISION DE VIA AEREA Y SISTEMA DE VIAS AEREAS COMPLETAMENTE DESECHABLE CON UNA VALVULA SIN RE-RESPIRACION.', NULL, 6, 1, 'E', 32, '2013-04-18 17:19:42', 1, '2018-02-08 00:34:45', 414, NULL),
