('RANDY 9000', 'PP09000U', 9, 'MANIQUI PARA SER ADAPTADO PARA UN USO OPTIMO EN EL ENTRENAMIENTO. FABRICADO CON PARTES RESISTENTES DE POLIETILENO QUE PERMITE LA ADICION DE CANTIDADES VARIABLES DE PESO A CADA UNA DE LAS PIEZAS. EL CAMPO DE MOVIMIENTO DE LAS ARTICULACIONES, INCLUYENDO FLEXION DE LA CINTURA, IMITA LA VIDA REAL. PUEDE USARSE EN TODAS LAS CONDICIONES DE CLIMA Y EL DISEÑO DE LAS ARTICULACIONS PROTEGE LOS DEDOS DE LOS RESCATISTAS', NULL, 6, 1, 'E', 32, '2013-04-18 17:23:02', 1, '2018-02-08 00:35:12', 419, NULL),
('ENTRENADOR DE MANEJO CRITICO DE VIA AEREA', 'PP00060U', 10, 'CABEZA DE DIFICIL INTUBACION UNIDA A UN TORSO PARA PRACTICA DE RCP QUE PERMITE LA ENSEÑANZA DE LA ATENCION RESPIRATORIA DE UN PACIENTE CRITICO. CUENTA CON EDEMA DE LENGU Y LARINGOSPASMO PARA COMPLICAR LA INTUBACION. PERMITE LA REALIZACION DE CRICOROTOMIA. LA CABEZA SIMULA DOS HERIDAS EXTERNAS Y UNA INTERNA QUE SANGRAN Y DEMANDAN ATENCION CON ASPIRACION Y CONTROL DEL SANGRADO', NULL, 6, 1, 'E', 32, '2013-04-18 17:23:47', 1, '2018-02-08 00:35:14', 420, NULL),
('CABEZA PARA INTUBACION POR TRAUMATISMO', 'PP00069U', 10, 'CABEZA PARA INTUBACION QUE SE ACOPLA AL ENTRENADOR SVA DE ADULTO (PP00080U). SIMULA GARGANTA Y CUERDAS VOCALES INFLAMADAS QUE OCASIONAN HINCHAZON DE LARINGE. TAMBIEN SIMULA SANGRADO. PUEDE REALIZARSE UNA CRICOROTOMIA. INCLUYE VIAS AEREAS PARA INTUBACION ORAL Y NASAL, VENTILACION DE BOLSA-VALVULA-MASCARA Y ENTREGA DE OXIGENO SUPLEMENTARIO', NULL, 6, 1, 'E', 32, '2013-04-18 17:24:20', 1, '2018-02-08 00:35:16', 421, NULL),
('INTUBACION AVANZADA DE LACTANTE', 'PP00130U', 10, 'ENTRENADOR QUE INCORPORA LA NUEVA TECNOLOGIA DE PIEL PARA ENTRENAMIENTO EN VIA AEREA PEDIATRICA. LA PROPIEDAD DE SER TRASLUCIDA FACILITA LA ILUMINACION VEROSIMIL DE LA VIA AEREA Y EL CUELLO. LAS CUERDAS VOCALES ESTAN RESALTADAS PARA UNA FACIL VISUALIZACION, LA LENGUA SE HINCHA Y ESTAN PRESENTES TODAS LAS REFERENCIAS ANATOMICAS.', NULL, 6, 1, 'E', 32, '2013-04-18 17:25:07', 1, '2018-02-08 00:35:19', 422, NULL),
('SIMULADOR DE CRICOROTOMIA DE LUJO', 'PP00135U', 10, 'SIMULADOR DISEÑADO PARA LA REALIZACION DE CRICOROTOMIA POR PUNCION O QUIRURGICA. LAS REFERENCIAS INCLUYEN CARTILAGO TIROIDES, CRICOIDES Y MEMBRANA CRICOIDES. EL INFLADO DEL PULMON VERIFICA LA COLOCACION CORRECTA. INCLUYE TRAQUEAS DE ADULTO Y DE NIÑO DE 3 AÑOS, Y BOLSA SUAVE PARA TRASLADO', NULL, 6, 1, 'E', 32, '2013-04-18 17:25:47', 1, '2018-02-08 00:35:39', 423, NULL),
('ENTRENADOR DE MANEJO DE VIA AEREA DE ADULTO DE LUJO CON TABLERO', 'PP00502U', 10, 'CABEZA PARA MANEJO DE VÍA AEREA QUE USA PIEL REALISTA. ANATOMIA CON CARACTERISTICAS EXACTAS. INCLUYE LARINGOSPASMO Y EDEMA LINGUAL, LOS PULMONES Y EL ESTOMAGO SON VISIBLES PARA DETERMINAR UNA INTUBACION EXITOSA. SE MUESTRAN TODAS LAS REFERENCIAS ANATOMICAS Y LAS CUERDAS VOCALES ESTAN RESALTADAS PARA UNA FACIL VISUALIZACION. LOS DIENTES SUPERIORES SE ROMPEN SI SE APLICA UNA TECNICA INADECUADA DURANTE LAS INTUBACIONES. EL TABLERO SE FIJA A LAS SUPERFICIES MEDIANTE PATAS DE VENTOSA', NULL, 6, 1, 'E', 32, '2013-04-18 17:26:17', 1, '2018-02-08 00:35:28', 424, NULL),
('SIMULADOR DE NEUMOTORAX', 'PP01800U', 10, 'TORSO PARA ENSEÑANZA Y PRACTICA DE LA INSERCION DE UNA AGUJA PARA PERMITIR QUE LA PRESION DEL AIRE ESCAPE DEL TORAX. EL MODELO ACEPTA TORACOTOMIA EN EL SEGUNDO ESPACIO INTERCOSTAL EN LA LINEA CLAVICULAR MEDIA O EN EL QUINTO ESPACIO INTERCOSTAL EN LA LINEA AUXILIAR MEDIA. ESTE MODELO SE COMPLEMENTA CON PULMONES REEMPLAZABLES, UNA CAJA TORACICA Y UNA PIEL REEMPLAZABLE SUAVE. LA UNIDAD PUEDE SER PINCHADA 75 O 100 VECES ANTES DE NECESITAR REEMPLAZO.', NULL, 6, 1, 'E', 32, '2013-04-18 17:26:52', 1, '2018-02-08 00:35:25', 425, NULL),
