('MODELO FUNCIONAL DE LA ARTICULACIÓN DE LA RODILLA DE LUJO', 'A82/1', 20, 'ESTE MODELO FUNCIONAL DE LA ARTICULACIÓN DERECHA CON LIGAMENTOS, DE ALTA CALIDAD Y EN TAMAÑO NATURAL, REPRESENTA DE FORMA EXTRAORDINARIAMENTE DETALLADA LA ANATOMÍA Y LAS POSIBILIDADES DE MOVIMIENTO FISIOLÓGICAS (P.EJ. ABDUCCIONES, ANTE VERSIÓN, RETROVERSIÓN, ROTACIÓN EXTERNA E INTERNA). LA COLORACIÓN DE LOS HUESOS MOLDEADOS CONFORME CON SU ORIGINAL ES EXTREMADAMENTE REALISTA. EL CARTÍLAGO EN LAS SUPERFICIES ARTICULARES SE REPRESENTA EN COLOR AZUL. EL MODELO CONSTA DE LOS MUÑONES DE MUSLO, TIBIA Y PERONÉ, LOS MENISCOS Y LA RÓTULA. SOBRE SOPORTE.', NULL, 8, 2, 'A', 32, '2013-04-22 14:31:52', NULL, NULL, 464, NULL),
('ARTICULACIÓN DEL CODO - MODELO FUNCIONAL', 'A83', 20, 'EL MODELO FUNCIONAL OFRECE UNA DEMOSTRACIÓN GRÁFICA DE LA ANATOMÍA Y DEL MECANISMO DE LA ARTICULACIÓN, PERMITIENDO UNA MEJOR COMPRENSIÓN ENTRE EL DOCTOR Y EL PACIENTE Y ENTRE EL PROFESOR Y EL ESTUDIANTE. EMPLEE LA ARTICULACIÓN DE TAMAÑO NORMAL Y COMPLETAMENTE FLEXIBLE, PARA DEMOSTRAR LA ABDUCCIÓN, LA ANTE VERSIÓN, LA RETROVERSIÓN, LA ROTACIÓN INTERNA/EXTERNA Y MUCHAS COSAS MÁS.\r\n\r\nCONSTA DE UNA PARTE DEL HÚMERO, ULNA Y RADIOS COMPLETOS, COMO TAMBIÉN DE LIGAMENTOS DE LA ARTICULACIÓN. ARTICULADO SOBRE UN SOPORTE.', NULL, 8, 2, 'A', 32, '2013-04-22 14:32:32', NULL, NULL, 465, NULL),
('MODELO FUNCIONAL DE LA ARTICULACIÓN DEL CODO DE LUJO', 'A83/1', 20, 'ESTE MODELO FUNCIONAL DE LA ARTICULACIÓN DERECHA CON LIGAMENTOS, DE ALTA CALIDAD Y EN TAMAÑO NATURAL, REPRESENTA DE FORMA EXTRAORDINARIAMENTE DETALLADA LA ANATOMÍA Y LAS POSIBILIDADES DE MOVIMIENTO FISIOLÓGICAS (P.EJ. ABDUCCIONES, ANTE VERSIÓN, RETROVERSIÓN, ROTACIÓN EXTERNA E INTERNA). LA COLORACIÓN DE LOS HUESOS MOLDEADOS CONFORME CON SU ORIGINAL ES EXTREMADAMENTE REALISTA. EL CARTÍLAGO EN LAS SUPERFICIES ARTICULARES SE REPRESENTA EN COLOR AZUL. EL MODELO CONSTA DE LOS MUÑONES DE BRAZO, CÚBITO Y HUESO RADIO. SOBRE SOPORTE', NULL, 8, 2, 'A', 32, '2013-04-22 14:33:11', NULL, NULL, 466, NULL),
('MINI-ARTICULACIÓN DE LA CADERA, SIN BASE', 'A84', 20, 'ÉSTA MINI-ARTICULACIÓN HA SIDO REDUCIDA LA MITAD DE SU TAMAÑO NATURAL, PERO MANTIENE TODA SU FUNCIONALIDAD.', NULL, 8, 2, 'A', 32, '2013-04-22 14:33:52', NULL, NULL, 467, NULL),
('MINI-ARTICULACIÓN DE LA CADERA CON CORTE TRANSVERSAL, SOBRE UNA BASE', 'A84/1', 20, 'ÉSTA MINI-ARTICULACIÓN HA SIDO REDUCIDA LA MITAD DE SU TAMAÑO NATURAL, PERO MANTIENE TODA SU FUNCIONALIDAD. ADEMÁS DE LAS ESTRUCTURAS ANATÓMICAS EXTERNAS USTED AHORA TIENE LA POSIBILIDAD DE EXPLICAR LO QUE ESTA SUCEDIENDO EN EL INTERIOR DE LA ARTICULACIÓN UTILIZANDO EL CORTE TRANSVERSAL DE LA ARTICULACIÓN EN LA BASE.', NULL, 8, 2, 'A', 32, '2013-04-22 14:34:32', NULL, NULL, 468, NULL),
