('MINI-ARTICULACIÓN DE LA RODILLA CON CORTE TRANSVERSAL, SOBRE BASE', 'A85/1', 20, 'ÉSTA MINI-ARTICULACIÓN HA SIDO REDUCIDA LA MITAD DE SU TAMAÑO NATURAL, PERO MANTIENE TODA SU FUNCIONALIDAD. ADEMÁS DE LAS ESTRUCTURAS ANATÓMICAS EXTERNAS USTED AHORA TIENE LA POSIBILIDAD DE EXPLICAR LO QUE ESTA SUCEDIENDO EN EL INTERIOR DE LA ARTICULACIÓN UTILIZANDO EL CORTE TRANSVERSAL DE LA ARTICULACIÓN EN LA BASE.', NULL, 8, 2, 'A', 32, '2013-04-22 14:35:42', NULL, NULL, 470, NULL),
('MINI-ARTICULACIÓN DEL HOMBRO, SIN BASE', 'A86', 20, 'ÉSTA MINI-ARTICULACIÓN HA SIDO REDUCIDA LA MITAD DE SU TAMAÑO NATURAL, PERO MANTIENE TODA SU FUNCIONALIDAD.', NULL, 8, 2, 'A', 32, '2013-04-22 14:36:20', NULL, NULL, 471, NULL),
('MINI-ARTICULACIÓN DEL HOMBRO CON CORTE TRANSVERSAL, SOBRE BASE', 'A86/1', 20, 'ÉSTA MINI-ARTICULACIÓN HA SIDO REDUCIDA LA MITAD DE SU TAMAÑO NATURAL, PERO MANTIENE TODA SU FUNCIONALIDAD. ADEMÁS DE LAS ESTRUCTURAS ANATÓMICAS EXTERNAS USTED AHORA TIENE LA POSIBILIDAD DE EXPLICAR LO QUE ESTA SUCEDIENDO EN EL INTERIOR DE LA ARTICULACIÓN UTILIZANDO EL CORTE TRANSVERSAL DE LA ARTICULACIÓN EN LA BASE.', NULL, 8, 2, 'A', 32, '2013-04-22 14:36:54', NULL, NULL, 472, NULL),
('MINI-ARTICULACIÓN DEL CODO, SIN BASE', 'A87', 20, 'ÉSTA MINI-ARTICULACIÓN HA SIDO REDUCIDA LA MITAD DE SU TAMAÑO NATURAL, PERO MANTIENE TODA SU FUNCIONALIDAD.', NULL, 8, 2, 'A', 32, '2013-04-22 14:37:43', NULL, NULL, 473, NULL),
('MINI-ARTICULACIÓN DEL CODO CON CORTE TRANSVERSAL, SOBRE BASE', 'A87/1', 20, 'ÉSTA MINI-ARTICULACIÓN HA SIDO REDUCIDA LA MITAD DE SU TAMAÑO NATURAL, PERO MANTIENE TODA SU FUNCIONALIDAD. ADEMÁS DE LAS ESTRUCTURAS ANATÓMICAS EXTERNAS USTED AHORA TIENE LA POSIBILIDAD DE EXPLICAR LO QUE ESTA SUCEDIENDO EN EL INTERIOR DE LA ARTICULACIÓN UTILIZANDO EL CORTE TRANSVERSAL DE LA ARTICULACIÓN EN LA BASE.', NULL, 8, 2, 'A', 32, '2013-04-22 14:38:16', NULL, NULL, 474, NULL),
('FRACTURA DE FÉMUR Y DESGASTE DE LA ARTICULACIÓN DE LA CADERA', 'A88', 20, 'EL PRESENTE MODELO HA SIDO DESARROLLADO PARA AYUDAR A INFORMAR DE MANERA COMPRENSIBLE A LOS PACIENTES, P. EJ. ANTES DE UNA OPERACIÓN. REPRESENTA LA ARTICULACIÓN DE LA CADERA DERECHA DE UNA PERSONA MAYOR EN MEDIO TAMAÑO NATURAL. ADEMÁS, SOBRE EL ZÓCALO SE REPRESENTA UN CORTE FRONTAL POR EL CUELLO DEL FÉMUR EN RELIEVE. EL MODELO REPRESENTA LAS FRACTURAS DE FÉMUR MÁS FRECUENTES EN LA PRÁCTICA ASÍ COMO DESGASTES TÍPICOS EN LA ARTICULACIÓN DE LA CADERA (COXARTROSIS O ARTROSIS DE LA ARTICULACIÓN DE LA CADERA). SE REPRESENTAN LAS FRACTURAS SIGUIENTES: FRACTURA MEDIA DEL CUELLO DEL FÉMUR, FRACTURA LATERAL DEL CUELLO DEL FÉMUR, FRACTURA A TRAVÉS DE LA ZONA DE LOS TROCÁNTERES (FRACTURA PERTROCANTÉREA DE FÉMUR), FRACTURA DEBAJO DE LOS TROCÁNTERES (FRACTURA SUBTROCANTÉREA DE FÉMUR), FRACTURA EN LA ZONA DEL CUERPO DEL FÉMUR (FRACTURA DEL CUERPO DEL FÉMUR), FRACTURA EN LA ZONA DE LA CABEZA DEL FÉMUR (FRACTURA DE LA CABEZA DEL FÉMUR), FRACTURA DEL TROCÁNTER MAYOR, FRACTURA O DESPRENDIMIENTO DEL TROCÁNTER MENOR (FRACTURA CON DESPRENDIMIENTO DEL TROCÁNTER MENOR) \r\nSOBRE UN ZÓCALO.', NULL, 8, 2, 'A', 32, '2013-04-22 14:38:58', NULL, NULL, 475, NULL),
('ARTICULACIÓN DEL HOMBRO CON MANGUITO ROTADOR', 'A880', 20, 'ESTE MODELO SE COMPONE DE LA MITAD SUPERIOR DEL HÚMERO, LA CLAVÍCULA Y DEL HUESO ESCÁPULA U OMÓPLATO. ADEMÁS DE LA REPRESENTACIÓN DE LA MUSCULATURA DEL MANGUITO ROTADOR SE HAN RESALTADO EN COLORES DIFERENTES LAS SUPERFICIES DEL ORIGEN Y DE LA INSERCIÓN DE LOS MÚSCULOS DEL HOMBRO (ORIGEN = ROJO; INSERCIÓN = AZUL). SE ENCUENTRAN REPRESENTADOS Y SE PUEDEN DESPRENDER LOS SIGUIENTES MÚSCULOS: SUBSCAPULARIS, SUPRASPINATUS, INFRASPINATUS, TERES MINOR. AL RETIRAR CADA UNO DE LOS MÚSCULOS, SE PUEDEN LLEVAR A CABO TODOS LOS MOVIMIENTOS DE LA ARTICULACIÓN DEL HOMBRO', NULL, 8, 2, 'A', 32, '2013-04-22 14:39:48', NULL, NULL, 476, NULL),
('ARTICULACIÓN DE LA CADERA, 7 PIEZAS', 'A881', 20, 'EL MODELO MUESTRA LA ARTICULACIÓN DE LA CADERA DE UN HOMBRE, CON MÚSCULOS INDIVIDUALES, AL IGUAL QUE SUS ORÍGENES E INSERCIONES EN EL FÉMUR Y EN EL HUESO ILÍACO. LAS SUPERFICIES DE LOS ORÍGENES E INSERCIONES DE LOS MÚSCULOS SE PRESENTAN EN RELIEVE Y CON DISTINTOS COLORES (ORIGEN = ROJO, INSERCIÓN = AZUL). LA MUSCULATURA DE LA CADERA SE ENCUENTRA INSERTADA EN SUS REGIONES CORRESPONDIENTES DE ORIGEN E INSERCIÓN Y ES TAMBIÉN DESMONTABLE.', NULL, 8, 2, 'A', 32, '2013-04-22 14:40:26', NULL, NULL, 477, NULL),
('ARTICULACIÓN DE LA RODILLA CON MÚSCULOS', 'A882', 20, 'MODELO DE 12 PARTES DE LA ARTICULACIÓN DE LA RODILLA. MUESTRA DIFERENTES MÚSCULOS Y PARTES DE MÚSCULOS EXTRAÍBLES DE LA REGIÓN DE LA RODILLA. LAS ZONAS CON CÓDIGO DE COLOR Y ELEVADAS INDICAN EL ORIGEN DEL MÚSCULO Y SUS PUNTOS DE INSERCIÓN EN EL FÉMUR, TIBIA Y PERONÉ. ADEMÁS, TAMBIÉN REPRESENTA PARTES DE LOS LIGAMENTOS COLATERALES PERONEALES Y TIBIALES. TODOS LOS MÚSCULOS DE LA PIERNA SON FÁCILMENTE EXTRAÍBLES PARA PERMITIR EL ESTUDIO DE LAS CAPAS ANATÓMICAS INFERIORES.', NULL, 8, 2, 'A', 32, '2013-04-22 14:43:20', NULL, NULL, 478, NULL),
('ARTICULACIÓN DEL CODO, 8 PIEZAS', 'A883', 20, 'EL MODELO MUESTRA EL CODO DERECHO DE UN HOMBRE CON TODOS LOS MÚSCULOS, LOS ORÍGENES Y LAS INSERCIONES MUSCULARES DEL HÚMERO, ASÍ COMO DEL RADIO Y EL CÚBITO. LAS SUPERFICIES DE LAS INSERCIONES Y DE LOS ORÍGENES MUSCULARES ESTÁN RESALTADAS Y CODIFICADAS POR COLORES (ORIGEN = ROJO; INSERCIÓN = AZUL) CON FINES DIDÁCTICOS. LOS MÚSCULOS ESTÁN INSERTADOS EN LAS SUPERFICIES DE LOS ORÍGENES Y DE LAS INSERCIONES MUSCULARES CORRESPONDIENTES Y, POR LO TANTO, SE PUEDEN EXTRAER.', NULL, 8, 2, 'A', 32, '2013-04-22 14:43:57', NULL, NULL, 479, NULL),
('MODELO DE LA ARTICULACIÓN DE LA RODILLA, DIVIDIDO EN 3 PARTES', 'A89', 20, 'ESTE MODELO AYUDA A EXPLICAR GRÁFICAMENTE LAS DIVERSAS ENFERMEDADES DE LA ARTICULACIÓN DE LA RODILLA (ARTICULATIO GENUS) HUMANA Y TAMBIÉN LAS POSIBLES FORMAS DE TRATAMIENTO. LA ARTICULACIÓN DE UNA RODILLA DERECHA SANA ESTÁ REPRESENTADA A TAMAÑO NATURAL Y EN POSICIÓN ERECTA, INCLUYENDO PARTE DEL MUSLO, DE LA TIBIA Y DEL PERONÉ, ASÍ COMO LOS LIGAMENTOS Y LA RÓTULA. SOBRE UN ZÓCALO.', NULL, 8, 2, 'A', 32, '2013-04-22 14:44:30', NULL, NULL, 480, NULL),
('MODELO QUE MUESTRA LAS 9 FASES DE LA MITOSIS', 'R01', 21, 'MUESTRA LAS 9 FASES DE LA MITOSIS PONIENDO COMO EJEMPLO UNA CÉLULA TÍPICA DE MAMÍFERO AUMENTADA UNAS 10.000 VECES: 1. INTERFASE 2. PROFASE 3. PROMETAFASE PRECOZ 4. PROMETAFASE AVANZADA 5. METAFASE 6. ANAFASE PRECOZ 7. ANAFASE AVANZADA 8. TELOFASE 9. CITOCINESIS', NULL, 8, 2, 'A', 32, '2013-04-22 14:45:57', NULL, NULL, 481, NULL),
('MODELO DE 10 ETAPAS DE LA MEIOSIS', 'R02', 21, 'ESTA MUESTRA 10 ETAPAS DE LA MEIOSIS A BASE DEL EJEMPLO DE UNA CÉLULA TÍPICA DE MAMÍFERO, AUMENTADA APROXIMADAMENTE 10.000 VECES: 1. INTERFASE (ESTADO DE LA FASE G1) 2. PROFASE I (LEPTOTENE) 3. PROFASE I (ZIGOTENO Y PAQUITENE) 4. PROFASE I (DIPLOTENE) 5. PROFASE I (DIAQUINESIS) 6. METAFASE I 7. ANAFASE I 8. TELOFASE I, CITOQUINESIS I, INTERQUINESIS, PROFASE II Y METAFASE II 9. ANAFASE II 10. TELOFASE II Y CITOQUINESIS II', NULL, 8, 2, 'A', 32, '2013-04-22 14:46:34', NULL, NULL, 482, NULL),
('COLUMNA VERTEBRAL MINIATURA, ELÁSTICA', 'A18/20', 22, 'MODELO CON ESCAMA DEL OCCIPITAL Y PELVIS. LA COLUMNA VERTEBRAL ESTÁ MONTADA DE FORMA ELÁSTICA Y, POR LO TANTO, PERMITE ENSEÑAR MOVIMIENTOS NATURALES Y ALTERACIONES PATOLÓGICAS. SIN SOPORTE', NULL, 8, 2, 'A', 32, '2013-04-22 14:49:04', NULL, NULL, 483, NULL),
('COLUMNA VERTEBRAL MINIATURA, ELÁSTICA, SOBRE SOPORTE', 'A18/21', 22, 'MODELO CON ESCAMA DEL OCCIPITAL Y PELVIS. LA COLUMNA VERTEBRAL ESTÁ MONTADA DE FORMA ELÁSTICA Y, POR LO TANTO, PERMITE ENSEÑAR MOVIMIENTOS NATURALES Y ALTERACIONES PATOLÓGICAS. SOBRE SOPORTE.', NULL, 8, 2, 'A', 32, '2013-04-22 14:49:48', NULL, NULL, 484, NULL),
('COLUMNA VERTEBRAL PEDIÁTRICA', 'A52', 22, 'ESTE MODELO REALISTA DE LA COLUMNA VERTEBRAL DE UN NIÑO DE ALREDEDOR DE 5 AÑOS ES ESPECIALMENTE INTERESANTE PARA LA ANATOMÍA, LA PEDIATRÍA, LA ORTOPEDIA Y LA RADIOLOGÍA PEDIÁTRICA. GRACIAS AL MATERIAL ÚNICO CON EL QUE SE HA FABRICADO APENAS SE DIFERENCIA DE UNA COLUMNA VERTEBRAL NATURAL. LA COLUMNA VERTEBRAL FLEXIBLE SE PRESENTA MONTADA SOBRE UNA BASE CON HUESO OCCIPITAL, PELVIS, SACRO Y COXIS. ASÍ MISMO REPRODUCE LA MÉDULA ESPINAL DEL CONDUCTO VERTEBRAL CON CAUDAL EQUINAL Y EL NACIMIENTO DE LAS RAÍCES NERVIOSAS. EL MODELO PERMITE ESTUDIAR DE FORMA SORPRENDENTE EL ESTADIO CARACTERÍSTICO DEL CRECIMIENTO ÓSEO CORRESPONDIENTE A LA ETAPA DE CRECIMIENTO DE UN NIÑO DE 5 AÑOS DE EDAD. TAMBIÉN MUESTRA: EN EL ÁREA VERTEBRAL, TRANSICIÓN PARCIALMENTE INCOMPLETA DE CUERPOS VERTEBRALES Y ARCOS VERTEBRALES, EN EL SACRO, FUSIÓN AÚN INCOMPLETA DE CADA UNA DE LAS VÉRTEBRAS SACARLES, EN LA PELVIS, LA JUNTURA EN Y AÚN ABIERTA COMO ZONA DE CRECIMIENTO PRINCIPAL DE LA CAVIDAD COTILOIDEA. LAS PORCIONES DEL HUESO ILÍACO, PUBIS E ISQUION AÚN SIN FUSIONAR.', NULL, 8, 2, 'A', 32, '2013-04-22 14:50:31', NULL, NULL, 485, NULL),
('COLUMNA FLEXIBLE - VERSIÓN CLÁSICA CON COSTILLAS', 'A56', 22, 'ESTE MODELO MUESTRA LA INTERACCIÓN ENTRE LA COLUMNA, COSTILLAS Y LAS ESTRUCTURAS ASOCIADAS. LAS CARACTERÍSTICAS SOBRESALIENTES SON: MONTAJE TOTALMENTE FLEXIBLE PARA DEMOSTRACIONES EXPLÍCITAS, PELVIS MASCULINA, PLACA OCCIPITAL, HERNIA DE DISCO ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR, SALIDA DE LAS RAÍCES NERVIOSAS Y ARTERIAS VERTEBRALES', NULL, 8, 2, 'A', 32, '2013-04-22 14:51:41', NULL, NULL, 486, NULL),
('COLUMNA FLEXIBLE - VERSIÓN CLÁSICA CON COSTILLAS Y CABEZAS DE FÉMUR', 'A56/2', 22, 'ESTE MODELO MUESTRA LA INTERACCIÓN ENTRE LA COLUMNA, COSTILLAS Y LAS ESTRUCTURAS ASOCIADAS. LAS CARACTERÍSTICAS SOBRESALIENTES SON: MONTAJE TOTALMENTE FLEXIBLE PARA DEMOSTRACIONES EXPLICITAS, PELVIS MASCULINA, PLACA OCCIPITAL, HERNIA DE DISCO ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR, SALIDA DE LAS RAÍCES NERVIOSAS, ARTERIAS VERTEBRALES Y CABEZAS DE FÉMUR MONTADAS DE FORMA MOVIBLE', NULL, 8, 2, 'A', 32, '2013-04-22 14:52:30', NULL, NULL, 487, NULL),
('COLUMNA FLEXIBLE – VERSIÓN CLÁSICA', 'A58/1', 22, 'MONTAJE TOTALMENTE FLEXIBLE PARA DEMOSTRACIONES EXPLICITAS, PELVIS MASCULINA, PLACA OCCIPITAL, HERNIA DE DISCO ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR, SALIDA DE LAS RAÍCES NERVIOSAS Y ARTERIAS VERTEBRALES', NULL, 8, 2, 'A', 32, '2013-04-22 14:53:08', NULL, NULL, 488, NULL),
('COLUMNA FLEXIBLE VERSIÓN CLÁSICA, CON CABEZAS DE FÉMUR', 'A58/2', 22, 'MODELO DE LA COLUMNA VERTEBRAL FLEXIBLE. MONTAJE TOTALMENTE FLEXIBLE PARA DEMOSTRACIONES EXPLICITAS. PELVIS MASCULINA, PLACA OCCIPITAL, HERNIA DE DISCO ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR, SALIDA DE LAS RAÍCES NERVIOSAS, ARTERIAS VERTEBRALES Y CABEZAS DE FÉMUR MONTADAS DE FORMA MOVIBLE', NULL, 8, 2, 'A', 32, '2013-04-22 14:53:50', NULL, NULL, 489, NULL),
('COLUMNA FLEXIBLE -VERSIÓN CLÁSICA PINTADA CON CABEZAS DE FÉMUR Y DEMONSTRACIÓN DE MÚSCULOS', 'A58/3', 22, 'LAS COLUMNAS PINTADAS AGREGAN UNA NUEVA DIMENSIÓN PARA REALIZAR DEMOSTRACIONES. LAS INSERCIONES MUSCULARES (AZUL) Y EL ORIGEN DE LOS MÚSCULOS (ROJO) ESTÁN PINTADOS EN EL INNOMINADO IZQUIERDO, FÉMUR Y VÉRTEBRAS. \r\nMONTAJE TOTALMENTE FLEXIBLE PARA DEMOSTRACIONES EXPLICITAS, PELVIS MASCULINA, PLACA OCCIPITAL, HERNIA DE DISCO ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR, SALIDA DE LAS RAÍCES NERVIOSAS, ARTERIAS VERTEBRALES Y CABEZAS DE FÉMUR MONTADAS DE FORMA MOVIBLE', NULL, 8, 2, 'A', 32, '2013-04-22 14:54:48', NULL, NULL, 490, NULL),
('COLUMNA FLEXIBLE - VERSIÓN CLÁSICA CON PELVIS FEMENINO', 'A58/4', 22, 'MONTAJE TOTALMENTE FLEXIBLE PARA DEMOSTRACIONES EXPLICITAS, PELVIS FEMENINA, PLACA OCCIPITAL, HERNIA DE DISCO ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR, SALIDA DE LAS RAÍCES NERVIOSAS, ARTERIAS VERTEBRALES Y CABEZAS DE FÉMUR MONTADAS DE FORMA MOVIBLE', NULL, 8, 2, 'A', 32, '2013-04-22 14:55:47', NULL, NULL, 491, NULL),
('COLUMNA FLEXIBLE – VERSIÓN DE LUJO', 'A58/5', 22, 'MODELO QUE TIENE EL SACRO ABIERTO Y EXPONE EL TALLO CEREBRAL PARA REALIZAR ESTUDIOS AVANZADOS. OTRAS OPCIONES SON: MONTAJE TOTALMENTE FLEXIBLE PARA DEMOSTRACIONES EXPLICITAS, PELVIS MASCULINA, PLACA OCCIPITAL, HERNIA DE DISCO ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR, SALIDA DE LAS RAÍCES NERVIOSAS Y ARTERIAS VERTEBRALES', NULL, 8, 2, 'A', 32, '2013-04-22 14:56:30', NULL, NULL, 492, NULL),
('COLUMNA FLEXIBLE - VERSIÓN DE LUJO CON CABEZAS DE FÉMUR', 'A58/6', 22, 'MODELO QUE TIENE EL SACRO ABIERTO Y EXPONE EL TALLO CEREBRAL PARA REALIZAR ESTUDIOS AVANZADOS. OTRAS OPCIONES SON: MONTAJE TOTALMENTE FLEXIBLE PARA DEMOSTRACIONES EXPLICITAS, PELVIS MASCULINA, PLACA OCCIPITAL, HERNIA DE DISCO ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR, SALIDA DE LAS RAÍCES NERVIOSAS Y ARTERIAS VERTEBRALES Y CABEZAS DE FEMUR MONTADAS EN FORMA MOVIBLE', NULL, 8, 2, 'A', 32, '2013-04-22 14:57:13', NULL, NULL, 493, NULL),
('COLUMNA FLEXIBLE – VERSIÓN DE LUJO PINTADA CON CABEZAS DE FÉMUR', 'A58/7', 22, 'LAS COLUMNAS PINTADAS AGREGAN UNA NUEVA DIMENSIÓN PARA REALIZAR DEMOSTRACIONES. LAS INSERCIONES MUSCULARES (AZUL) Y EL ORIGEN DE LOS MÚSCULOS (ROJO) ESTÁN PINTADOS EN EL INNOMINADO IZQUIERDO, FÉMUR Y VÉRTEBRAS. MONTAJE TOTALMENTE FLEXIBLE PARA DEMOSTRACIONES EXPLICITAS, PELVIS MASCULINA, PLACA OCCIPITAL, HERNIA DE DISCO ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR, SALIDA DE LAS RAÍCES NERVIOSAS, ARTERIAS VERTEBRALES Y CABEZAS DE FÉMUR MONTADAS DE FORMA MOVIBLE', NULL, 8, 2, 'A', 32, '2013-04-22 14:57:50', NULL, NULL, 494, NULL),
('COLUMNA DIDÁCTICA FLEXIBLE', 'A58/8', 22, 'LAS 5 SECCIONES DE LA COLUMNA VERTEBRAL APARECEN DIFERENCIADAS POR COLOR: 7 COLUMNAS VERTEBRALES, 12 VÉRTEBRAS TORÁCICAS, 5 VÉRTEBRAS LUMBARES, SACRO Y COXIS. \r\nMONTAJE TOTALMENTE FLEXIBLE PARA DEMOSTRACIONES EXPLICITAS, PELVIS MASCULINA, PLACA OCCIPITAL, HERNIA DE DISCO ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR, SALIDA DE LAS RAÍCES NERVIOSAS, ARTERIAS VERTEBRALES', NULL, 8, 2, 'A', 32, '2013-04-22 14:58:40', NULL, NULL, 495, NULL),
('COLUMNA DIDÁCTICA FLEXIBLE CON CABEZAS DE FÉMUR', 'A58/9', 22, 'LAS 5 SECCIONES DE LA COLUMNA VERTEBRAL APARECEN DIFERENCIADAS POR COLOR: 7 COLUMNAS VERTEBRALES, 12 VÉRTEBRAS TORÁCICAS, 5 VÉRTEBRAS LUMBARES, SACRO Y COXIS. \r\nMONTAJE TOTALMENTE FLEXIBLE PARA DEMOSTRACIONES EXPLICITAS, PELVIS MASCULINA, PLACA OCCIPITAL, HERNIA DE DISCO ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR, SALIDA DE LAS RAÍCES NERVIOSAS, ARTERIAS VERTEBRALES Y CABEZAS DE FEMUR MONTADAS DE FORMA MOVIBLE', NULL, 8, 2, 'A', 32, '2013-04-22 14:59:23', NULL, NULL, 496, NULL),
('COLUMNA FLEXIBLE PARA USO INTENSIVO', 'A59/1', 22, 'MODELO DE LA COLUMNA VERTEBRAL FLEXIBLE. EL MONTAJE ESPECIAL SOBRE UNA VARA FLEXIBLE GARANTIZA UNA EXTREMA ESTABILIDAD. IDEAL PARA UN USO ACTIVO REGULAR, COMO EN COLEGIOS. MONTAJE TOTALMENTE FLEXIBLE PARA DEMOSTRACIONES EXPLICITAS. PELVIS MASCULINA, PLACA OCCIPITAL, HERNIA DE DISCO ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR, SALIDA DE LAS RAÍCES NERVIOSAS Y ARTERIAS VERTEBRALES', NULL, 8, 2, 'A', 32, '2013-04-22 14:59:58', NULL, NULL, 497, NULL),
('COLUMNA FLEXIBLE PARA USO INTENSIVO, CON CABEZAS DE FÉMUR', 'A59/2', 22, 'MONTAJE TOTALMENTE FLEXIBLE PARA DEMOSTRACIONES EXPLICITAS. PRESENTA PELVIS MASCULINA, PLACA OCCIPITAL, HERNIA DE DISCO ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR, SALIDA DE LAS RAÍCES NERVIOSAS, ARTERIAS VERTEBRALES, CABEZAS DE FÉMUR MONTADAS DE FORMA MOVIBLE. EL SOPORTE NO VIENE INCLUIDO', NULL, 8, 2, 'A', 32, '2013-04-22 15:00:49', 32, '2013-04-22 18:05:18', 498, NULL),
('SOPORTE MULTIFUNCIONAL PARA LA COLUMNA VERTEBRAL, 3 PIEZAS', 'A59/8', 22, 'SOPORTE DE ACERO NIQUELADO PARA COLOCACIÓN Y DEMOSTRACIÓN DE LA COLUMNA VERTEBRAL', NULL, 8, 2, 'A', 32, '2013-04-22 15:01:27', NULL, NULL, 499, NULL),
