('COLUMNA CERVICAL', 'A72', 22, 'MODELO FUNCIONAL DE LA COLUMNA CERVICAL COMPUESTA DE UNA LÁMINA HORIZONTAL DEL OCCIPITAL Y 7 VÉRTEBRAS CERVICALES. CON DISCO INTERVERTEBRAL, NERVIOS CERVICALES, ARTERIAS VERTEBRALES Y MÉDULA ESPINAL. MONTADA DE FORMA MÓVIL SOBRE SOPORTE', NULL, 8, 2, 'A', 32, '2013-04-22 15:08:32', NULL, NULL, 504, NULL),
('COLUMNA DORSAL', 'A73', 22, 'MODELO FUNCIONAL DE LA COLUMNA DORSAL COMPUESTA DE 12 VÉRTEBRAS TORÁCICAS CON DISCOS INTERVERTEBRALES, NERVIOS TORÁCICOS Y MÉDULA ESPINAL. MONTADA DE FORMA MÓVIL SOBRE SOPORTE', NULL, 8, 2, 'A', 32, '2013-04-22 15:09:12', NULL, NULL, 505, NULL),
('COLUMNA VERTEBRAL LUMBAR', 'A74', 22, 'COMPUESTA DE 5 VÉRTEBRAS LUMBARES CON DISCO INTERVERTEBRAL, SACRO CON TAPA, COXIS, NERVIOS VERTEBRALES Y DURAMADRE ESPINAL . MONTADA DE FORMA MÓVIL SOBRE SOPORTE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:09:48', NULL, NULL, 506, NULL),
('6 VÉRTEBRAS ARTICULADAS', 'A75', 22, 'COMPUESTAS DEL ATLAS, AXIS, OTRA VÉRTEBRA CERVICAL, DOS VÉRTEBRAS DORSALES CON DISCO INTERVERTEBRAL Y UNA VÉRTEBRA LUMBAR. DESMONTABLES, ARTICULADAS SOBRE UN SOPORTE', NULL, 8, 2, 'A', 32, '2013-04-22 15:10:29', NULL, NULL, 507, NULL),
('MODELO DE DISCOS VERTEBRALES LUMBARES QUE PRESENTA HERNIA DISCAL', 'A76', 22, 'MODELO COMPUESTO DE DOS VÉRTEBRAS LUMBARES CON NERVIOS VERTEBRALES, DURAMADRE ESPINAL Y 2 DISCOS INTERCAMBIABLES CON HERNIA MEDIANA Y LATERAL ENTRE LA 4TA Y 5TA VÉRTEBRA LUMBAR. SOBRE SOPORTE, DESMONTABLES', NULL, 8, 2, 'A', 32, '2013-04-22 15:11:19', NULL, NULL, 508, NULL),
('COLUMNA VERTEBRAL LUMBAR CON HERNIA DISCAL DORSO LATERAL', 'A76/5', 22, 'ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR. ADICIONALMENTE CON SACRO Y COXIS. MONTADA DE FORMA MÓVIL SOBRE SOPORTE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:11:57', NULL, NULL, 509, NULL),
('TRES DISCOS VERTEBRALES, MONTADOS FLEXIBLES', 'A76/8', 22, 'ANATÓMICAMENTE CORRECTOS HASTA EL ÚLTIMO DETALLE. MONTADOS DE FORMA FLEXIBLE CON NERVIOS VERTEBRALES Y DURAMADRE ESPINAL.', NULL, 8, 2, 'A', 32, '2013-04-22 15:13:09', NULL, NULL, 510, NULL),
('DISCOS LUMBARES, CON HERNIA DISCAL. MONTADOS FLEXIBLES SOBRE SOPORTE', 'A76/9', 22, 'CON NERVIOS VERTEBRALES Y DURAMADRE ESPINAL.', NULL, 8, 2, 'A', 32, '2013-04-22 15:13:48', NULL, NULL, 511, NULL),
('EQUIPO CON 7 BONELIKE™ VÉRTEBRAS CERVICALES', 'A790', 22, 'MODELO ORIGINAL ÚNICO EN EL MUNDO DE VÉRTEBRAS CERVICALES CON ESTRUCTURAS ANATÓMICAS REPRODUCIDAS CUIDADOSAMENTE DE FORMA DETALLADA. FABRICADO CON EL MATERIAL 3B BONELIKE™ DE EXCELENTE CALIDAD, QUE IMITA \r\nEXTREMADAMENTE BIEN UNA VÉRTEBRA REAL. PESO IGUAL AL PESO REAL. ESTAS VÉRTEBRAS SON ÚTILES COMO SUSTITUTOS DE LOS HUESOS DE VERDAD DE CARA A LA \r\nFORMACIÓN MÉDICA Y PARA DAR EXPLICACIONES A LOS PACIENTES. \r\nINCLUYE SOPORTE', NULL, 8, 2, 'A', 32, '2013-04-22 15:14:32', NULL, NULL, 512, NULL),
('EQUIPO CON 5 VÉRTEBRAS LUMBARES', 'A792', 22, 'MODELO ORIGINAL ÚNICO EN EL MUNDO DE VÉRTEBRAS LUMBARES CON ESTRUCTURAS ANATÓMICAS REPRODUCIDAS CUIDADOSAMENTE DE FORMA DETALLADA. FABRICADO CON EL MATERIAL 3B BONELIKE™ DE EXCELENTE CALIDAD, QUE IMITA \r\nEXTREMADAMENTE BIEN UNA VÉRTEBRA REAL. PESO IGUAL AL PESO REAL. ESTAS VÉRTEBRAS SON ÚTILES COMO SUSTITUTOS DE LOS HUESOS DE VERDAD DE CARA A LA FORMACIÓN MÉDICA Y PARA DAR EXPLICACIONES A LOS PACIENTES.\r\nINCLUYE SOPORTE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:15:44', NULL, NULL, 513, NULL),
('JUEGO DE 24 VÉRTEBRAS BONELIKE', 'A793', 22, 'JUEGO DE 24 VERTEBRAS INDIVIDUALES EN ESTUCHE PARA LA ENSEÑANZA. INCLUYE LAS 7 VÉRTEBRAS CERVICALES, 12 VERTEBRAS TORÁCICAS, 5 VÉRTEBRAS LUMBARES. PARA IDENTIFICACIÓN DE LAS VÉRTEBRAS ESTAS SE ENCUENTRAN MARCADAS (CI-VII, TI-XII, LI-V). MALETÍN DE TRANSPORTE EN COMPARTIMIENTOS SUBDIVIDIDOS EN SECCIONES PARA GUARDAR CADA UNA DE LAS 24 VERTEBRAS.', NULL, 8, 2, 'A', 32, '2013-04-22 15:16:20', NULL, NULL, 514, NULL),
('BONELIKE™ COLUMNA VERTEBRAL', 'A794', 22, 'MODELO NATURAL DE LA COLUMNA VERTEBRAL HUMANA, DE MONTAJE FLEXIBLE, CON LA EXCELENTE CALIDAD DE BONELIKETM. REPRODUCCIÓN FIEL DE TODOS LOS DETALLES ANATÓMICOS CON PESO REAL. CONSTA DE PELVIS MASCULINA Y HUESO OCCIPITAL. EL HUESO OCCIPITAL Y EL ATLAS SON REMOVIBLES.', NULL, 8, 2, 'A', 32, '2013-04-22 15:16:56', NULL, NULL, 515, NULL),
('ESTADIOS DEL PROLAPSO DEL CARTÍLAGO INTERVENTERAL Y DE LA DEGENERACIÓN VERTEBRAL', 'A795', 22, 'EL MODELO MUESTRA LOS CAMBIOS DEGENERATIVOS DE LOS CUERPOS VERTEBRALES Y DE LOS DISCOS INTERVERTEBRALES DE LA COLUMNA LUMBAR EN DIFERENTES ESTADIOS. LAS ESTRUCTURAS ÓSEAS ESTÁN REPRODUCIDAS MINUCIOSAMENTE PARA SER IGUALES A LAS VÉRTEBRAS LUMBARES HUMANAS ORIGINALES. DE ARRIBA ABAJO SE MUESTRAN LOS SIGUIENTES ESTADOS: DISCO INTERVERTEBRAL SANO, VÉRTEBRA LUMBAR (LI) SIN CAMBIOS DEGENERATIVOS, DISCO INTERVERTEBRAL CON PROMINENCIA, VÉRTEBRA LUMBAR (LII) CON CAMBIOS DEGENERATIVOS INICIALES, DISCO INTERVERTEBRAL CON PROLAPSO INTERNO, VÉRTEBRA LUMBAR (LIII) CON CAMBIOS DEGENERATIVOS AVANZADOS, DISCO INTERVERTEBRAL CON PROLAPSO INTRAFORAMINAL HACIA LA DERECHA, VÉRTEBRA LUMBAR (LIV) CON CAMBIOS DEGENERATIVOS MARCADOS Y ESTRECHAMIENTO ÓSEO DEL AGUJERO INTERVERTEBRAL IZQUIERDO, DISCO INTERVERTEBRAL MUY ESTRECHO, VÉRTEBRA LUMBAR (LV) CON CAMBIOS DEGENERATIVOS MARCADOS Y ESTRECHAMIENTO ÓSEO DEL AGUJERO INTERVERTEBRAL IZQUIERDO CON COMPRESIÓN DE LA RAÍZ DEL NERVIO RAQUÍDEO L5 IZQUIERDO.\r\nEL MODELO SE DESMONTA EN CUERPOS VERTEBRALES Y DISCOS INTERVERTEBRALES.', NULL, 8, 2, 'A', 32, '2013-04-22 15:17:34', NULL, NULL, 516, NULL),
('MODELO DE LA MÉDULA ESPINAL CON TERMINACIONES NERVIOSAS', 'C41', 22, 'EL MODELO MUESTRA LA ESTRUCTURA DE LA MÉDULA ESPINAL AMPLIADA CINCO VECES DE TAMAÑO. LA MÉDULA ESPINAL SE COMPONE DE LA SUSTANCIA GRIS, QUE RODEA EL CANAL CENTRAL, Y DE LA SUSTANCIA BLANCA. EN LA BASE, SE REPRESENTAN GRÁFICAMENTE, EN RELACIÓN CON LAS SUSTANCIAS GRIS Y BLANCA, LOS DISTINTOS CORTES TRANSVERSALES DEL CUELLO, EL PECHO, LA REGIÓN LUMBAR Y LA MÉDULA SACRA. SE SUMINISTRA CON LA BASE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:19:01', NULL, NULL, 517, NULL),
('COLUMNA FLEXIBLE, CON DISCOS INTERVERTEBRALES SUAVES', 'VB84', 22, 'LOS DISCOS SUAVES BRINDAN MAYOR REALISMO. ESTA COLUMNA ÚNICA MUESTRA CÓMO SE DEFORMAN LOS DISCOS DURANTE UNA POSICIÓN NORMAL Y ANORMAL. UTILÍCELA PARA DEMOSTRAR CUALQUIER NÚMERO DE CONDICIONES PATOLÓGICAS TALES COMO ESCOLIOSIS, LORDOSIS, CIFOSIS O SUBLUXACIONES. LA FORMACIÓN DE LA HERNIA SE PUEDE DEMOSTRAR CON COMPRESIÓN. ADEMÁS, EL SOPORTE ESPECIAL PERMITE VER EL MODELO DE MANERA DESPEJADA DURANTE LA DEMOSTRACIÓN Y PRESENTACIÓN. INCLUYE DURAMADRE ESPINAL Y NERVIOS VERTEBRALES. CON SOPORTE DESMONTABLE', NULL, 8, 2, 'A', 32, '2013-04-22 15:19:37', NULL, NULL, 518, NULL),
('CRÁNEO MINIATURA, DE 3 PIEZAS', 'A18/15', 23, 'CRÁNEO MINIATURA QUE REPRESENTA EXACTAMENTE Y CON FIDELIDAD DE DETALLES LAS ESTRUCTURAS ANATÓMICAS, ES DESMONTABLE EN CALOTA CRANEAL, BASE CRANEAL Y MANDÍBULA.', NULL, 8, 2, 'A', 32, '2013-04-22 15:22:16', 32, '2013-04-22 15:23:10', 519, NULL),
('CRÁNEO CLÁSICO, 3 PARTES', 'A20', 23, 'REPRODUCCIÓN MUY EXACTA DEL CRÁNEO HUMANO, FABRICADO Y TERMINADO MANUALMENTE CON UN MATERIAL RESISTENTE E IRROMPIBLE, REPRESENTACIÓN MUY EXACTA DE SURCOS, ORIFICIOS, APÓFISIS, SUTURAS Y OTROS. DESMONTABLE EN BÓVEDA DEL CRÁNEO, BASE DEL CRÁNEO Y MANDÍBULA. OPCIONALMENTE PUEDE USTED INTEGRAR UN CEREBRO (C18), QUE CONSISTE DE 5 PIEZAS', NULL, 8, 2, 'A', 32, '2013-04-22 15:23:38', NULL, NULL, 520, NULL),
('CRÁNEO CLÁSICO SOBRE COLUMNA CERVICAL, 4 PARTES', 'A20/1', 23, 'MODELO DE CRÁNEO HUMANO MONTADO SOBRE LA COLUMNA CERVICAL PARA LA ENSEÑANZA DE ANATOMÍA. REPRESENTACIÓN DEL ROMBENCÉFALO, LA MÉDULA ESPINAL, LOS NERVIOS CERVICALES, LAS ARTERIAS VERTEBRALES, LAS ARTERIAS BASILARES Y LAS ARTERIAS CEREBRALES POSTERIORES. REPRODUCCIÓN MUY EXACTA DEL CRÁNEO HUMANO, FABRICADO Y TERMINADO MANUALMENTE CON UN MATERIAL RESISTENTE E IRROMPIBLE, REPRESENTACIÓN MUY EXACTA DE SURCOS, ORIFICIOS, APÓFISIS, SUTURAS Y OTROS. DESMONTABLE EN BÓVEDA DEL CRÁNEO, BASE DEL CRÁNEO Y MANDÍBULA', NULL, 8, 2, 'A', 32, '2013-04-22 15:24:24', NULL, NULL, 521, NULL),
('CRÁNEO CLÁSICO DIDÁCTICO CON COLUMNA CERVICAL', 'A20/2', 23, 'ESTE MODELO MUESTRA LAS FORMAS Y RELACIONES DE LAS DISTINTAS LÁMINAS ÓSEAS DEL CRÁNEO CON LA AYUDA DE 19 COLORES DIDÁCTICOS. MONTADO FLEXIBLE SOBRE LA COLUMNA CERVICAL (C1, C2 Y C7 ESTÁN COLOREADAS), ESTE MODELO TAMBIÉN MUESTRA ROMBENCÉFALO, MÉDULA ESPINAL, NERVIOS ESPINALES DE LA COLUMNA CERVICAL, ARTERIAS VERTEBRALES, ARTERIA BASILAR Y ARTERIAS CEREBRALES POSTERIORES. DISPONE DE UN SOPORTE. REPRODUCCIÓN MUY EXACTA DEL CRÁNEO HUMANO, FABRICADO Y TERMINADO MANUALMENTE CON UN MATERIAL RESISTENTE E IRROMPIBLE. REPRESENTACIÓN MUY EXACTA DE SURCOS, ORIFICIOS, APÓFISIS, SUTURAS Y OTROS. DESMONTABLE EN BÓVEDA DEL CRÁNEO, BASE DEL CRÁNEO Y MANDÍBULA', NULL, 8, 2, 'A', 32, '2013-04-22 15:25:03', NULL, NULL, 522, NULL),
('CRÁNEO CLÁSICO CON CEREBRO', 'A20/9', 23, 'EL ENCÉFALO DIVIDIDO POR LA MITAD (C18) TIENE UNA FORMA ANATÓMICA IGUAL AL ORIGINAL. SU MITAD IZQUIERDA ES DESMONTABLE EN: LÓBULOS FRONTALES Y PARIETALES, LÓBULOS TEMPORALES Y OCCIPITALES, TRONCO ENCEFÁLICO, CEREBELO, REPRODUCCIÓN MUY EXACTA DEL CRÁNEO HUMANO. FABRICADO Y TERMINADO MANUALMENTE CON UN MATERIAL RESISTENTE E IRROMPIBLE. REPRESENTACIÓN MUY EXACTA DE SURCOS, ORIFICIOS, APÓFISIS, SUTURAS Y OTROS. DESMONTABLE EN BÓVEDA DEL CRÁNEO, BASE DEL CRÁNEO Y MANDÍBULA', NULL, 8, 2, 'A', 32, '2013-04-22 15:25:47', NULL, NULL, 523, NULL),
('CRÁNEO CLÁSICO TRANSPARENTE, 3 PARTES', 'A20/T', 23, 'ESTE CRÁNEO ÚNICO ES DE GRAN UTILIDAD PARA EL ESTUDIO DE LAS ESTRUCTURAS INTERNAS, QUE SÓLO SON VISIBLES A TRAVÉS DE LAS RADIOGRAFÍAS. REPRODUCCIÓN MUY EXACTA DEL CRÁNEO HUMANO, FABRICADO Y TERMINADO MANUALMENTE CON UN MATERIAL RESISTENTE E IRROMPIBLE. REPRESENTACIÓN MUY EXACTA DE SURCOS, ORIFICIOS, APÓFISIS, SUTURAS Y OTROS, DESMONTABLE EN BÓVEDA DEL CRÁNEO, BASE DEL CRÁNEO Y MANDÍBULA. OPCIONALMENTE PUEDE USTED INTEGRAR UN CEREBRO (C18), QUE CONSISTE DE 5 PIEZAS', NULL, 8, 2, 'A', 32, '2013-04-22 15:26:54', NULL, NULL, 524, NULL),
('CRÁNEO CLÁSICO CON NUMERACIÓN, 3 PARTES', 'A21', 23, 'CRÁNEO CON NUMERACIÓN Y PRESENTACIÓN EN COLOR DE LAS SUTURAS CRANEALES. REPRODUCCIÓN MUY EXACTA DEL CRÁNEO HUMANO, FABRICADO Y TERMINADO MANUALMENTE CON UN MATERIAL RESISTENTE E IRROMPIBLE. REPRESENTACIÓN MUY EXACTA DE SURCOS, ORIFICIOS, APÓFISIS, SUTURAS Y OTROS, DESMONTABLE EN BÓVEDA DEL CRÁNEO, BASE DEL CRÁNEO Y MANDÍBULA. OPCIONALMENTE PUEDE USTED INTEGRAR UN CEREBRO (C18), QUE CONSISTE DE 5 PIEZAS', NULL, 8, 2, 'A', 32, '2013-04-22 15:27:32', NULL, NULL, 525, NULL),
('CRÁNEO CLÁSICO CON MANDÍBULA ABIERTA, DESMONTABLE EN 3 PIEZAS', 'A22', 23, 'ESTE CRÁNEO DENTAL POSEE UNA MANDÍBULA QUE PERMITE VISUALIZAR LAS RAÍCES DENTALES CON SUS VASOS Y NERVIOS. ESTÁN NUMERADOS LOS HUESOS CRANEALES, LOS ELEMENTOS ÓSEOS, LOS SURCOS, LOS AGUJEROS Y OTRAS ESTRUCTURAS. LAS SUTURAS CRANEALES ESTÁN REPRESENTADAS CON COLORES, ASÍ COMO LOS VASOS DE LAS MENINGES Y LOS SENOS VENOSOS.', NULL, 8, 2, 'A', 32, '2013-04-22 15:30:01', NULL, NULL, 526, NULL),
('CRÁNEO CLÁSICO CON MANDÍBULA ABIERTA', 'A22/1', 23, 'MODELO DEL CRÁNEO CON MANDÍBULA ABIERTA, PINTADO. ORIGEN (ROJO) E INSERCIONES (AZUL) MUSCULARES REPRESENTADOS EN LA PARTE IZQUIERDA DEL MODELO. CON NUMERACIÓN. REPRODUCCIÓN MUY EXACTA DEL CRÁNEO HUMANO, FABRICADO Y TERMINADO MANUALMENTE CON UN MATERIAL RESISTENTE E IRROMPIBLE. REPRESENTACIÓN MUY EXACTA DE SURCOS, ORIFICIOS, APÓFISIS, SUTURAS Y OTROS. DESMONTABLE EN BÓVEDA DEL CRÁNEO, BASE DEL CRÁNEO Y MANDÍBULA. OPCIONALMENTE PUEDE USTED INTEGRAR UN CEREBRO (C18), QUE CONSISTE DE 5 PIEZAS', NULL, 8, 2, 'A', 32, '2013-04-22 15:30:38', NULL, NULL, 527, NULL),
('MODELO DEL CRÁNEO, PINTADO, 3 PARTES', 'A23', 23, 'EL ORIGEN (ROJO) Y LAS INSERCIONES (AZUL) MUSCULARES ESTÁN PINTADAS EN LA PARTE IZQUIERDA DEL CRÁNEO. CON NUMERACIÓN DE LOS HUESOS Y LAS ESTRUCTURAS DEL CRÁNEO EN EL LADO DERECHO. EL CRÁNEO DENOMINA MÁS DE 140 DETALLES ANATÓMICOS. REPRODUCCIÓN MUY EXACTA DEL CRÁNEO HUMANO. FABRICADO Y TERMINADO MANUALMENTE CON UN MATERIAL RESISTENTE E IRROMPIBLE. REPRESENTACIÓN MUY EXACTA DE SURCOS, ORIFICIOS, APÓFISIS, SUTURAS Y OTROS. DESMONTABLE EN BÓVEDA DEL CRÁNEO, BASE DEL CRÁNEO Y MANDÍBULA. OPCIONALMENTE PUEDE USTED INTEGRAR UN CEREBRO (C18), QUE CONSISTE DE 5 PIEZAS', NULL, 8, 2, 'A', 32, '2013-04-22 15:31:27', NULL, NULL, 528, NULL),
('CRÁNEO CLÁSICO, PINTADO, 3 PARTES', 'A23', 23, 'EL ORIGEN (ROJO) Y LAS INSERCIONES (AZUL) MUSCULARES ESTÁN PINTADAS EN LA PARTE IZQUIERDA DEL CRÁNEO. CON NUMERACIÓN DE LOS HUESOS Y LAS ESTRUCTURAS DEL CRÁNEO EN EL LADO DERECHO. EL CRÁNEO DENOMINA MÁS DE 140 DETALLES ANATÓMICOS.', NULL, 8, 2, 'I', 32, '2013-04-22 15:32:02', 1, '2013-09-28 13:39:44', 529, NULL),
('CRÁNEO FUNCIONAL CON MUSCULATURA PARA LA MASTICACIÓN, 2 PARTES', 'A24', 23, 'LOS MÚSCULOS PARA LA MASTICACIÓN (M. MASETERO, M. TEMPORAL, M. PTERIGOIDEO INTERNO Y EXTERNO) ESTÁN REPRESENTADOS EN FORMA DE BANDAS ELÁSTICAS. CON ESTE MODELO, USTED PUEDE DEMOSTRAR LA FUNCIÓN DE LA MUSCULATURA PARA LA MASTICACIÓN CON LA MANDÍBULA CERRADA Y ABIERTA, ASÍ COMO LOS MOVIMIENTOS MANDIBULARES HACIA LOS LADOS Y HACIA DELANTE. LA BÓVEDA CRANEAL ES DESMONTABLE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:32:48', NULL, NULL, 530, NULL),
('MODELO DEL CRÁNEO DE UN FETO', 'A25', 23, 'VACIADO NATURAL DE UN CRÁNEO FETAL EN LA SEMANA 30 DE EMBARAZO', NULL, 8, 2, 'A', 32, '2013-04-22 15:33:24', NULL, NULL, 531, NULL),
('CRÁNEO DE FETO, SOBRE SOPORTE', 'A26', 23, 'VACIADO NATURAL DE UN CRÁNEO FETAL EN LA SEMANA 30 DE EMBARAZO.', NULL, 8, 2, 'A', 32, '2013-04-22 15:33:57', NULL, NULL, 532, NULL),
('CRÁNEO DE DEMOSTRACIÓN DE LUJO, 10 PARTES', 'A27', 23, 'ESTA REPRODUCCIÓN DEL CRÁNEO HUMANO ES DE UNA CALIDAD EXTRAORDINARIA. LA BÓVEDA DEL CRÁNEO ES DESMONTABLE, LA BASE DEL CRÁNEO ESTÁ SECCIONADA POR LA MITAD. LAS ABERTURAS ESTÁN EN EL SENO FRONTAL, LA LÁMINA PERPENDICULAR Y EL VÓMER, A TRAVÉS DE LAS CUALES SE PUEDEN CONTEMPLAR LA PARTE LATERAL DE LA NARIZ Y EL SENO ESFENOIDAL. EN LA MITAD IZQUIERDA SE PUEDE SACAR EL HUESO TEMPORAL Y ABRIR LA ZONA DE LA MEMBRANA DEL TÍMPANO. EL MAXILAR Y LA MANDÍBULA ESTÁN ABIERTOS, DE MANERA QUE LOS NERVIOS ALVEOLARES RESULTAN VISIBLES. EN EL LADO DERECHO, EL HUESO TEMPORAL ESTÁ ABIERTO Y MUESTRA EL SENO SIGMOIDEO, EL TRAYECTO DEL NERVIO FACIAL Y LOS CONDUCTOS SEMICIRCULARES. OTRAS ABERTURAS SE ENCUENTRAN EN EL SENO MAXILAR Y EN LA MITAD DERECHA DE LA MANDÍBULA, DE FORMA QUE RESULTAN VISIBLES LAS RAÍCES DE LOS PREMOLARES Y MOLARES DE LA MANDÍBULA. LA OCLUSIÓN NATURAL Y LA POSIBILIDAD DE SACAR Y PONER CADA UNO DE LOS DIENTES, HACEN QUE ESTE MODELO DE CRÁNEO TENGA UN INTERÉS ESPECIAL PARA LOS DENTISTAS', NULL, 8, 2, 'A', 32, '2013-04-22 15:35:49', NULL, NULL, 533, NULL);
INSERT INTO `productos` (`titulo`, `sku`, `categoria`, `descripcion`, `precio`, `marca`, `uso`, `estado`, `created_by`, `created_at`, `updated_by`, `updated_at`, `id`, `ficha`) VALUES
('CRÁNEO DE DEMOSTRACIÓN DE LUJO CON VITRINA', 'A27/9', 23, 'ESTA REPRODUCCIÓN DEL CRÁNEO HUMANO ES DE UNA CALIDAD EXTRAORDINARIA. LA BÓVEDA DEL CRÁNEO ES DESMONTABLE, LA BASE DEL CRÁNEO ESTÁ SECCIONADA POR LA MITAD. LAS ABERTURAS ESTÁN EN EL SENO FRONTAL, LA LÁMINA PERPENDICULAR Y EL VÓMER, A TRAVÉS DE LAS CUALES SE PUEDEN CONTEMPLAR LA PARTE LATERAL DE LA NARIZ Y EL SENO ESFENOIDAL. EN LA MITAD IZQUIERDA SE PUEDE SACAR EL HUESO TEMPORAL Y ABRIR LA ZONA DE LA MEMBRANA DEL TÍMPANO. EL MAXILAR Y LA MANDÍBULA ESTÁN ABIERTOS, DE MANERA QUE LOS NERVIOS ALVEOLARES RESULTAN VISIBLES. EN EL LADO DERECHO, EL HUESO TEMPORAL ESTÁ ABIERTO Y MUESTRA EL SENO SIGMOIDEO, EL TRAYECTO DEL NERVIO FACIAL Y LOS CONDUCTOS SEMICIRCULARES. OTRAS ABERTURAS SE ENCUENTRAN EN EL SENO MAXILAR Y EN LA MITAD DERECHA DE LA MANDÍBULA, DE FORMA QUE RESULTAN VISIBLES LAS RAÍCES DE LOS PREMOLARES Y MOLARES DE LA MANDÍBULA. LA OCLUSIÓN NATURAL Y LA POSIBILIDAD DE SACAR Y PONER CADA UNO DE LOS DIENTES, HACEN QUE ESTE MODELO DE CRÁNEO TENGA UN INTERÉS ESPECIAL PARA LOS DENTISTAS', NULL, 8, 2, 'A', 32, '2013-04-22 15:36:28', NULL, NULL, 534, NULL),
('BONELIKE™ CRÁNEO – HUESOS DE MEDIO CRÁNEO, 4 PARTES', 'A280', 23, 'LA MITAD IZQUIERDA ÓSEA DEL CRÁNEO ESTÁ PENSADA ESPECIALMENTE PARA LOS ESTUDIANTES. LA MITAD DEL CRÁNEO ES DESMONTABLE EN BÓVEDA DEL CRÁNEO, BASE DEL CRÁNEO, MANDÍBULA Y TABIQUE NASAL. ES UN MODELO DE PRIMERA CATEGORÍA Y DE PRECIO AJUSTADO, CON EL QUE SE PUEDEN ESTUDIAR TODAS LAS ESTRUCTURAS ANATÓMICAS.', NULL, 8, 2, 'A', 32, '2013-04-22 15:38:33', NULL, NULL, 535, NULL),
('BONELIKE™ CRÁNEO – CRÁNEO ÓSEO, 6 PARTES', 'A281', 23, 'ESTA VERSIÓN MUESTRA UN CRÁNEO COMPLETO DIVIDIDO SAGITALMENTE POR LA MITAD. SE DESMONTA EN AMBAS MITADES DE LA BÓVEDA CRANEAL Y DE LA BASE DEL CRÁNEO, EL TABIQUE NASAL, ASÍ COMO TODO EL MAXILAR INFERIOR. PARA LA DEMOSTRACIÓN DE LOS MOVIMIENTOS DE MASTICACIÓN, LA MANDÍBULA ESTÁ MONTADA PARA TENER MOVILIDAD. ESTE MODELO DE CRÁNEO ESTÁ INDICADO PARA EL ESTUDIO DE LAS ESTRUCTURAS ÓSEAS Y DE LA ANATOMÍA COMPLEJA DEL CRÁNEO HUMANO.', NULL, 8, 2, 'A', 32, '2013-04-22 15:39:06', NULL, NULL, 536, NULL),
('BONELIKE™ CRÁNEO – CRÁNEO COMBINADO TRANSPARENTE / HUESOS, 8 PARTES', 'A282', 23, 'LA COMBINACIÓN DE UNA MITAD DE CRÁNEO TRANSPARENTE Y OTRA MITAD ÓSEA POSIBILITA QUE LOS ESTUDIANTES DE ANATOMÍA TENGAN UNA REPRESENTACIÓN TOPOGRÁFICA DE LAS ESTRUCTURAS, QUE EN OTROS MODELOS DE CRÁNEO NO SON VISIBLES. LA MITAD DERECHA DEL CRÁNEO, QUE ES TRANSPARENTE, FACILITA EL ESTUDIO DE LOS DETALLES ANATÓMICOS FUNDAMENTALES, COMO LA UBICACIÓN DE LOS SENOS PARANASALES. EN COMBINACIÓN CON LA MITAD IZQUIERDA, QUE ES LA PARTE ÓSEA, PRESENTA DE FORMA DIRECTA Y SENCILLA EL RECONOCIMIENTO DE ESTRUCTURAS QUE NO ERAN VISIBLES. LA TRANSPARENCIA DE LOS MAXILARES FACILITA EL RECONOCIMIENTO DE LOS DIENTES Y LAS RAÍCES DENTALES. LOS DIENTES SE SACAN PARA PODER OBSERVARLOS CON TODO DETALLE. LA MITAD ÓSEA DEL CRÁNEO TAMBIÉN LLEVA LA MUSCULATURA EXTERNA DE LA MASTICACIÓN (M. MASETERO, M. TEMPORAL). PARA DEMOSTRAR LOS MOVIMIENTOS DE MASTICACIÓN, EL MAXILAR INFERIOR SE PUEDE MOVER. ESTOS DETALLES HACEN QUE ESTE CRÁNEO SEA DE GRAN UTILIDAD PARA LOS DENTISTAS. EL CRÁNEO SE DESMONTA EN AMBAS MITADES DE LA BÓVEDA DEL CRÁNEO Y DE LA BASE DEL CRÁNEO, EL TABIQUE NASAL, EL MAXILAR INFERIOR COMPLETO Y AMBOS MÚSCULOS MASTICADORES.', NULL, 8, 2, 'A', 32, '2013-04-22 15:39:42', NULL, NULL, 537, NULL),
('BONELIKE™ CRÁNEO – CRÁNEO DIDÁCTICO DE LUJO, 7 PARTES', 'A283', 23, 'ESTE CRÁNEO EXTRAORDINARIO Y DE GRAN VALOR ACLARA TODAS LAS DUDAS ANATÓMICAS. LA POSIBILIDAD DE CONOCER LAS ESTRUCTURAS EN LA MITAD TRANSPARENTE DEL CRÁNEO Y LOS HUESOS EN LA MITAD ÓSEA, HACE QUE ESTE CRÁNEO TENGA UN ELEVADO INTERÉS DIDÁCTICO. EN LA MITAD DERECHA TRANSPARENTE DEL CRÁNEO SE PUEDE RECONOCER DESDE FUERA LA UBICACIÓN DE LOS SENOS PARANASALES, QUE ESTÁN COLOREADOS PARA DIFERENCIARLOS: SENO MAXILAR (AMARILLO), CÉLULAS ETMOIDALES (NARANJA), SENO FRONTAL (VERDE), SENO ESFENOIDAL (VIOLETA). TAMBIÉN ESTÁN REPRESENTADOS CON COLORES LOS SENOS SANGUÍNEOS, ASÍ COMO LAS ARTERIAS DEL CUELLO Y DE LA CARA: SENO DE LA DURAMADRE (AZUL), A. CARÓTIDA PRIMITIVA, A. CARÓTIDA EXTERNA, A. CARÓTIDA INTERNA Y LA RAMA DE LA A. MENÍNGEA (ROJO). UNA MITAD DEL CEREBRO, VISIBLE TAMBIÉN A TRAVÉS DE LA BÓVEDA DEL CRÁNEO, MUESTRA LAS ZONAS RELACIONADAS CON EL CEREBRO Y EL CURSO DE LOS SENOS. A TRAVÉS DE LOS MAXILARES TRANSPARENTES SE VEN LOS DIENTES Y SUS RAÍCES. LOS DIENTES SE PUEDEN SACAR UNO A UNO. LA MANDÍBULA ES MOVIBLE PARA DEMOSTRAR LOS MOVIMIENTOS DE MASTICACIÓN. EL CRÁNEO ESTÁ MONTADO SOBRE LA COLUMNA VERTEBRAL CERVICAL Y DESMONTABLE EN AMBOS LADOS DE LA BÓVEDA DEL CRÁNEO, LA MITAD IZQUIERDA DE LA BASE DEL CRÁNEO, EL TABIQUE NASAL, LA MANDÍBULA COMPLETA Y LA MITAD DEL CEREBRO.', NULL, 8, 2, 'A', 32, '2013-04-22 15:40:17', NULL, NULL, 538, NULL),
('CRÁNEO MICROCEFÁLICO', 'A29/1', 23, 'CRÁNEO DE VARÓN JOVEN. ESTE CRÁNEO MICROCEFÁLICO DE UNA PIEZA MUESTRA UN ABSCESO ALVEOLAR DEL MAXILAR SUPERIOR DERECHO, EN EL QUE EL DIENTE CANINO SUPERIOR DERECHO ESTÁ RETENIDO. LAS MUELAS MUESTRAN SEÑALES DE DESGASTE. 27 DIENTES. VACIADO NATURAL', NULL, 8, 2, 'A', 32, '2013-04-22 15:40:54', NULL, NULL, 539, NULL),
('CRÁNEO HIDROCEFÁLICO', 'A29/2', 23, 'EL CRÁNEO ENSANCHADO ES TÍPICO PARA ESTA CONDICIÓN QUE A VECES ES FATAL. LA PARTE SUPERIOR DEL CRÁNEO ESTÁ CUBIERTA PARCIALMENTE CON FORMACIÓN PERIÓSTICA. EL PRIMER MOLAR Y EL MOLAR EN LA PARTE DERECHA DE LA MANDÍBULA ESTÁN ENFERMOS.', NULL, 8, 2, 'A', 32, '2013-04-22 15:41:41', NULL, NULL, 540, NULL),
('CRÁNEO CON PALADAR Y MAXILAR HENDIDO', 'A29/3', 23, 'CRÁNEO MASCULINO QUE PRESENTA UN DEFECTO FACIAL CONGÉNITO SEVERO EN LA PARTE IZQUIERDA DEL CRÁNEO. EL CRÁNEO CONSTA DE UNA SOLA PIEZA Y TIENE 29 DIENTES. VACIADO DEL MOLDE DE UNA MUESTRA HUMANA', NULL, 8, 2, 'A', 32, '2013-04-22 15:42:44', NULL, NULL, 541, NULL),
('CRÁNEO DESMONTABLE EN 22 PIEZAS', 'A290', 23, 'MODELO DE ASPECTO NATURAL QUE PERMITE APRECIAR FÁCILMENTE LA ESTRUCTURA COMPLEJA DEL CRÁNEO DEBIDO A QUE SUS 22 HUESOS SE PUEDEN DESMONTAR UNO A UNO. LAS CONEXIONES ENTRE LOS HUESOS DEL MODELO SON ESTABLES Y POCO VISIBLES Y RESULTA MUY SENCILLO MONTAR Y DESMONTAR CADA UNO DE LOS HUESOS PORQUE LAS SUTURAS DE ESTE MODELO DE CRÁNEO ESTÁN MUY SIMPLIFICADAS. LOS 22 HUESOS ESTÁN REPRESENTADOS EN UN COLOR IDÉNTICO AL DEL HUESO NATURAL. INCLUYE HUESO PARIETAL (IZQUIERDO Y DERECHO), OCCIPITAL, FRONTAL, TEMPORAL (IZQUIERDO Y DERECHO), ESFENOIDES, ETMOIDES, VÓMER, CIGOMÁTICO (IZQUIERDO Y DERECHO), MAXILAR SUPERIOR CON DIENTES (IZQUIERDO Y DERECHO), HUESO PALATINO (IZQUIERDO Y DERECHO), CORNETE NASAL (IZQUIERDO Y DERECHO), HUESO LAGRIMAL (IZQUIERDO Y DERECHO), HUESO NASAL (IZQUIERDO Y DERECHO) Y MAXILAR INFERIOR CON DIENTES', NULL, 8, 2, 'A', 32, '2013-04-22 15:43:23', NULL, NULL, 542, NULL),
('CRÁNEO DESMONTABLE VERSIÓN DIDÁCTICA', 'A291', 23, 'ESTE MODELO REALISTA Y DE GRAN CALIDAD ESTÁ HECHO DE PLÁSTICO RESISTENTE INDEFORMABLE Y PERMITE APRECIAR FÁCILMENTE LA COMPLEJA ESTRUCTURA DEL CRÁNEO HUMANO. LOS 22 HUESOS QUE LO COMPONEN REPRODUCEN FIELMENTE LOS DETALLES Y RESULTAN MUY SENCILLOS DE MONTAR Y DESMONTAR GRACIAS A UNAS CONEXIONES ENTRE HUESOS POCO VISIBLES Y ESTABLES. LA MANIPULACIÓN DEL CRÁNEO ES SEGURA Y SENCILLA. ADEMÁS, ESTE CRÁNEO NO SE DESMONTA CONSTANTEMENTE, COMO OCURRE CON LOS MODELOS CON CONEXIONES MAGNÉTICAS MÁS INESTABLES. LOS BORDES DENTADOS DE LAS SUTURAS REFLEJAN EL GRADO DE SOLDADURA DE UN CRÁNEO HUMANO VERDADERO CON GRAN REALISMO.\r\nLOS HUESOS ESTÁN REPRESENTADOS EN 9 COLORES DISTINTOS PARA FACILITAR LA IDENTIFICACIÓN DE CADA UNA DE LAS PARTES DEL CRÁNEO. LOS PARES DE PLACAS ÓSEAS PRESENTAN EL MISMO COLOR.', NULL, 8, 2, 'A', 32, '2013-04-22 15:44:07', NULL, NULL, 543, NULL),
('CABEZA CON CUELLO, 4 PIEZAS', 'C07', 23, 'LA MITAD IZQUIERDA DE ESTE MODELO SECCIONADO MEDIALMENTE DE TAMAÑO NATURAL MUESTRA LA MUSCULATURA CON NERVIOS, VASOS Y ESTRUCTURAS ÓSEAS Y UN HEMISFERIO CEREBRAL EXTRAÍBLE. LA CABEZA ESTÁ MONTADA EN UNA PARTE CERVICAL DESMONTABLE, QUE ESTÁ SECCIONADA HORIZONTAL Y TRANSVERSALMENTE. SUMINISTRO CON TABLERO.', NULL, 8, 2, 'A', 32, '2013-04-22 15:44:39', NULL, NULL, 544, NULL),
('MODELO DE LA CABEZA, 6 PIEZAS', 'C09/1', 23, 'MODELO DE LA CABEZA PARA NECESIDADES ELEVADAS. ESTA CABEZA DE 6 PIEZAS Y DE TAMAÑO NATURAL ESTÁ MONTADA SOBRE UN SUPORTE E INCLUYE UNA MITAD DEL CEREBRO DESMONTABLE EN 4 PIEZAS CON ARTERIAS. EL GLOBO OCULAR CON NERVIO ÓPTICO TAMBIÉN ES DESMONTABLE Y EN UN LADO SE EXPONE LA NARIZ, CAVIDAD BUCAL, FARINGE, OCCIPITAL Y BASE CRANEAL. CON SOPORTE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:45:18', NULL, NULL, 545, NULL),
('MODELO DE LA CABEZA, 3 PIEZAS', 'C10/1', 23, 'ESTA CABEZA DE 3 PIEZAS Y DE TAMAÑO NATURAL ESTÁ MONTADA SOBRE UN SUPORTE E INCLUYE UNA MITAD DEL CEREBRO DESMONTABLE CON ARTERIAS Y UN GLOBO OCULAR CON NERVIO ÓPTICO. UN LADO EXPONE LA NARIZ, CAVIDAD BUCAL, FARINGE, OCCIPITAL Y LA BASE DEL CRÁNEO. LAS PARTES VIENEN ENUMERADAS. SOBRE BASE DESMONTABLE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:46:21', NULL, NULL, 546, NULL),
('CORTE MEDIAL DE LA CABEZA', 'C12', 23, 'ESTE MODELO EN RELIEVE MUESTRA TODAS LAS ESTRUCTURAS RELEVANTES CON GRAN DETALLE. MONTADO SOBRE SUPORTE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:46:59', NULL, NULL, 547, NULL),
('CORTE MEDIAL Y FRONTAL DE LA CABEZA', 'C13', 23, '2 MODELOS EN RELIEVE SOBRE TABLERO.', NULL, 8, 2, 'A', 32, '2013-04-22 15:47:33', NULL, NULL, 548, NULL),
('MEDIA CABEZA CON MUSCULATURA', 'C14', 23, 'MODELO DEL CORTE MEDIAL QUE MUESTRA LAS ESTRUCTURAS EXTERNAS, SUPERFICIALES E INTERNAS DE LA CABEZA Y EL CUELLO. SOBRE SOPORTE, DESMONTABLE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:48:08', NULL, NULL, 549, NULL),
('ENCÉFALO DE LUJO CON ARTERIAS', 'C25', 23, 'MODELO FUNCIONAL DEL ENCÉFALO CON ARTERIAS EN LA BASE DE LA CABEZA, DESMONTABLE EN 8 PIEZAS. LA CABEZA ESTÁ DIVIDIDA HORIZONTALMENTE POR ENCIMA DE LA BASE DE CRÁNEO. ESTE MODELO DE UN ENCÉFALO DE LUJO MEDIANAMENTE DIVIDIDO MUESTRA LAS ARTERIAS CEREBRALES COMO TAMBIÉN LA ARTERIA BASILAR DESMONTABLE. SOBRE BASE DESMONTABLE. AMBAS MITADES SE PUEDEN ENSAMBLAR EN: FRONTAL CON LÓBULOS PARIETALES, LÓBULOS TEMPORAL Y OCCIPITAL, MITAD DEL TALLO CEREBRAL Y MITAD DEL CEREBELO', NULL, 8, 2, 'A', 32, '2013-04-22 15:48:44', NULL, NULL, 550, NULL),
('CORTE MEDIAL DE LA CABEZA, DESMONTABLE EN 5 PIEZAS', 'VB156', 23, 'MODELO EN RELIEVE. LAS SIGUIENTES PARTES SON DESMONTABLES: LENGUA CON GLÁNDULA SUBLINGUAL Y MUSCULATURA DE LA BASE DE LA BOCA, CARTÍLAGO DE LA TIROIDE CON MUSCULATURA ASOCIADA, LARINGE Y GLÁNDULA TIROIDEA', NULL, 8, 2, 'A', 32, '2013-04-22 15:49:20', NULL, NULL, 551, NULL),
('ENCÉFALO INTRODUCTORIO, DESMONTABLE EN 2 PIEZAS', 'C15', 24, 'UN ENCÉFALO MEDIANAMENTE DIVIDIDO, PERFECTO PARA LOS PRIMEROS ESTUDIOS DEBIDO A SU BAJO COSTO. SOBRE SOPORTE DESMONTABLE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:50:33', NULL, NULL, 552, NULL),
('ENCÉFALO ECONÓMICO, DESMONTABLE EN 2 PIEZAS', 'C15/1', 24, 'ENCÉFALO DIVIDIDO MEDIANAMENTE, CADA ESTRUCTURA DEL ENCÉFALO TIENE EL MISMO COLOR. SOBRE SOPORTE DESMONTABLE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:51:08', NULL, NULL, 553, NULL),
('ENCÉFALO CLÁSICO, DESMONTABLE EN 4 PIEZAS', 'C16', 24, 'TODAS LAS ESTRUCTURAS DE ESTE ENCÉFALO MEDIANAMENTE DIVIDIDO ESTÁN PINTADAS A MANO, ENUMERADAS E IDENTIFICADAS. SOBRE SOPORTE DESMONTABLE. LA MITAD DERECHA SE PUEDE DESMONTAR EN: FRONTAL CON LÓBULOS PARIETALES, LÓBULOS TEMPORAL CON OCCIPITAL Y MITAD DEL CEREBELO', NULL, 8, 2, 'A', 32, '2013-04-22 15:51:42', NULL, NULL, 554, NULL),
('MODELO DEL ENCÉFALO, DESMONTABLE, 8 PIEZAS', 'C17', 24, 'UN MODELO DEL ENCÉFALO HUMANO MUY DETALLADO DIVIDIDO MEDIANAMENTE. SOBRE SOPORTE DESMONTABLE. AMBAS MITADES SE PUEDEN DESMONTAR EN: FRONTAL CON LÓBULOS PARIETALES, LÓBULOS TEMPORAL Y OCCIPITAL, MITAD DEL TALLO CEREBRAL Y MITAD DEL CEREBELO', NULL, 8, 2, 'A', 32, '2013-04-22 15:52:17', NULL, NULL, 555, NULL),
('ENCÉFALO CLÁSICO, 5 PARTES', 'C18', 23, 'ESTE MODELO SECCIONADO MEDIANAMENTE ES EL MODELO ANATÓMICO ORIGINAL DE UN ENCÉFALO HUMANO REAL. SU MITAD IZQUIERDA ESTÁ DIVIDIDA EN: LÓBULOS FRONTAL Y PARIETAL, LÓBULOS TEMPORAL Y OCCIPITAL, TRONCO ENCEFÁLICO Y CEREBELO', NULL, 8, 2, 'A', 32, '2013-04-22 15:52:54', NULL, NULL, 556, NULL),
('CEREBRO DE LUJO CON ARTERIAS', 'C20', 23, 'MODELO FUNCIONAL DEL CEREBRO, CON ARTERIAS, DESMONTABLE, 9 PIEZAS. ESTE MODELO DE UN ENCÉFALO DE LUJO MEDIALMENTE DIVIDIDO MUESTRA LAS ARTERIAS CEREBRALES COMO TAMBIÉN LA ARTERIA BASILAR DESMONTABLE. SOBRE SOPORTE DESMONTABLE. AMBAS MITADES SE PUEDEN ENSAMBLAR EN: FRONTAL CON LÓBULOS PARIETALES, LÓBULOS TEMPORAL Y OCCIPITAL, MITAD DEL TALLO CEREBRAL Y MITAD DEL CEREBELO', NULL, 8, 2, 'A', 32, '2013-04-22 15:53:42', NULL, NULL, 557, NULL),
('CEREBRO NEURO-ANATÓMICO, DESMONTABLE EN 8 PIEZAS', 'C22', 24, 'ESTE ENCÉFALO DE LUJO ESTÁ DIVIDIDO MEDIANAMENTE. EN LA MITAD DERECHA, ENCONTRARÁ UNA AGRUPACIÓN Y REPRESENTACIÓN DEL LÓBULO CEREBRAL A COLOR. LA MITAD IZQUIERDA MUESTRA: REGIÓN PRE Y POSCENTRAL, ÁREAS DE BROCA Y WERNICKE, GIRO DE HESCHL, NERVIOS CEREBRALES, VENTRÍCULOS. AMBAS MITADES SE PUEDEN DESMONTAR EN: LÓBULOS FRONTAL Y PARIETAL, LÓBULOS TEMPORAL CON OCCIPITAL, MITAD DEL TALLO CEREBRAL, MITAD DEL CEREBELO.\r\nSOBRE SOPORTE DESMONTABLE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:54:23', NULL, NULL, 558, NULL),
('MODELO SECCIONADO DEL ENCÉFALO, 5 PARTES', 'K25', 24, 'ESTE MODELO SECCIONADO MEDIANAMENTE ES EL MODELO ANATÓMICO ORIGINAL DE UN ENCÉFALO HUMANO REAL. SU MITAD IZQUIERDA ESTÁ DIVIDIDA EN: LÓBULOS FRONTAL Y PARIETAL, LÓBULOS TEMPORAL Y OCCIPITAL, TRONCO ENCEFÁLICO, CEREBELO. SOBRE SOPORTE DESMONTABLE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:54:58', NULL, NULL, 559, NULL),
('ENCÉFALO CON ARTERIAS, DESMONTABLE EN 5 PIEZAS', 'VH405', 24, 'DIVIDIDO MEDIANAMENTE CON LA MITAD DERECHA MOSTRANDO LAS ARTERIAS. LA MITAD IZQUIERDA SE PUEDE DESMONTAR EN: FRONTAL CON LÓBULOS PARIETALES, LÓBULOS TEMPORAL Y OCCIPITAL, MITAD DEL TALLO CEREBRAL, MITAD DEL CEREBELO. \r\nSOBRE SOPORTE DESMONTABLE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:57:37', NULL, NULL, 560, NULL),
('ENCÉFALO GIGANTE, 2,5 VECES EL TAMAÑO NATURAL, DESMONTABLE EN 14 PIEZAS', 'VH409', 24, 'UN MODELO INTEGRAL DE UN ENCÉFALO, MUY ÚTIL COMO AYUDA PARA LA ENSEÑANZA, ESPECIALMENTE PARA GRANDES GRUPOS DE ESTUDIANTES. TODAS LAS ESTRUCTURAS DEL ENCÉFALO Y LOS VENTRÍCULOS SE PUEDEN VER A TRAVÉS DE LAS DIVISIONES MEDIANAS, FRONTALES Y TRASVERSALES. SOBRE SOPORTE DESMONTABLE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:58:17', NULL, NULL, 561, NULL),
('VENTRÍCULO CEREBRAL', 'VH410', 23, 'ESTE MODELO MUESTRA AMBOS VENTRÍCULOS LATERALES, EL 3EN Y 4º VENTRÍCULO Y EL ACUEDUCTO CEREBRAL (SILVIO). SOBRE SOPORTE.', NULL, 8, 2, 'A', 32, '2013-04-22 15:58:51', NULL, NULL, 562, NULL),
('MEDIO ESQUELETO, DESARTICULADO', 'A04', 25, 'VIENE COMPLETO CON CRÁNEO ARTICULADO, ESTERNÓN, HIOIDES Y COLUMNA VERTEBRAL. UNA MANO Y UN PIE ESTÁN ARTICULADOS CON ALAMBRES. VIENE CON UNA CAJA DE ALMACENAMIENTO SECCIONADA', NULL, 8, 2, 'A', 32, '2013-04-22 16:23:27', NULL, NULL, 563, NULL),
('ESQUELETO COMPLETO, DESARTICULADO, CON CRÁNEO DE 3 PIEZAS', 'A05/1', 25, 'TIENE UNA MANO Y UN PIE ARTICULADOS EN UN ALAMBRE. SUS CONTRA PIEZAS ESTÁN ENSARTADAS DE FORMA SUELTA EN NYLON. VIENE CON UNA CAJA ESTABLE DE ALMACENAMIENTO', NULL, 8, 2, 'A', 32, '2013-04-22 16:24:33', NULL, NULL, 564, NULL),
('ESQUELETO CON DESCRIPCIÓN DE MÚSCULOS, DESARTICULADO', 'A05/2', 25, 'ESTA VERSIÓN ESPECIAL ESTÁ PINTADA A MANO Y ENUMERADA CON EL FIN DE MOSTRAR LOS ORÍGENES DE LOS MÚSCULOS EN ROJO Y LAS INSERCIONES MUSCULARES EN AZUL EN EL LADO IZQUIERDO. TODOS LOS HUESOS Y LAS ESTRUCTURAS ÓSEAS, TALES COMO FISURAS, FORAMINA Y PROCESOS ESTÁN ENUMERADOS MANUALMENTE EN EL LADO DERECHO. EL CRÁNEO ES DE 3 PIEZAS. UNA MANO Y UN PIE ESTÁN ARTICULADOS EN UN ALAMBRE. SUS CONTRA PIEZAS ESTÁN ENSARTADAS EN FORMA SUELTA EN NYLON VIENE CON UNA TARJETA DE DIFERENTES IDIOMAS PARA IDENTIFICAR MÁS DE 600 ESTRUCTURAS ANATÓMICAS ENUMERADAS. VIENE CON UNA CAJA DE ALMACENAMIENTO SECCIONADA', NULL, 8, 2, 'A', 32, '2013-04-22 16:25:18', NULL, NULL, 565, NULL),
('ESQUELETO CLÁSICO STAN, SOBRE SOPORTE ROTATORIO', 'A10', 25, 'MODELO DE ESQUELETO EN MONTAJE CON ACABADOS A MANO, FABRICADO CON MATERIAL IRROMPIBLE Y DE LARGA DURACIÓN. PESO DE LOS 200 HUESOS MUY APROXIMADO AL PESO REAL, TAMAÑO NATURAL. CRÁNEO MONTADO EN 3 PIEZAS, DIENTES COLOCADOS UNO A UNO, EXTREMIDADES DESMONTABLES DE FORMA RÁPIDA Y SENCILLA. SUMINISTRADO CON SOPORTE Y PROTECTOR DEL POLVO', NULL, 8, 2, 'A', 32, '2013-04-22 16:25:51', NULL, NULL, 566, NULL),
('ESQUELETO CLÁSICO MAX', 'A11', 25, 'MODELO DEL ESQUELETO HUMANO EN SOPORTE DE 5 PATAS. ESTÁN INCLUIDAS MÁS DE 600 ESTRUCTURAS MÉDICAS/ANATÓMICAS Y EN LA PARTE IZQUIERDA SE\r\nENCUENTRAN, POR EJEMPLO, EL LUGAR DE ORIGEN DE LOS MÚSCULOS (ROJO) Y LAS INSERCIONES\r\nMUSCULARES (AZUL) MÁS IMPORTANTES Y EN LA PARTE DERECHA, LOS HUESOS, LAS FISURAS Y LOS\r\nORIFICIOS, TODOS NUMERADOS A MANO.', NULL, 8, 2, 'A', 32, '2013-04-22 16:27:01', NULL, NULL, 567, NULL),
('ESQUELETO CLÁSICO LEO CON LIGAMENTOS ARTICULARES, EN SOPORTE DE 5 PATAS CON RUEDAS', 'A12', 25, 'MODELO DE ESQUELETO QUE MUESTRA LA REPRESENTACIÓN DE LA INTERACCIÓN ESTRUCTURAL ENTRE HUESOS Y LIGAMENTOS ARTICULARES. SUS LIGAMENTOS ARTICULARES ELÁSTICOS EN LAS GRANDES ARTICULACIONES (HOMBRO, CODO, CADERA Y RODILLA) ESTÁN MONTADOS EN EL LADO DERECHO. MONTAJE CON ACABADOS A MANO, FABRICADO CON MATERIAL IRROMPIBLE Y DE LARGA DURACIÓN. PESO DE LOS 200 HUESOS MUY APROXIMADO AL PESO REAL, TAMAÑO NATURAL, CRÁNEO MONTADO EN 3 PIEZAS, DIENTES COLOCADOS UNO A UNO, EXTREMIDADES DESMONTABLES DE FORMA RÁPIDA Y SENCILLA. SUMINISTRADO CON SOPORTE Y PROTECTOR DEL POLVO', NULL, 8, 2, 'A', 32, '2013-04-22 16:27:32', NULL, NULL, 568, NULL),
('ESQUELETO DE LUJO SAM, EN SOPORTE DE 5 PATAS CON RUEDAS', 'A13', 25, 'ESTA REPRODUCCIÓN DE ESQUELETO PERMITE DEMOSTRAR LOS MOVIMIENTOS DE LA CRÁNEO POR LAS ARTICULACIONES DE LA CABEZA Y PUEDE AJUSTAR LAS POSTURAS NATURALES DEL CUERPO MEDIANTE LA COLUMNA VERTEBRAL FLEXIBLE. ESTE MODELO TIENE UN GRAN INTERÉS DESDE EL PUNTO DE VISTA MÉDICO Y ANATÓMICO, DEBIDO A LA COMBINACIÓN SINGULAR DE MÁS DE 600 ESTRUCTURAS DISTINTAS ENTRE LAS QUE DESTACAN UNA COLUMNA VERTEBRAL FLEXIBLE, INSERCIONES MUSCULARES, HUESOS NUMERADOS, LIGAMENTOS ARTICULARES FLEXIBLES Y UN PROLAPSO DE CARTÍLAGO INTERVERTEBRAL ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR. LIGAMENTOS ARTICULARES FLEXIBLES, COLUMNA VERTEBRAL FLEXIBLE, NERVIOS ESPINALES Y ARTERIAS VERTEBRALES, PROLAPSO DE CARTÍLAGO INTERVERTEBRAL ENTRE LA 3ª Y LA 4ª VÉRTEBRA LUMBAR, RELACIÓN EXCELENTE CALIDAD-PRECIO. FABRICADO CON MATERIAL IRROMPIBLE Y DE LARGA DURACIÓN, PESO DE LOS 200 HUESOS MUY APROXIMADO AL PESO REAL, TAMAÑO NATURAL, CRÁNEO MONTADO EN 3 PIEZAS, DIENTES COLOCADOS UNO A UNO, EXTREMIDADES DESMONTABLES DE FORMA RÁPIDA Y SENCILLA. SUMINISTRADO CON SOPORTE Y PROTECTOR DEL POLVO', NULL, 8, 2, 'A', 32, '2013-04-22 16:28:06', NULL, NULL, 569, NULL),
('ESQUELETO DE LUJO SAM, EN SOPORTE COLGANTE', 'A13/1', 25, 'MODELO QUE PERMITE LA DEMOSTRACIÓN DE LOS MOVIMIENTOS DEL CRÁNEO POR LAS ARTICULACIONES DE LA CABEZA Y PUEDE AJUSTAR LAS POSTURAS NATURALES DEL CUERPO MEDIANTE LA COLUMNA VERTEBRAL FLEXIBLE. ESTE MODELO TIENE UN GRAN INTERÉS DESDE EL PUNTO DE VISTA MÉDICO Y ANATÓMICO, DEBIDO A LA COMBINACIÓN SINGULAR DE MÁS DE 600 ESTRUCTURAS DISTINTAS ENTRE LAS QUE DESTACAN UNA COLUMNA VERTEBRAL FLEXIBLE, INSERCIONES MUSCULARES, HUESOS NUMERADOS, LIGAMENTOS ARTICULARES FLEXIBLES Y UN PROLAPSO DE CARTÍLAGO INTERVERTEBRAL ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR', NULL, 8, 2, 'A', 32, '2013-04-22 16:28:44', NULL, NULL, 570, NULL),
('ESQUELETO DE LUJO FRED, EN SOPORTE DE 5 PATAS CON RUEDAS', 'A15', 25, 'ESQUELETO FLEXIBLE. LA COLUMNA SE PUEDE DOBLAR IMITANDO CUALQUIER MOVIMIENTO HUMANO NATURAL. UNA VEZ DOBLADO, PERMANECERÁ EN ESA MISMA POSICIÓN PARA DEMOSTRAR LA POSTURA CORRECTA E INCORRECTA O VARIAS CONDICIONES PATOLÓGICAS. ADEMÁS, SE PUEDEN DEMOSTRAR TODOS LOS MOVIMIENTOS DEL CRÁNEO EN LAS ARTICULACIONES DEL CUELLO. SE MUESTRAN LAS SALIDAS DEL NERVIO VERTEBRAL Y LAS ARTERIAS VERTEBRALES COMO UNA HERNIA EN EL DISCO DORSO LATERAL ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR. VIENE CON UN SOPORTE CON RODILLOS Y GUARDAPOLVO', NULL, 8, 2, 'A', 32, '2013-04-22 16:29:19', NULL, NULL, 571, NULL),
('ESQUELETO DE LUJO FRED (1 MANO Y 1 PIE ELÁSTICOS), EN SOPORTE DE 5 PATAS CON RUEDAS', 'A15/2', 25, 'PRESENTAMOS A FRED, EL ESQUELETO FLEXIBLE. LA COLUMNA DE FRED SE PUEDE DOBLAR IMITANDO CUALQUIER MOVIMIENTO HUMANO NATURAL. UNA VEZ DOBLADO, PERMANECERÁ EN ESA MISMA POSICIÓN PARA DEMOSTRAR LA POSTURA CORRECTA E INCORRECTA O VARIAS CONDICIONES PATOLÓGICAS. ADEMÁS, SE PUEDEN DEMOSTRAR TODOS LOS MOVIMIENTOS DEL CRÁNEO EN LAS ARTICULACIONES DEL CUELLO. SE MUESTRAN LAS SALIDAS DEL NERVIO VERTEBRAL Y LAS ARTERIAS VERTEBRALES COMO UNA HERNIA EN EL DISCO DORSO LATERAL ENTRE LA 3ª Y 4ª VÉRTEBRA LUMBAR. ESTE MODELO VIENE CON UNA MANO Y UN PIE CON SUJETADORES ELÁSTICOS PARA PERMITIR UN ESTUDIO MÁS DETALLADO DE CADA UNO DE LOS HUESOS. ADEMÁS UNA PIERNA Y UN PIE ESTÁN MONTADOS DE FORMA ELÁSTICA. VIENE CON UN SOPORTE CON RODILLOS Y GUARDAPOLVO.', NULL, 8, 2, 'A', 32, '2013-04-22 16:29:55', NULL, NULL, 572, NULL),
('ESQUELETO FISIOLÓGICO, SOBRE SOPORTE ROTATORIO , 5 PATAS', 'A15/3', 25, 'ESTE SINGULAR ESQUELETO SE DESTACA POR UNA REALIZACIÓN CASI FIEL AL ORIGINAL DE LA MECÁNICA ARTICULAR. ESTO LE PERMITE A VD. MOSTRAR LA ROTACIÓN INTERNA Y EXTERNA DE LOS BRAZOS Y LAS PIERNAS ASÍ COMO EL MOVIMIENTO Y LA EXTENSIÓN DE LA ARTICULACIÓN DE LA RODILLA Y DE LA DEL CODO. LA COLUMNA VERTEBRAL FLEXIBLE PERMITE REALIZAR LOS MOVIMIENTOS NATURALES (INCLINACIÓN LATERAL, MOVIMIENTO Y EXTENSIÓN, ROTACIÓN). LOS HUESOS DE LAS MANOS ESTÁN MONTADOS SOBRE ALAMBRE PARA VISUALIZAR SU POSICIÓN NATURAL. EL MONTAJE FLEXIBLE DE LOS HUESOS DE LOS PIES PERMITE SU MOVILIDAD. LAS ESCÁPULAS GIRAN AL ELEVARSE LOS BRAZOS. INCLUSO SE PUEDE MOSTRAR LA ESCASA MOVILIDAD DE LAS ARTICULACIONES SACRO ILÍACA Y SACRO COCCÍGEA.', NULL, 8, 2, 'A', 32, '2013-04-22 16:30:34', NULL, NULL, 573, NULL),
('MINI ESQUELETO “SHORTY“, SOBRE ZÓCALO', 'A18', 25, 'ES UN MINI ESQUELETO DE PRIMERÍSIMA CATEGORÍA. MEDIANTE HARDWARE Y SOFTWARE DE ALTO RENDIMIENTO, SE DISMINUYERON TODOS LOS DETALLES A LA MITAD DE SU TAMAÑO NATURAL (80 CMS.), DE MANERA QUE LAS ESTRUCTURAS ANATÓMICAS ESTÉN REPRODUCIDAS ÓPTIMAMENTE. EL CRÁNEO ES DESMONTABLE EN 3 PIEZAS (CALOTA CRANEAL, BASE CRANEAL, MANDÍBULA). LOS BRAZOS Y LAS PIERNAS SON DE QUITA Y PON. LAS ARTICULACIONES DE LA CADERA ESTÁN MONTADAS DE FORMA QUE PERMITAN ENSEÑAR EL MOVIMIENTO DE ROTACIÓN NATURAL.', NULL, 8, 2, 'A', 32, '2013-04-22 16:31:10', NULL, NULL, 574, NULL),
('MINI ESQUELETO “SHORTY“, SOBRE SOPORTE COLGANTE', 'A18/1', 25, 'ES UN MINI ESQUELETO DE PRIMERÍSIMA CATEGORÍA. MEDIANTE HARDWARE Y SOFTWARE DE ALTO RENDIMIENTO, CONSEGUIMOS DISMINUIR TODOS LOS DETALLES A LA MITAD DE SU TAMAÑO NATURAL (80 CMS.), DE MANERA QUE LAS ESTRUCTURAS ANATÓMICAS ESTÁN REPRODUCIDAS ÓPTIMAMENTE. EL CRÁNEO ES DE QUITA Y PON ASÍ COMO DESMONTABLE EN 3 PIEZAS (CALOTA CRANEAL, BASE CRANEAL, MANDÍBULA). LOS BRAZOS Y LAS PIERNAS SON DE QUITA Y PON. LAS ARTICULACIONES DE LA CADERA ESTÁN MONTADAS DE FORMA QUE PERMITEN ENSEÑAR EL MOVIMIENTO DE ROTACIÓN NATURAL.', NULL, 8, 2, 'A', 32, '2013-04-22 16:31:58', NULL, NULL, 575, NULL),
('MINI ESQUELETO “SHORTY“ CON MÚSCULOS PINTADOS, SOBRE SOPORTE', 'A18/5', 25, 'MINI ESQUELETO CON REPRESENTACIÓN EN COLOR DE LOS ORÍGENES (EN COLOR ROJO) E INSERCIONES (EN COLOR AZUL) MUSCULARES EN LA MITAD IZQUIERDA. \r\nLOS MÚSCULOS ESTÁN NUMERADOS', NULL, 8, 2, 'A', 32, '2013-04-22 16:33:20', NULL, NULL, 576, NULL),
('MINI ESQUELETO “SHORTY” CON MÚSCULOS PINTADOS, SOBRE SOPORTE COLGANTE', 'A18/6', 25, 'MINI ESQUELETO CON SOPORTE COLGANTE. EL SOPORTE ES APROPIADO TANTO PARA SER COLOCADO EN EL SUELO COMO PARA SER MONTADO EN LA PARED', NULL, 8, 2, 'A', 32, '2013-04-22 16:34:01', NULL, NULL, 577, NULL),
('ESTERNÓN CON CARTÍLAGOS COSTALES', 'A69', 25, '', NULL, 8, 2, 'A', 32, '2013-04-22 16:34:33', NULL, NULL, 578, NULL),
('COSTILLAS. 12 A CADA LADO', 'A69/2', 25, '', NULL, 8, 2, 'A', 32, '2013-04-22 16:36:14', NULL, NULL, 579, NULL),
('MODELO DE OSTEOPOROSIS, VERSIÓN DE LUJO, 3 VERTEBRAS', 'A78', 25, 'COMPUESTO DE 3 DISCOS VERTEBRALES CON SECCIÓN MEDIAL CON DISCO INTERVERTEBRAL. PARA REALIZAR COMPARACIONES, LA SECCIÓN SUPERIOR MUESTRA LA ESTRUCTURA DE LOS HUESOS SANOS, LA SECCIÓN CENTRAL DE LOS HUESOS OSTEOPORÓTICOS Y A SECCIÓN INFERIOR DE UNA ESTRUCTURA ÓSEA OSTEOPORÓTICA AVANZADA CON PLACAS APLANADAS. EL PESO DE LA VERTEBRA OSTEOPORÓDICO ESTA NOTABLEMENTE REDUCIDO. LAS VÉRTEBRAS SON DESMONTABLES PARA UN ESTUDIO DETALLADO.', NULL, 8, 2, 'A', 32, '2013-04-22 16:36:56', NULL, NULL, 580, NULL),
('ESTRUCTURA DE LOS HUESOS AUMENTADA 80 VECES', 'A79', 25, 'ESTE MODELO EXTREMADAMENTE DETALLADO MUESTRA UNA SECCIÓN TRIDIMENSIONAL DE UN HUESO COMPACTO COMO ESTRUCTURA TÍPICA DE UN HUESO LARGO, AUMENTADO 80 VECES. SE PRESENTAN DISTINTAS FASES EN SECCIONES TRANSVERSALES Y LONGITUDINALES DE TODOS LOS PLANOS DEL HUESO, ASÍ COMO UNA SECCIÓN EN DOS FASES DE LA ESTRUCTURA INTERNA DE LA MÉDULA ÓSEA. LAS CARACTERÍSTICAS ESPECIALES DE UN HUESO COMPACTO ESTÁN CLARAMENTE EXPUESTAS PARA FACILITAR LA COMPRENSIÓN DE LA ESTRUCTURA Y DE LA FUNCIÓN DEL HUESO, CON LAS TÍPICAS PLACAS ÓSEAS QUE RECIBEN EL NOMBRE DE SISTEMA LAMINAR DE HAVERS. ESTE MODELO REPRESENTA DE FORMA ILUSTRATIVA LA CORRELACIÓN FUNCIONAL DE CADA UNO DE LOS COMPONENTES DEL HUESO, COMO EL TEJIDO ESPONJOSO, EL TEJIDO COMPACTO, EL PERIOSTIO, LA CORTEZA ÓSEA, LAS CÉLULAS ÓSEAS Y LOS CONDUCTOS DE VOLKMANN Y DE HAVERS.', NULL, 8, 2, 'A', 32, '2013-04-22 16:41:10', NULL, NULL, 581, NULL),
('MODELO DE OSTEOPOROSIS 2 PIEZAS', 'A95', 25, 'LA OSTEOPOROSIS PRESENTADA DE FORMA EXTRAORDINARIAMENTE DIDÁCTICA COMPARANDO VÉRTEBRAS DORSALES OSTEOPORÓTICAS Y SANAS. UN MODELO IDÓNEO PARA LA FORMACIÓN MÉDICA Y SESIONES CON EL PACIENTE. LAS VÉRTEBRAS DORSALES PRESENTADAS SON LAS 11 Y 12. EN EL LADO IZQUIERDO DE LA BASE SE PRESENTAN LAS PIEZAS CORRESPONDIENTES A LAS DOS VÉRTEBRAS OSTEOPORÓTICAS CON DISCO INTERVERTEBRAL COMPRIMIDO. EL CUERPO VERTEBRAL SUPERIOR ESTÁ SEPARADO EN EL PLANO MEDIO. LA MITAD VERTEBRAL FIJADA MAGNÉTICAMENTE PUEDE RETIRARSE CON FACILIDAD PARA PODER VER LAS SECCIONES TRANSVERSALES. ASIMISMO PERMITE RECONOCER PERFECTAMENTE EL HUNDIMIENTO DEL CUERPO VERTEBRAL O PÉRDIDA DE SUSTANCIA ÓSEA DURANTE LA OSTEOPOROSIS Y COMO CONSECUENCIA DE ELLA. ASIMISMO MUESTRA ALTERACIONES ÓSEAS DEGENERATIVAS EN FORMA DE OSTEOFITOS. EN EL LADO DERECHO DE LA BASE SE PRESENTAN, A MODO DE COMPARACIÓN, DOS PIEZAS IGUALES DE VÉRTEBRAS SANAS CON DISCO INTERVERTEBRAL. LA MITAD DEL CUERPO VERTEBRAL SUPERIOR TAMBIÉN ESTÁ FIJADA MAGNÉTICAMENTE Y PUEDE RETIRARSE. LAS VÉRTEBRAS REPRESENTADAS SE COMPLEMENTAN CON SENDOS ADHESIVO EN LA BASE QUE MUESTRAN DOS IMÁGENES TRIDIMENSIONALES MICRO-CT OBTENIDAS MEDIANTE BIOPSIA ÓSEA. LAS IMÁGENES MUESTRAN CLARAMENTE LA MICROARQUITECTURA DEL HUESO OSTEOPORÓTICO Y SU REDUCIDA DENSIDAD ÓSEA EN COMPARACIÓN CON LA DE UN HUESO SANO.', NULL, 8, 2, 'A', 32, '2013-04-22 16:44:11', NULL, NULL, 582, NULL),
('MODELO FUNCIONAL DEL ESQUELETO DE LA MANO CON LIGAMENTOS Y TÚNEL CARPIANO, 3 PARTES', 'M33', 25, 'ESTA MANO DE TRES PARTES MUESTRA LOS DETALLES ANATÓMICOS DE LOS LIGAMENTOS Y LOS TENDONES QUE SE ENCUENTRAN EN LA MANO, LA MUÑECA Y EL ANTEBRAZO INFERIOR. TAMBIÉN SE MUESTRA LA MEMBRANA INTERÓSEA ENTRE EL RADIO Y EL CÚBITO JUNTO CON LOS HUESOS DE LA MANO. EL RETINÁCULO FLEXOR ES EXTRAÍBLE Y ADEMÁS HAY UNA PARTE DESMONTABLE QUE PUEDE ENCAJARSE EN EL DORSO DEL MODELO. ESTA PARTE MUESTRA LAS ESTRUCTURAS CLÍNICAMENTE RELEVANTES DEL TÚNEL CARPIANO TALES COMO EL RETINÁCULO FLEXOR, EL NERVIO MEDIANO Y LOS TENDONES', NULL, 8, 2, 'A', 32, '2013-04-22 16:47:37', NULL, NULL, 583, NULL),
('MODELO FUNCIONAL DEL ESQUELETO DE LA MANO CON LIGAMENTOS Y MÚSCULOS, 4 PARTES', 'M33/1', 25, 'ESTE MODELO DE ALTA CALIDAD CONSTA DE 4 PARTES Y MUESTRA TODOS LOS HUESOS, MÚSCULOS, TENDONES, LIGAMENTOS, NERVIOS, ARTERIAS Y VENAS DE LA MANO Y EL ANTEBRAZO INFERIOR. EL LADO DORSAL MUESTRA LOS MÚSCULOS EXTENSORES ASÍ COMO PARTES DE LOS TENDONES DE LA MUÑECA EN SU PASO BAJO EL RETINÁCULO DE LOS EXTENSORES. EL LADO PALMAR DE LA MANO ESTÁ REPRESENTADO EN TRES CAPAS, LAS DOS PRIMERAS EXTRAÍBLES, PARA PERMITIR UN ESTUDIO DETALLADO DE LA CAPA ANATÓMICA MÁS PROFUNDA. ASIMISMO PERMITE EXPLORAR ESTRUCTURAS CLÍNICAMENTE RELEVANTES COMO EL NERVIO MEDIANO Y EL ARCO ARTERIAL SUPERFICIAL DE LA PALMA DE LA MANO. LA CAPA ANATÓMICA MÁS PROFUNDA PERMITE ESTUDIAR LOS MÚSCULOS INTRÍNSECOS Y EL ARCO ARTERIAL PROFUNDO PALMAR JUNTO CON OTROS DETALLES.', NULL, 8, 2, 'A', 32, '2013-04-22 16:49:03', NULL, NULL, 584, NULL),
('MODELO FUNCIONAL DEL ESQUELETO DEL PIE Y SUS LIGAMENTOS', 'M34', 25, 'ESTE DETALLADO MODELO MUESTRA VARIOS LIGAMENTOS Y TENDONES IMPORTANTES INCLUYENDO EL TENDÓN DE AQUILES Y EL TENDÓN PERONEO LARGO DEL TOBILLO. EL MODELO CONSTA DEL HUESO DEL PIE Y LAS PARTES INFERIORES DE LA TIBIA Y EL PERONÉ, INCLUYENDO LA MEMBRANA INTRAÓSEA QUE SE ENCUENTRA ENTRE AMBOS. MUESTRA TODOS LOS LIGAMENTOS Y TENDONES ANATÓMICAMENTE IMPORTANTES, TANTO LOS GRANDES COMO LOS PEQUEÑOS.', NULL, 8, 2, 'A', 32, '2013-04-22 16:51:12', NULL, NULL, 585, NULL),
('MODELO FUNCIONAL DEL ESQUELETO DEL PIE Y SUS LIGAMENTOS Y SUS MÚSCULOS', 'M34/1', 25, 'ESTE MODELO ANATÓMICAMENTE DETALLADO DEL PIE Y DE LA PARTE INFERIOR DE LA PIERNA PUEDE DESMONTARSE EN 6 PARTES EXTRAÍBLES PARA REALIZAR UN ESTUDIO DETALLADO DE LA ZONA. EL MODELO NO INCLUYE SOLAMENTE LOS HUESOS, SINO QUE TAMBIÉN INCORPORA LOS MÚSCULOS, TENDONES, LIGAMENTOS, NERVIOS, ARTERIAS Y VENAS. LA VISTA FRONTAL MUESTRA LOS MÚSCULOS EXTENSORES DE LA PARTE INFERIOR DE LA PIERNA. PUEDE SEGUIRSE EL DISCURRIR DE LOS TENDONES BAJO EL LIGAMENTO CRURAL TRANSVERSAL Y CRURAL CRUCIAL HASTA SUS PUNTOS DE INSERCIÓN. ADEMÁS, TODAS LAS FUNDAS DE LOS TENDONES SON VISIBLES. LA PARTE DORSAL DEL MODELO PERMITE EXTRAER EL MÚSCULO GEMELO PARA REVELAR LOS ELEMENTOS ANATÓMICOS QUE SE HAYAN DEBAJO. LA PLANTA DEL PIE ESTÁ REPRESENTADA EN TRES CAPAS, LA PRIMERA DE LAS CUALES MUESTRA EL FLEXOR CORTO DE LOS DEDOS. ESTE MÚSCULO PUEDE EXTRAERSE, MOSTRANDO EL CUADRADO PLANTAR, EL TENDÓN DEL FLEXOR LARGO DE LOS DEDOS Y EL MÚSCULO FLEXOR DEL DEDO GORDO DEL PIE. ESTA SEGUNDA CAPA ES A SU VEZ EXTRAÍBLE PARA MOSTRAR DETALLES ANATÓMICOS SITUADOS TODAVÍA A MAYOR PROFUNDIDAD.', NULL, 8, 2, 'A', 32, '2013-04-22 16:51:50', NULL, NULL, 586, NULL),
('MODELO FUNCIONAL DEL BRAZO, CON MÚSCULOS, 6 PARTES', 'M11', 26, 'EN ESTE NUEVO MODELO DE TAMAÑO NATURAL PUEDEN DESMONTARSE LOS SIGUIENTES MÚSCULOS: M. DELTOIDES, M. BÍCEPS BRAQUIAL, M. TRÍCEPS BRAQUIAL, M. PALMAR MENOR Y M. PALMAR MAYOR, M. SUPINADOR LARGO CON M. RADIAL EXTERNO. MONTADO SOBRE SOPORTE.', NULL, 8, 2, 'A', 32, '2013-04-22 16:52:36', NULL, NULL, 587, NULL),
('MODELO DE LA ESTRUCTURA DE LA MANO, DESMONTABLE EN 3 PIEZAS', 'M18', 26, 'ESTE MODELO DE TAMAÑO NATURAL MUESTRA LAS ESTRUCTURAS SUPERFICIALES DEL DORSO DE LA MANO ADEMÁS DE LAS ESTRUCTURAS INTERNAS, INCLUYENDO HUESOS, MÚSCULOS, TENDONES, LIGAMENTOS, ARTERIAS (ARCOS PALMARES SUPERFICIALES Y PROFUNDOS) Y NERVIOS. LA APONEUROSIS PALMAR Y EL PLANO DE LOS TENDONES DEL FLEXOR SUPERFICIAL SON DESMONTABLES. LAS PIEZAS VIENEN ENUMERADAS.', NULL, 8, 2, 'A', 32, '2013-04-22 16:53:09', NULL, NULL, 588, NULL),
('MODELO DE LA ESTRUCTURA DE UN DEDO', 'M19', 26, 'ESTE MODELO DE TAMAÑO NATURAL MUESTRA LOS HUESOS, MÚSCULOS Y TENDONES DEL DEDO MEDIO HUMANO. SE ENVÍA CON UN SOPORTE', NULL, 8, 2, 'A', 32, '2013-04-22 17:02:08', NULL, NULL, 589, NULL),
('PIE NORMAL', 'M30', 26, 'TANTO LAS ESTRUCTURAS SUPERFICIALES COMO LOS HUESOS INTERNOS, MÚSCULOS, LIGAMENTOS Y NERVIOS ESTÁN ENUMERADOS SEGÚN EL TEXTO EXPLICATIVO CORRESPONDIENTE.', NULL, 8, 2, 'A', 32, '2013-04-22 17:02:45', NULL, NULL, 590, NULL),
('PIE PLANO (PES PLANUS)', 'M31', 26, 'TANTO LAS ESTRUCTURAS SUPERFICIALES COMO LOS HUESOS INTERNOS, MÚSCULOS, LIGAMENTOS Y NERVIOS ESTÁN ENUMERADOS SEGÚN EL TEXTO EXPLICATIVO CORRESPONDIENTE', NULL, 8, 2, 'A', 32, '2013-04-22 17:03:45', NULL, NULL, 591, NULL),
('PIE ARQUEADO (PES CAVUS)', 'M32', 26, 'TANTO LAS ESTRUCTURAS SUPERFICIALES COMO LOS HUESOS INTERNOS, MÚSCULOS, LIGAMENTOS Y NERVIOS ESTÁN ENUMERADOS SEGÚN EL TEXTO EXPLICATIVO CORRESPONDIENTE', NULL, 8, 2, 'A', 32, '2013-04-22 17:04:17', NULL, NULL, 592, NULL),
('ESQUELETO DE LA PELVIS, MASCULINO', 'A60', 27, 'CONSTA DE LOS HUESOS DE LA CADERA, EL SACRO CON COXIS Y 2 DISCOS LUMBARES', NULL, 8, 2, 'A', 32, '2013-04-22 17:17:10', NULL, NULL, 593, NULL),
('ESQUELETO DE LA PELVIS, FEMENINO', 'A61', 27, 'CONSTA DE LOS HUESOS DE LA CADERA, EL SACRO CON COXIS Y 2 DISCOS LUMBARES, CON SÍNFISIS MÓVIL', NULL, 8, 2, 'A', 32, '2013-04-22 17:18:51', NULL, NULL, 594, NULL),
('ESQUELETO DE LA PELVIS, FEMENINO, CON CABEZAS DE FÉMUR MÓVILES', 'A62', 27, 'CONSTA DE LOS HUESOS DE LA CADERA, EL SACRO CON COXIS Y 2 DISCOS LUMBARES, CON SNFISIS MVIL', NULL, 8, 2, 'A', 32, '2013-04-22 17:19:32', 32, '2013-04-22 17:20:36', 595, NULL),
('PELVIS FEMENINA, 2 PIEZAS', 'H10', 27, 'ESTE MODELO EN FORMA DE CORTE MEDIANO PRESENTA TODAS LAS ESTRUCTURAS IMPORTANTES DE LA PELVIS. UNA MITAD DE LOS ÓRGANOS GENITALES CON LA VEJIGA Y EL RECTO ES DESMONTABLE PARA LOS ESTUDIOS EN DETALLE. SOBRE TABLA PARA MONTAR EN LA PARED.', NULL, 8, 2, 'A', 32, '2013-04-22 17:21:05', NULL, NULL, 596, NULL),
('MODELO DE LA PELVIS MASCULINA', 'H11', 27, '<p>ESTA SECCI&Oacute;N MEDIA DE LA PELVIS MASCULINA REPRESENTA TODAS LAS ESTRUCTURAS CON UNA EXTRAORDINARIA FIDELIDAD EN LOS DETALLES. ASIMISMO, PARA VER LAS ESTRUCTURAS INTERNAS, UNA DE LAS DOS MITADES DE LOS &Oacute;RGANOS GENITALES ES DESMONTABLE</p>', NULL, 8, 2, 'A', 32, '2013-04-22 17:22:57', 32, '2013-09-09 12:15:50', 597, '20130909_21a62f.pdf'),
('SECCIÓN TRASVERSAL DE LA PELVIS MASCULINA, TAMAÑO NATURAL', 'H12', 27, 'ESTA SECCIÓN TRASVERSAL DE LOS ÓRGANOS GENITALES MASCULINOS PRESENTA TODAS LAS ESTRUCTURAS EN DETALLE.', NULL, 8, 2, 'A', 32, '2013-04-22 17:23:29', NULL, NULL, 598, NULL),
('MODELO DE HERNIA INGUINAL', 'H13', 27, 'ESTE MODELO MUESTRA EN TAMAÑO NATURAL LAS ESTRUCTURAS ANATÓMICAS DE LA REGIÓN INGUINAL DE UN VARÓN CON UNA HERNIA INGUINAL INDIRECTA O EXTERNA, QUE AQUÍ APARECE ABIERTA. DOS REPRESENTACIONES ESQUEMÁTICAS PERMITEN LA COMPARACIÓN ENTRE UNA HERNIA INGUINAL DIRECTA (INTERNA) Y UNA HERNIA INGUINAL INDIRECTA (EXTERNA). ESTE MODELO FACILITA LAS EXPLICACIONES QUE RECIBE EL PACIENTE QUE VA A SER SOMETIDO A UNA INTERVENCIÓN QUIRÚRGICA. SOBRE UN ZÓCALO.', NULL, 8, 2, 'A', 32, '2013-04-22 17:24:03', NULL, NULL, 599, NULL),
('MODELO DE LA PELVIS FEMENINA, 3 PARTES', 'H20/1', 27, 'MODELO EN TRES PIEZAS REPRESENTANDO UN MOLDE ORIGINAL DE LA ESTRUCTURA ÓSEA DE UNA PELVIS FEMENINA, MOSTRANDO TODOS LOS DETALLES DE LAS ESTRUCTURAS ANATÓMICAS: DOS HUESOS ILÍACOS, LA SÍNFISIS PÚBICA, EL SACRO Y EL COXIS, LA QUINTA VÉRTEBRA LUMBAR CON EL DISCO INTERVERTEBRAL. UNA SECCIÓN MEDIA SAGITAL A TRAVÉS DE LA QUINTA VÉRTEBRA LUMBAR, SACRO Y COXIS, PERMITE DESMONTAR LAS DOS MITADES DE LA PELVIS, MOSTRANDO UNA PARTE DE LA CAUDA EQUINA EN EL CANAL VERTEBRAL. LA MITAD IZQUIERDA DE LA QUINTA VÉRTEBRA LUMBAR ES DESMONTABLE', NULL, 8, 2, 'A', 32, '2013-04-22 17:24:40', NULL, NULL, 600, NULL),
('MODELO DE LA PELVIS FEMENINA CON LIGAMENTOS, VASOS, NERVIOS, PISO PÉLVICO Y ÓRGANOS, 6 PARTES', 'H20/4', 27, '<p>ESTE MODELO ORIGINAL DE UNA PELVIS FEMENINA REPRESENTA INFORMACI&Oacute;N DETALLADA ACERCA DE LA TOPOGRAF&Iacute;A DE LOS HUESOS, LIGAMENTOS, VASOS, NERVIOS, M&Uacute;SCULOS DEL PISO P&Eacute;LVICO Y &Oacute;RGANOS P&Eacute;LVICOS FEMENINOS. LA TOTALIDAD DEL PISO P&Eacute;LVICO EST&Aacute; REPRESENTADO CON UNA SECCI&Oacute;N DEL ESF&Iacute;NTER ANAL EXTERNO CON SECCI&Oacute;N MEDIA SAGITAL PARCIALMENTE EXTRA&Iacute;BLE, ESF&Iacute;NTER URETRAL EXTERNO Y LOS M&Uacute;SCULOS TRANSVERSOS PROFUNDO Y SUPERFICIAL DEL PERIN&Eacute;, Y BULBOESPONJOSO. EL RECTO, EL &Uacute;TERO CON LAS TROMPAS DE FALOPIO, LOS OVARIOS Y LA VAGINA TAMBI&Eacute;N SON DESPRENDIBLES Y PUEDEN DESMONTARSE EN DOS MITADES POR SU SECCI&Oacute;N MEDIA SAGITAL. LA MITAD P&Eacute;LVICA DERECHA MUESTRA LAS DIVISIONES Y LA ANATOM&Iacute;A TOPOGR&Aacute;FICA DE LA ARTERIA IL&Iacute;ACA COM&Uacute;N, LAS ARTERIAS EXTERNA E INTERNA Y TAMBI&Eacute;N DE LA VENA IL&Iacute;ACA COM&Uacute;N Y LA VENA IL&Iacute;ACA EXTERNA. TAMBI&Eacute;N MUESTRA EL PLEXO SACRO DERECHO, EL NERVIO CI&Aacute;TICO DERECHO Y EL NERVIO PUDENDO. HUESOS Y LIGAMENTOS MOSTRADOS: DOS HUESOS IL&Iacute;ACOS, LA S&Iacute;NFISIS P&Uacute;BICA, EL SACRO Y EL COXIS, LA QUINTA V&Eacute;RTEBRA LUMBAR CON EL DISCO INTERVERTEBRAL. UNA SECCI&Oacute;N MEDIA SAGITAL A TRAV&Eacute;S DE LA QUINTA V&Eacute;RTEBRA LUMBAR, SACRO Y COXIS, PERMITE DESMONTAR LAS DOS MITADES DE LA PELVIS, MOSTRANDO UNA PARTE DE LA CAUDA EQUINA EN EL CANAL VERTEBRAL. LA MITAD IZQUIERDA DE LA QUINTA V&Eacute;RTEBRA LUMBAR ES EXTRA&Iacute;BLE. LA MITAD DERECHA DEL MODELO MUESTRA LOS SIGUIENTES LIGAMENTOS P&Eacute;LVICOS: LIGAMENTO INGUINAL, LIGAMENTO SACROTUBEROSO, LIGAMENTO SACROESPINOSO, LIGAMENTOS SACROIL&Iacute;ACOS ANTERIORES, LIGAMENTO ILIOLUMBAR, LIGAMENTO LONGITUDINAL ANTERIOR, LIGAMENTO SACROIL&Iacute;ACO INTER&Oacute;SEO, LIGAMENTO SACROIL&Iacute;ACO POSTERIOR Y MEMBRANA OBTURADORA.</p>', NULL, 8, 2, 'A', 32, '2013-04-22 17:25:23', 32, '2013-09-09 12:26:12', 601, '20130909_f174ae.pdf'),
('MODELO DE LA PRÓSTATA', 'K41', 27, 'UNA SECCIÓN A TRAVÉS DE LOS ÓRGANOS GENITALES MASCULINOS EN TAMAÑO LA MITAD DEL NATURAL, PRESENTA UNA PRÓSTATA SANA CON LA VEJIGA, LA URETRA, LOS TESTÍCULOS, LA SÍNFISIS Y EL RECTO. EL ESTRECHAMIENTO DE LA URETRA DEBIDO AL CAMBIO DE LA PRÓSTATA SE PUEDE EXPLICAR MEDIANTE LAS PRESENTACIONES DE CORTES SECCIONALES AL TRAVÉS. TODAS LAS ESTRUCTURAS ANATÓMICAS ESTÁN PINTADAS EN DETALLE. EN BASE.', NULL, 8, 2, 'A', 32, '2013-04-22 17:25:59', NULL, NULL, 602, NULL),
('ESQUELETO DE LA PELVIS FEMENINA CON ÓRGANOS GENITALES, EN 3-PIEZAS', 'L31', 27, 'ESTE MODELO ES ESPECIALMENTE ADECUADO PARA ESTUDIAR LA POSICIÓN DE LOS ÓRGANOS GENITALES FEMENINOS EN LA PELVIS. CONSISTE DE PELVIS FEMENINA CON SÍNFISIS DESMONTABLE, EL HUESO DE LA CADERA, EL SACRO, EL COXIS, 2 VÉRTEBRAS LUMBARES Y UN INSERTO GENITAL FEMENINO CON EL RECTO. EL ÚTERO Y LA VEJIGA SON DESMONTABLES. SE SUMINISTRA SOBRE UN TABLERO.', NULL, 8, 2, 'A', 32, '2013-04-22 17:26:51', NULL, NULL, 603, NULL),
('PELVIS MASCULINA, 2 PIEZAS', 'VG351', 27, 'ADEMÁS DE TODAS LAS ESTRUCTURAS IMPORTANTES DE LA PELVIS, MUESTRA ESTE MODELO DE LA SECCIÓN MEDIANA DE LA PELVIS LOS MÚSCULOS ABDOMINALES Y PÉLVICOS EN GRAN DETALLE. UNA MITAD DE LOS ÓRGANOS GENITALES CON VEJIGA Y EL RECTO ES DESMONTABLE. MONTADO SOBRE UNA BASE EN POSICIÓN VERTICAL.', NULL, 8, 2, 'A', 32, '2013-04-22 17:27:27', NULL, NULL, 604, NULL),
('PELVIS FEMENINA, 2 PIEZAS', 'VG366', 27, 'ADEMÁS DE TODAS LAS ESTRUCTURAS IMPORTANTES DE LA PELVIS, MUESTRA ESTE MODELO DE LA SECCIÓN MEDIANA DE LA PELVIS LOS MÚSCULOS ABDOMINALES Y PÉLVICOS EN GRAN DETALLE. UNA MITAD DE LOS ÓRGANOS GENITALES CON VEJIGA Y EL RECTO ES DESMONTABLE. MONTADO SOBRE UNA BASE EN POSICIÓN VERTICAL.', NULL, 8, 2, 'A', 32, '2013-04-22 17:28:19', NULL, NULL, 605, NULL),
('PELVIS FEMENINA CON LIGAMENTOS', 'W19012', 27, 'ESTE MODELO DE ILUSTRACIÓN DE LA PELVIS FEMENINA MUESTRA CON SUS LIGAMENTOS SINTÉTICOS MUY REALES COMO SE SOSTIENE EL CINTURÓN PELVIANO', NULL, 8, 2, 'A', 32, '2013-04-22 17:28:52', NULL, NULL, 606, NULL),
('PELVIS FEMENINA CON LIGAMENTOS, NERVIOS Y MÚSCULOS', 'W19020', 27, 'UNA PELVIS ÓSEA FEMENINA DE TAMAÑO NATURAL QUE MUESTRA LOS LIGAMENTOS Y LOS NERVIOS PRINCIPALES, CON UN SUELO DE LA PELVIS EN DOS PARTES DESMONTABLES', NULL, 8, 2, 'A', 32, '2013-04-22 17:30:08', NULL, NULL, 607, NULL),
('PELVIS Y SUELO DE LA PELVIS FEMENINA, 5 PIEZAS', 'W19025', 27, 'UNA PELVIS CON MATERIAL SINTÉTICO PARECIDO AL HUESO, CON SUELO DE LA PELVIS MUY DETALLADO Y DESMONTABLE REALIZADO CON MATERIAL FLEXIBLE COLOREADO. EL MODELO CONTIENE LAS PARTES GENITALES Y LA MUSCULATURA ASOCIADA.', NULL, 8, 2, 'A', 32, '2013-04-22 17:30:43', NULL, NULL, 608, NULL),
('SERIE DE MODELOS DENTALES , 5 MODELOS', 'D10', 28, 'ESTA SERIE SE COMPONE DE 5 MODELOS DE DIENTES, MONTADOS SINGULARMENTE SOBRE SOPORTE DESMONTABLE. INCISIVO INFERIOR DE 2 PIEZAS CON CORTE LONGITUDINAL (D10/1), CANINO INFERIOR DE 2 PIEZAS CON CORTE LONGITUDINAL (D10/2), PRIMER MOLAR SENCILLO INFERIOR (D10/3), MOLAR CON RAÍZ DOBLE DE 2 PIEZAS CON CORTE LONGITUDINAL MOSTRANDO UN ATAQUE DE CARIES (D10/4), MOLAR SUPERIOR DE RAÍZ TRIPLE EN 3 PIEZAS CON CORTE LONGITUDINAL Y UN INSERTO DE CARIES (D10/5).', NULL, 8, 2, 'A', 32, '2013-04-22 17:32:57', NULL, NULL, 609, NULL),
('INCISIVO INFERIOR, 2 PIEZAS', 'D10/1', 28, 'MODELO DE INCISIVO INFERIOR DESMONTABLE EN 2 PIEZAS', NULL, 8, 2, 'A', 32, '2013-04-22 17:33:33', NULL, NULL, 610, NULL),
('CANINO INFERIOR, 2 PIEZAS', 'D10/2', 28, 'MODELO DE CANINO INFERIOR DESMONTABLE EN 2 PIEZAS', NULL, 8, 2, 'A', 32, '2013-04-22 17:34:15', NULL, NULL, 611, NULL),
('PRIMER MOLAR INFERIOR DE RAÍZ SENCILLA', 'D10/3', 28, 'MODELO DE MOLAR INFERIOR DE RAÍZ SENCILLA', NULL, 8, 2, 'A', 32, '2013-04-22 17:34:55', NULL, NULL, 612, NULL),
('MOLAR INFERIOR CON 2 RAÍCES', 'D10/4', 28, 'MODELO DE MOLAR INFERIOR CON 2 RAÍCES', NULL, 8, 2, 'A', 32, '2013-04-22 17:35:32', NULL, NULL, 613, NULL),
('MOLAR SUPERIOR CON 3 RAÍCES', 'D10/5', 28, 'MODELO DE MOLAR SUPERIOR CON 3 RAÍCES', NULL, 8, 2, 'A', 32, '2013-04-22 17:36:21', NULL, NULL, 614, NULL),
('MOLAR SUPERIOR, 6 PIEZAS', 'D15', 28, 'ESTE MODELO MUESTRA UN MOLAR SUPERIOR CON TRES RAÍCES EXTREMAMENTE AUMENTADO CUAL SE DESMONTAR EN 6 PIEZAS. INCLUYE UN CORTE LONGITUDINAL A TRAVÉS DE LA CORONA, LAS DOS RAÍCES Y LA CAVIDAD PULPAR. CONTIENE UNA PULPA DESMONTABLE Y TRES OPCIONES INTERCAMBIABLES CON DIFERENTES ETAPAS DE CARIES AVANZADA. SOBRE SOPORTE.', NULL, 8, 2, 'A', 32, '2013-04-22 17:36:58', NULL, NULL, 615, NULL),
('MODELO DE CUIDADO DENTAL, 3 VECES SU TAMAÑO NATURAL', 'D16', 28, 'IDEAL PARA LA DEMOSTRACIÓN DE TÉCNICAS PARA EL CUIDADO DE LOS DIENTES ANTE UNA CLASE COMPLETA. SE SUMINISTRA CON EL MODELO UN CEPILLO DE DIENTES GIGANTE. LAS DOS MANDÍBULAS SON MONTADAS FLEXIBLEMENTE Y SON APROPIADAS PARA LA DEMOSTRACIÓN DE LA DENTADURA SUPERIOR E INFERIOR.', NULL, 8, 2, 'A', 32, '2013-04-22 17:37:31', NULL, NULL, 616, NULL),
('DESARROLLO DE LA DENTADURA', 'D20', 28, 'VACIADO EN MOLDE DE UNA MUESTRA NATURAL. ESTAS 4 MITADES DE MANDÍBULA SUPERIORES E INFERIORES MUESTRAN 4 DIFERENTES ETAPAS DE DESARROLLO: RECIÉN NACIDO, NIÑO DE 5 AÑOS, NIÑO DE 9 AÑOS Y JOVEN ADULTO', NULL, 8, 2, 'A', 32, '2013-04-22 17:38:04', NULL, NULL, 617, NULL),
('MITAD DE LA MANDÍBULA INFERIOR, 3 VECES SU TAMAÑO NATURAL, 6 PIEZAS', 'D25', 28, 'ESTE MODELO REPRESENTA LA MITAD DE LA MANDÍBULA IZQUIERDA DE UNA PERSONA JOVEN. UNA SECCIÓN DEL HUESO ES DESMONTABLE PARA EXPONER LAS RAÍCES DE LOS DIENTES, ESPONGIOSA, VASOS Y NERVIOS. LOS CANINOS Y EL PRIMER MOLAR SON CORTADOS LONGITUDINALMENTE. SOBRE SOPORTE.', NULL, 8, 2, 'A', 32, '2013-04-22 17:38:34', NULL, NULL, 618, NULL),
('AFECCIÓN DENTAL, A 2 AUMENTOS, DE 21 PIEZAS', 'D26', 28, 'EL MODELO SE BASA EN UNA REPRODUCCIÓN FIEL, A 2 AUMENTOS, DE UNA MANDÍBULA DE UN ADULTO CON 16 DIENTES SEPARABLES. \r\nUNA DE LAS MITADES DEL MODELO REPRESENTA 8 DIENTES SANOS Y ENCÍA SANA. LA OTRA MITAD DEL MODELO REPRESENTA LAS SIGUIENTES AFECCIONES DENTALES: PLACA DENTAL, SARRO DENTAL, PARODONTITIS, INFLAMACIÓN DE LA RAÍZ DENTAL, CARIES DE FISURAS, CARIES DE SUPERFICIES PROXIMALES Y CARIES DE SUPERFICIES LISAS. LA PARTE ÓSEA ANTERIOR ES PARCIALMENTE DESMONTABLE PARA HACER VISIBLES LAS RAÍCES DENTALES, VASOS Y NERVIOS. DOS DE LAS MUELAS ESTÁN DIVIDIDAS LONGITUDINALMENTE PARA HACER VISIBLE EL INTERIOR DEL DIENTE. \r\nSE SUMINISTRA SOBRE ZÓCALO.', NULL, 8, 2, 'A', 32, '2013-04-22 17:39:12', NULL, NULL, 619, NULL),
('DENTADURA DE ADULTO', 'VE281', 28, '<p>LAS RA&Iacute;CES DE LOS DIENTES, ESPONGIOSA, VASOS Y NERVIOS SON EXPUESTOS. LA MAND&Iacute;BULA INFERIOR ES M&Oacute;VIL. SOBRE SOPORTE</p>', NULL, 8, 2, 'A', 32, '2013-04-22 17:39:49', 32, '2013-09-09 12:55:13', 620, '20130909_7d51c0.pdf'),
('MODELO DE LA DENTADURA DE LECHE', 'VE282', 28, '<p>LA MAND&Iacute;BULA SUPERIOR E INFERIOR EST&Aacute;N ABIERTAS PARA MOSTRAR LA DISPOSICI&Oacute;N DE LOS DIENTES RESTANTES. SOBRE SOPORTE.</p>', NULL, 8, 2, 'A', 32, '2013-04-22 17:40:35', 32, '2013-09-09 13:03:55', 621, '20130909_eae1f9.pdf'),
('MITAD DE LA MANDÍBULA INFERIOR, 3 VECES SU TAMAÑO NATURAL, 11 PIEZAS', 'VE287', 28, '<p>LA SECCI&Oacute;N FRONTAL &Oacute;SEA Y TODOS LOS DIENTES SON DESMONTABLES. ADEM&Aacute;S SE MUESTRA DETALLADAMENTE LOS NERVIOS, VASOS SANGU&Iacute;NEOS, LAS GL&Aacute;NDULAS SUBLINGUALES Y SUBMANDIBULARES.</p>', NULL, 8, 2, 'A', 32, '2013-04-22 17:41:11', 32, '2013-09-09 13:12:07', 622, '20130909_d6d7c0.pdf'),
('MODELO DE LA MITAD DE LA MANDÍBULA INFERIOR, CON 8 DIENTES CARIADOS, 19 PIEZAS', 'VE290', 28, '<p>ESTOS DIENTES ENFERMOS MUESTRAN VARIAS ETAPAS DE CARIES DESDE UN EJEMPLO F&Aacute;CIL DE TRATAR HASTA UNA DESTRUCCI&Oacute;N AVANZADA DE UN MOLAR CON RA&Iacute;Z EXPUESTA. CON ESTE MODELO PUEDE MOSTRAR DE FORMA MUY IMPRESIONANTE LA IMPORTANCIA DE USAR T&Eacute;CNICAS CORRECTAS PARA EL CUIDADO DE LOS DIENTES.</p>', NULL, 8, 2, 'A', 32, '2013-04-22 17:41:44', 32, '2013-09-09 13:21:44', 623, '20130909_15d577.pdf'),
('MOLAR SUPERIOR DE TRES RAÍCES, 2 PIEZAS', 'VE298', 28, '<p>CORTE LONGITUDINAL DE LA CORONA DEL DIENTE Y RA&Iacute;Z PARA MOSTRAR LA PULPA CON PRINCIPIOS DE CARIES. SOBRE SOPORTE, DESMONTABLE.</p>', NULL, 8, 2, 'A', 32, '2013-04-22 17:42:23', 32, '2013-09-09 13:24:11', 624, '20130909_9bf356.pdf'),
('MOLAR SUPERIOR DE DOS RAÍCES, 2 PIEZAS', 'VE299', 28, '<p>LA MITAD DE LA CORONA DEL DIENTE ES DESMONTABLE PARA MOSTRAR LA PULPA ADEM&Aacute;S SE PUEDE VER PRINCIPIOS DE CARIES. SOBRE BASE, DESMONTABLE.</p>', NULL, 8, 2, 'A', 32, '2013-04-22 17:43:03', 32, '2013-09-09 13:29:42', 625, '20130909_34d8b1.pdf'),
('INCISIVO SUPERIOR, 2 PIEZAS', 'VE300', 28, '<p>CON CORTE LONGITUDINAL PARA EXPONER LA PULPA COMPLETA. SOBRE SOPORTE</p>', NULL, 8, 2, 'A', 32, '2013-04-22 17:43:49', 32, '2013-09-09 13:34:54', 626, '20130909_33b4bf.pdf'),
('LENGUA. 3B MICROANATOMY', 'D17', 29, '<p>ESTE MODELO MUESTRA LOS DIFERENTES AUMENTOS DE ZONAS ESPECIALES DE LA LENGUA EN UN S&Oacute;LO MODELO. INCLUYE LA REPRESENTACI&Oacute;N MACROSC&Oacute;PICA DE LA LENGUA A TAMA&Ntilde;O NATURAL (VISTA DORSAL), LA REPRESENTACI&Oacute;N MICROSC&Oacute;PICA DE TODAS LAS PAPILAS GUSTATIVAS (AUMENTADAS 10-20 VECES) Y UN BULBO GUSTATORIO (AUMENTADO APROX. 450 VECES). TODAS LAS VISTAS EST&Aacute;N MONTADAS EN UNA BASE EN LA QUE SE MUESTRA UNA VISTA GENERAL DE LA INERVACI&Oacute;N SENSORIAL Y SENSIBLE DE LA LENGUA. UN MODELO &Uacute;NICO PARA EL ESTUDIO EN PROFUNDIDAD DE LA LENGUA</p>', NULL, 8, 2, 'A', 32, '2013-04-22 17:47:13', 32, '2013-09-09 14:08:36', 627, '20130909_e87285.pdf'),
('OÍDO, 3 VECES SU TAMAÑO NATURAL, 4 PIEZAS', 'E10', 29, '<p>LA REPRESENTACI&Oacute;N DEL O&Iacute;DO EXTERNO, MEDIO E INTERNO. INCLUYE T&Iacute;MPANO DESMONTABLE CON MARTILLO Y YUNQUE, ADEM&Aacute;S DE LABERINTOS CON CANALES SEMICIRCULARES, NERVIO COCLEAR Y NERVIO VEST&Iacute;BULO COCLEAR. SOBRE SOPORTE.</p>', NULL, 8, 2, 'A', 32, '2013-04-22 17:47:45', 32, '2013-09-09 14:13:07', 628, '20130909_6e03d8.pdf'),
('MODELO DEL OÍDO 3 VECES SU TAMAÑO NATURAL, 6 PIEZAS', 'E11', 29, 'LA REPRESENTACIÓN DEL OÍDO EXTERNO, MEDIO E INTERNO. INCLUYE TÍMPANO DESMONTABLE CON MARTILLO Y YUNQUE, ADEMÁS DE LABERINTOS CON CANALES SEMICIRCULARES, NERVIO COCLEAR Y NERVIO VESTÍBULO COCLEAR. ADICIONALMENTE INCLUYE SECCIONES ÓSEAS DESMONTABLES PARA CERRAR EL OÍDO MEDIO E INTERNO.', NULL, 8, 2, 'A', 32, '2013-04-22 17:48:19', NULL, NULL, 629, NULL),
('OÍDO, 3 VECES SU TAMAÑO NATURAL, 6 PIEZAS', 'E11', 29, 'LA REPRESENTACIÓN DEL OÍDO EXTERNO, MEDIO E INTERNO. INCLUYE TÍMPANO DESMONTABLE CON MARTILLO Y YUNQUE, ADEMÁS DE LABERINTOS CON CANALES SEMICIRCULARES, NERVIO COCLEAR Y NERVIO VESTÍBULO COCLEAR. ADICIONALMENTE INCLUYE SECCIONES ÓSEAS DESMONTABLES PARA CERRAR EL OÍDO MEDIO E INTERNO. SOBRE SOPORTE.', NULL, 8, 2, 'I', 32, '2013-04-22 17:49:00', 1, '2013-09-09 16:53:39', 630, NULL),
('MODELO DEL OÍDO PARA EL ESCRITORIO, 1,5 VECES SU TAMAÑO NATURAL', 'E12', 29, 'REPRESENTACIÓN DEL OÍDO EXTERNO, MEDIO E INTERNO. SOBRE BASE', NULL, 8, 2, 'A', 32, '2013-04-22 17:49:34', NULL, NULL, 631, NULL),
('OSÍCULOS AUDITIVOS DE TAMAÑO NATURAL', 'E13', 29, 'LOS OSÍCULOS AUDITIVOS HUMANOS ESTÁN INCRUSTADOS INDIVIDUALMENTE EN UN PLÁSTICO TRANSPARENTE.', NULL, 8, 2, 'A', 32, '2013-04-22 17:50:14', NULL, NULL, 632, NULL),
('NARIZ CON CAVIDADES PARANASALES, DIVIDIDA EN 5 PARTES', 'E20', 29, 'EL MODELO PERMITE VISUALIZAR LA ESTRUCTURA DE LA NARIZ EN UNA AMPLIACIÓN DE 1,5, CON LAS CAVIDADES PARANASALES EN EL INTERIOR DE UNA MITAD DERECHA SUPERIOR DEL ROSTRO. POR MEDIO DE COLORES (TAMBIÉN A TRAVÉS DE LA PIEL, REMOVIBLE Y TRANSPARENTE) LA REPRESENTACIÓN EXTERIOR MUESTRA: EL CARTÍLAGO NASAL EXTERNO, LA CAVIDAD NASAL, CON LOS SENOS MAXILAR, FRONTAL Y ESFENOIDAL, EL SENO MAXILAR ABIERTO Y CON EL ARCO CIGOMÁTICO RETIRADO. LA REPRESENTACIÓN DEL CORTE MEDIO MUESTRA: LA CAVIDAD NASAL CUBIERTA DE MUCOSA CON LAS CONCHAS NASALES (REMOVIBLES), LAS ARTERIAS DE LA MUCOSA, LOS NERVIOS OLFATIVOS Y LAS INERVACIONES DE LA PARED LATERAL DE LA CAVIDAD NASAL, DE LAS CONCHAS NASALES Y DEL PALADAR', NULL, 8, 2, 'A', 32, '2013-04-22 17:50:49', NULL, NULL, 633, NULL),
('OJO, 5 VECES SU TAMAÑO NATURAL, 6 PIEZAS', 'F10', 29, '<p>DESMONTABLE EN: MITAD SUPERIOR DE LA ESCLER&Oacute;TICA CON C&Oacute;RNEA Y SUJETADORES DEL M&Uacute;SCULO DEL OJO, AMBAS MITADES DE LA COROIDES CON IRIS Y RETINA, LENTES, HUMOR V&Iacute;TREO. MONTADO SOBRE BASE.</p>', NULL, 8, 2, 'A', 32, '2013-04-22 17:51:29', 32, '2013-09-09 17:11:25', 634, '20130909_09f949.pdf'),
('OJO, 5 VECES EL TAMAÑO NATURAL, 7 PIEZAS', 'F11', 29, 'DESMONTABLE EN: MITAD SUPERIOR DE LA ESCLERÓTICA CON CÓRNEA Y SUJETADORES DEL MÚSCULO DEL OJO, AMBAS MITADES DE LA COROIDES CON IRIS Y RETINA, LENTES, HUMOR VÍTREO.\r\nEN UNA BASE DE ÓRBITA ÓSEA.', NULL, 8, 2, 'A', 32, '2013-04-22 17:52:13', NULL, NULL, 635, NULL);
