('OJO, CON PÁRPADO Y SISTEMA LAGRIMAL, 5 VECES SU TAMAÑO NATURAL, 8 PIEZAS', 'F12', 29, 'DESMONTABLE EN: MITAD SUPERIOR DE LA ESCLERÓTICA CON CÓRNEA Y SUJETADORES DEL MÚSCULO DEL OJO, AMBAS MITADES DE LA COROIDES CON IRIS Y RETINA, LENTES, HUMOR VÍTREO. \r\nCON EL SISTEMA LAGRIMAL, SOBRE BASE DE ÓRBITA ÓSEA.', NULL, 8, 2, 'A', 32, '2013-04-22 17:52:59', NULL, NULL, 636, NULL),
('OJO, 3 VECES SU TAMAÑO NATURAL, 7 PIEZAS', 'F13', 29, 'ESTE MODELO ES DESMONTABLE EN: AMBAS MITADES DE LA ESCLERÓTICA CON SUJETADORES DEL MÚSCULO DEL OJO, UNA MITAD DE LA COROIDES CON IRIS Y RETINA, LENTES, HUMOR VÍTREO.\r\nADICIONALMENTE CON EL NERVIO ÓPTICO EN SU POSICIÓN NATURAL EN SU CUENCA (PISO Y PARED MEDIAL).\r\nSOBRE BASE.', NULL, 8, 2, 'A', 32, '2013-04-22 17:53:36', NULL, NULL, 637, NULL),
('OJO, 3 VECES SU TAMAÑO NATURAL, 6 PIEZAS', 'F15', 29, 'ESTE MODELO ES DESMONTABLE EN: AMBAS MITADES DE LA ESCLERÓTICA CON SUJETADORES DEL MÚSCULO DEL OJO, UNA MITAD DE LA COROIDES CON IRIS Y RETINA, LENTES, HUMOR VÍTREO\r\nSOBRE BASE.', NULL, 8, 2, 'A', 32, '2013-04-22 17:54:28', NULL, NULL, 638, NULL),
('3B MICROANATOMY™ OJO', 'F16', 29, '<p>EL MODELO MUESTRA LA DELICADA ESTRUCTURA DE LOS TEJIDOS QUE FORMAN LA RETINA, JUNTO A LA COROIDES Y LA ESCLER&Oacute;TICA. LA PARTE IZQUIERDA DEL MODELO OFRECE LA VISI&Oacute;N, A TRAV&Eacute;S DEL MICROSCOPIO &Oacute;PTICO, DE LA ESTRUCTURA COMPLETA DE LA RETINA CON LA RED DE VASOS DE ABASTECIMIENTO Y PARTE DE LA ESCLER&Oacute;TICA. LA PARTE DERECHA DEL MODELO ES UNA AMPLIACI&Oacute;N DE LA SECCI&Oacute;N. PERMITE OBSERVAR LA FINA DISTRIBUCI&Oacute;N DE LOS FOTO RECEPTORES Y DE LAS C&Eacute;LULAS DEL EPITELIO PIGMENTARIO. PARTE IZQUIERDA AUMENTADA 850 VECES - PARTE DERECHA AUMENTADA 3800 VECES</p>', NULL, 8, 2, 'A', 32, '2013-04-22 17:55:12', 32, '2013-09-09 17:29:02', 639, '20130909_e9470a.pdf'),
('MODELO DE LA LARINGE, 2 VECES SU TAMAÑO NATURAL, 7 PIEZAS', 'G21', 29, 'ESTE MODELO CORTADO MEDIANAMENTE MUESTRA: LARINGE, HUESO HIOIDES, TRÁQUEA, LIGAMENTOS, MÚSCULOS, VASOS, NERVIOS, GLÁNDULA TIROIDES. EL CARTÍLAGO TIROIDEO, 2 MÚSCULOS Y 2 MITADES DE LA GLÁNDULA TIROIDES SON DESMONTABLES. SOBRE BASE.', NULL, 8, 2, 'A', 32, '2013-04-22 17:55:45', NULL, NULL, 640, NULL),
('MODELO FUNCIONAL DE LA LARINGE, 3 VECES SU TAMAÑO', 'VC219', 29, 'CON EPIGLOTIS, CUERDAS VOCALES Y CARTÍLAGO ARITENOIDES DESMONTABLES. SOBRE BASE.', NULL, 8, 2, 'A', 32, '2013-04-22 17:56:26', NULL, NULL, 641, NULL),
('OJO EN ORBITA, 3,5 VECES SU TAMAÑO NATURAL, 8 PIEZAS', 'VJ457', 29, 'ESTE MODELO MUESTRA AL OJO CON EL NERVIO ÓPTICO EN SU POSICIÓN NATURAL EN SU CUENCA (PISO Y PARED MEDIAL). DESMONTABLE EN: AMBAS MITADES DE LA ESCLERÓTICA CON SUJETADORES DEL MÚSCULO DEL OJO, UNA MITAD DE LA COROIDES CON IRIS Y RETINA, LENTES, HUMOR VÍTREO, MÚSCULO RECTO SUPERIOR, MÚSCULO RECTO LATERAL, GLÁNDULA LAGRIMAL.\r\nSOBRE SOPORTE.', NULL, 8, 2, 'A', 32, '2013-04-22 17:57:04', NULL, NULL, 642, NULL),
('OJO, 5 VECES SU TAMAÑO NATURAL, 12 PIEZAS', 'VJ500A', 29, 'ESTE MODELO MUESTRA AL OJO CON EL NERVIO ÓPTICO EN SU POSICIÓN NATURAL EN SU CUENCA (PISO Y PARED MEDIAL). ADEMÁS PERMITEN LAS ESTRUCTURAS ASOCIADAS COMPRENDER MEJOR LA RELACIÓN ENTRE EL OJO, EL HUESO, LOS MÚSCULOS Y LAS ESTRUCTURAS DEL OJO. DESMONTABLE EN: DOS MITADES DE LA ESCLERÓTICA, NERVIO ÓPTICO, MÚSCULO RECTO SUPERIOR, MÚSCULO RECTO LATERAL, MITAD DE LA CÓRNEA, LENTES, HUMOR VÍTREO, GLÁNDULA LAGRIMAL, ESTRUCTURAS ASOCIADAS Y ÓRBITA ÓSEA', NULL, 8, 2, 'A', 32, '2013-04-22 17:57:36', NULL, NULL, 643, NULL),
('OJO, 5 VECES SU TAMAÑO NATURAL, 6 PIEZAS', 'VJ500C', 29, 'DESMONTABLE EN: MITAD SUPERIOR DE LA ESCLERÓTICA CON INSERCIÓN DEL MÚSCULO DEL OJO, MITAD SUPERIOR DE LA COROIDES CON IRIS Y RETINA, CÓRNEA, LENTES, HUMOR VÍTREO.\r\nSOBRE BASE.', NULL, 8, 2, 'A', 32, '2013-04-22 17:58:12', NULL, NULL, 644, NULL),
('EL OÍDO MÁS GRANDE DEL MUNDO, 15 VECES SU TAMAÑO NATURAL, 3 PIEZAS', 'VJ510', 29, 'CON 15 VECES SU TAMAÑO NATURAL, ESTE OÍDO DE 3 PIEZAS ES APTO PARA AUDITORIOS GRANDES, MUSEOS Y COLECCIONES ESPECIALES. ES UNA REPRESENTACIÓN DEL OÍDO EXTERNO, MEDIO E INTERNO. LOS OSÍCULOS, EL LABERINTO CON NERVIOS COCLEAR Y VESTÍBULO COCLEAR SON DESMONTABLES Y PUEDEN ESTUDIARSE CON DETALLE. MONTADO EN UNA BASE.', NULL, 8, 2, 'A', 32, '2013-04-22 17:58:46', NULL, NULL, 645, NULL),
('OÍDO GIGANTE, 5 VECES SU TAMAÑO NATURAL, 3 PIEZAS', 'VJ513', 29, 'REPRESENTACIÓN DE 5 VECES EL TAMAÑO NATURAL DEL OÍDO PARA VERLO FÁCILMENTE DESDE CUALQUIER LUGAR DEL SALÓN DE CLASES. INCLUYE REPRESENTACIONES DE OÍDO EXTERNO, OÍDO MEDIO, OÍDO INTERNO, OSÍCULOS DESMONTABLES, LABERINTOS CON NERVIO COCLEAR Y VESTIBULOCOCLEAR. SOBRE TABLERO.', NULL, 8, 2, 'A', 32, '2013-04-22 17:59:19', NULL, NULL, 646, NULL),
('OÍDO, 5 VECES SU TAMAÑO NATURAL, 8 PIEZAS', 'W42514', 29, 'LA REPRESENTACIÓN DEL OÍDO EXTERNO, MEDIO E INTERNO. SE PUEDE DESMONTAR: OÍDO EXTERNO, HUESO PETROSO, PROCESO MASTOIDEO, MEMBRANA TIMPÁNICA CON OSÍCULOS, LABERINTO, NERVIO COCLEAR Y VESTÍBULO COCLEAR (3 PIEZAS). LOS CANALES SEMICIRCULARES TRANSPARENTES ESTÁN LLENOS DE FLUIDOS, CADA UNO CON UNA BURBUJA PARA DEMOSTRAR SU FUNCIÓN DE BALANCE. SOBRE TABLERO', NULL, 8, 2, 'A', 32, '2013-04-22 17:59:53', NULL, NULL, 647, NULL),
('CORTE DE LA PIEL, 70 VECES SU TAMAÑO NATURAL', 'J10', 30, 'ESTE RELIEVE MUESTRA UN CORTE A TRAVÉS DE LAS TRES CAPAS DE LA PIEL CUBIERTA DE VELLOS. SE MUESTRA SOBRE BASE: FOLÍCULOS PILOSOS CON LAS GLÁNDULAS SEBÁCEAS, GLÁNDULAS SUDORÍPARAS, RECEPTORES, NERVIOS, VASOS.\r\nVIENE MONTADO EN UN SOPORTE.', NULL, 8, 2, 'A', 32, '2013-04-22 18:01:00', NULL, NULL, 648, NULL),
('CORTE DE LA PIEL, 40 VECES SU TAMAÑO NATURAL', 'J11', 30, '<p>ESTE MODELO DE MESA ES ADECUADO PARA COMPARAR LA PIEL CON VELLOS Y SIN VELLOS. SE MUESTRA LAS TRES CAPAS DE LA PIEL CON FOL&Iacute;CULOS PILOSOS, GL&Aacute;NDULAS SEB&Aacute;CEAS, GL&Aacute;NDULAS SUDOR&Iacute;PARAS, RECEPTOR, NERVIOS Y VASOS SON APRECIADOS. SOBRE BASE.</p>', NULL, 8, 2, 'A', 32, '2013-04-22 18:01:34', 32, '2013-09-09 18:07:55', 649, '20130909_70ed65.pdf'),
('MODELO FUNCIONAL DE LA PIEL', 'J13', 30, 'ESTE MODELO SINGULAR REPRESENTA DE FORMA ESPECIALMENTE IMPRESIONANTE LAS CAPAS Y ESTRUCTURAS DE LA PIEL. ADEMÁS DE LA REPRESENTACIÓN DETALLADA DE LAS DISTINTAS CAPAS, REPRESENTA DE FORMA ILUSTRATIVA EL PELO, LAS RAÍCES DE PELO, LAS GLÁNDULAS SEBÁCEAS Y SUDORÍPARAS ASÍ COMO LOS RECEPTORES, NERVIOS Y VASOS.', NULL, 8, 2, 'A', 32, '2013-04-22 18:02:03', NULL, NULL, 650, NULL),
('CORTE DE LA PIEL', 'J14', 30, 'ESTE MODELO MUESTRA LA ESTRUCTURA MICROSCÓPICA DE LA PIEL CON GRAN DETALLE. CON LA AYUDA DE DIFERENTES CORTES DE LA PIEL SIN VELLOS (POR EJEMPLO, LA PALMA DE LA MANO) Y CON VELLOS (POR EJEMPLO, EL ANTEBRAZO) SE PUEDEN VER LAS DIFERENTES CAPAS CELULARES, COMO TAMBIÉN LAS GLÁNDULAS SUDORÍPARAS INCRUSTADAS, LOS RECEPTORES DE TACTO, LOS VASOS SANGUÍNEOS, LOS NERVIOS Y UN VELLO CON RAÍZ. ADEMÁS, INCLUYE EL MODELO CORTADO DE UNA UÑA EN LA BASE DONDE SE APRECIA LA PLACA UNGUEAL, EL LECHO UNGUEAL Y LA RAÍZ DE LA UÑA. LA REPRESENTACIÓN DE LA RAÍZ DE UN VELLO CON TODAS SU CAPAS CELULARES COMPLETA ESTE MODELO DE LA PIEL.', NULL, 8, 2, 'A', 32, '2013-04-22 18:02:33', NULL, NULL, 651, NULL),
('MODELO DE CÁNCER DE PIEL', 'J15', 30, 'ESTE MODELO DE PATOLOGÍA MUESTRA LA VISIÓN ANTERIOR Y POSTERIOR DE 6 ESTADIOS DIFERENTES DEL CÁNCER MALIGNO DE PIEL AUMENTADOS 8 VECES DE TAMAÑO.\r\nA LA INSPECCIÓN SE PUEDEN RECONOCER EXTERNAMENTE LAS ALTERACIONES CUTÁNEAS VISIBLES QUE PERMITEN UNA VALORACIÓN SEGÚN LOS CRITERIOS “ABCDE“ . A LOS LADOS DEL MODELO ESTÁN SEÑALADAS LAS DIFERENTES PROFUNDIDADES DE INVASIÓN SEGÚN CLARK (I – V) Y BRESLOW (EN MM). CINCO ILUSTRACIONES ORIGINALES EN COLOR MUESTRAN DIVERSAS EXPRESIONES DEL MELANOMA MALIGNO', NULL, 8, 2, 'A', 32, '2013-04-22 18:03:05', 32, '2013-04-22 18:04:14', 652, NULL),
('PELVIS FEMENINA CON LIGAMENTOS, CON SECCIÓN MEDIA SAGITAL A TRAVÉS DE LOS MÚSCULOS DEL PISO PÉLVICO', 'H20/3', 31, '<p>ESTE MODELO DE CUATRO PARTES DE UNA PELVIS FEMENINA PRESENTA INFORMACI&Oacute;N DETALLADA SOBRE LA TOPOGRAF&Iacute;A DE LOS HUESOS, LIGAMENTOS, M&Uacute;SCULOS DEL PISO P&Eacute;LVICO Y &Oacute;RGANOS P&Eacute;LVICOS FEMENINOS. LA MITAD DERECHA DEL MODELO MUESTRA LOS HUESOS CON LOS LIGAMENTOS P&Eacute;LVICOS. ADEM&Aacute;S, LA MITAD IZQUIERDA DE LA PELVIS CONTIENE LOS M&Uacute;SCULOS DEL PISO P&Eacute;LVICO INCLUYENDO EL LEVATOR ANI, EL ISQUIOCAVERNOSO, LOS M&Uacute;SCULOS TRANSVERSOS PROFUNDO Y SUPERFICIAL DEL PERIN&Eacute;, EL ESF&Iacute;NTER ANAL EXTERNO Y EL ESF&Iacute;NTER URETRAL EXTERNO. UN M&Uacute;SCULO BULBOESPONJOSO PARCIALMENTE EXTRA&Iacute;BLE MUESTRA EL BULBO VESTIBULAR Y LA GL&Aacute;NDULA DE BARTHOLIN. LA SECCI&Oacute;N MEDIA SAGITAL EXTRA&Iacute;BLE A TRAV&Eacute;S DE LA VEJIGA URINARIA, VAGINA, &Uacute;TERO Y RECTO MUESTRA LA RELACI&Oacute;N CON LOS M&Uacute;SCULOS DEL PISO P&Eacute;LVICO DENTRO DE SUS ABERTURAS PARA LA URETRA, LA VAGINA Y EL RECTO.</p>', NULL, 8, 2, 'A', 32, '2013-04-22 18:07:13', 32, '2013-09-09 18:23:53', 653, '20130909_0d3bd4.pdf'),
('MODELO DE LOS ESTADIOS DE LA FERTILIZACIÓN Y DESARROLLO DEL EMBRIÓN, A 2 AUMENTOS', 'L01', 31, 'EL MODELO ILUSTRA ESQUEMÁTICAMENTE LA MADURACIÓN DEL ÓVULO, LA OVULACIÓN, LA FECUNDACIÓN Y CÓMO EL ÓVULO FECUNDADO SE DESARROLLA DESDE LA INTEGRACIÓN POR SÍ MISMO EN LA PARED DE LA MATRIZ HASTA EL COMIENZO DEL CRECIMIENTO COMO EMBRIÓN. LOS ESTADIOS DE DESARROLLO SE ENCUENTRAN, POR UNA PARTE, COMO REPRESENTACIÓN AMPLIADA, EN EL OVARIO, LA TROMPA Y EL ÚTERO Y, POR OTRA PARTE, EN OTRA REPRESENTACIÓN GRÁFICA TAMBIÉN AMPLIADA QUE SE ENCUENTRA SOBRE LA BASE DEL MODELO. SE SUMINISTRA CON LA BASE.', NULL, 8, 2, 'A', 32, '2013-04-22 18:07:47', NULL, NULL, 654, NULL),
('SERIE 3B SCIENTIFIC® DE EMBARAZO', 'L10', 31, '8 MODELOS PARA PRESENTAR TODAS LAS ETAPAS DEL DESARROLLO. TODOS LOS MODELOS ESTÁN MONTADOS POR SEPARADO SOBRE UN PEDESTAL.', NULL, 8, 2, 'A', 32, '2013-04-22 18:08:20', NULL, NULL, 655, NULL),
